window.CEKLIST={"surum": "1.12 — 02.11.2026", "sec": {"A": "A. Akreditasyon standardı, zorunlu gerekler ve kapsam", "B": "B. Başvuru, sözleşme ve başvurunun gözden geçirilmesi", "C": "C. Değerlendirme faaliyeti (modüle özgü)", "C1": "C.1 Kalite sistemi dokümantasyonu ve ilk değerlendirme", "C2": "C.2 Tasarım incelemesi", "D": "D. Personel yetkinliği ve kaynaklar", "E": "E. Değerlendirme raporu, gözden geçirme ve karar", "F": "F. Belge / onay kararı içeriği ve işaretleme", "G": "G. Gözetim, değişiklikler, askı ve geri çekme", "H": "H. Kayıtlar, bilgi verme ve koordinasyon"}, "modules": [{"id": "IV-A", "code": "A1", "grup": "aksam", "ad": "Aksam Modül B (Ek IV-A)", "baslik": "EK IV KISIM A — GÜVENLİK AKSAMLARI İÇİN AB TİP İNCELEMESİ (MODÜL B)", "ozet": [["Ürün", "Güvenlik aksamları (Ek III/1–6: kat kapısı kilitleri, güvenlik tertibatı (paraşüt), hız regülatörü, tamponlar, kabin yukarı aşırı hız ve UCM önleme tertibatları, elektronik içeren elektrikli güvenlik tertibatları/PESSRAL, hidrolik boru kopma valfi)"], ["Direktif dayanağı", "Md. 15(a) ve 15(b) — tasarım aşaması; üretim aşaması için Ek IX (C2) veya Ek VI (E) ile birlikte"], ["Başvuran / OK çıktısı", "İmalatçı veya yetkili temsilcisi / AB tip inceleme belgesi ve ekleri"], ["Akreditasyon (EA-2/17 M:2026)", "EN ISO/IEC 17065 · zorunlu gerekler cd + pk + t · kabul edilmeyen: 17021-1, 17024, 17025, 17029"], ["Tanık gruplaması", "Tablo 2: B ← B* veya G veya H1. G ve H1 asansör modülleridir; aksam tasarım yetkinliğini tek başına kanıtlamaz — aksam türü bazında dosya incelemesi + teknik mülakat önerilir"], ["Saklama süreleri", "OK: belge, ekler, teknik dosya ve değerlendirme raporu 15 yıl (md. 5) · İmalatçı: 10 yıl (md. 10)"]], "items": [{"no": "A.1", "sec": "A", "t": "Kuruluş bu modül (Ek IV Kısım A) için EN ISO/IEC 17065 esas alınarak akredite edilmiş/denetleniyor mu? Farklı bir standart kullanılıyorsa bildirim otoritesinin yayımlanmış bağlayıcı gerekliliğine dayanan gerekçe AK tarafından kayda alınmış mı?", "d": "EA-2/17 M:2026 §4.2, Annex A Tablo 1", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "A.2", "sec": "A", "t": "Bu modül için kabul edilmeyen standartlar (ISO/IEC 17021-1, 17024, 17025, 17029) akreditasyon dayanağı olarak kullanılmıyor.", "d": "EA-2/17 M:2026 Annex A Tablo 1", "k": "Kayıt incelemesi"}, {"no": "A.3", "sec": "A", "t": "'cd' gerekliliği: EN ISO/IEC 17065 md. 4.1.2, 4.1.3, 7.5 ve 7.6'nın (belgelendirme anlaşması, belge/işaret kullanımı, gözden geçirme ve karar) bu modül için ayrıca kanıtlandığı doğrulanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (cd)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "A.4", "sec": "A", "t": "'pk' gerekliliği: ürün bilgisine dayalı mesleki yargı — EN ISO/IEC 17020 md. 6.1.2, 6.1.3 ve 6.1.6–6.1.10 (yetkinlik kriterleri, görevlendirme, eğitim, gözetim, saha izleme, kayıtlar) bu modülün personeli için kanıtlanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (pk)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "A.5", "sec": "A", "t": "'t' gerekliliği: OK deneyleri kendisi yapıyorsa EN ISO/IEC 17025 md. 6 ve 7 (7.9 hariç) karşılanmalı; deneyler dış laboratuvarda yapılıyorsa Md. 26 kapsamında alt yüklenici değerlendirmesi aranmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (t); 2014/33/AB Md. 26", "k": "Prosedür incelemesi + Kayıt incelemesi + Tanık denetimi"}, {"no": "A.6", "sec": "A", "t": "Kapsam ifadesi: Direktif (2014/33/AB), ek ve modül (Ek IV Kısım A) ile ürün kapsamı (Ek III aksam türleri ayrı ayrı) açıkça yazılmış; NANDO'ya veri girişine uygun.", "d": "EA-2/17 M:2026 §5; ISO/IEC 17011 md. 7.8", "k": "Kayıt incelemesi"}, {"no": "A.7", "sec": "A", "t": "Akreditasyon kapsamı ile bildirim (NANDO) kapsamı tutarlı; bildirim dışı bir modül/ürün için belge düzenlenmemiş.", "d": "2014/33/AB Md. 28(3), Md. 32(1)", "k": "Kayıt incelemesi + Dosya örneklemesi"}, {"no": "A.8", "sec": "A", "t": "Tanık denetimi planı: aksam türleri (kilit, paraşüt, regülatör, tampon, UCMP/ACOP, PESSRAL, boru kopma valfi) için kapsam döngüsünde en az bir tip deneyinin yerinde izlenmesi veya gerekçeli dosya incelemesi + teknik mülakat planlanmış mı?", "d": "EA-2/17 M:2026 Annex B Tablo 2", "k": "Kayıt incelemesi"}, {"no": "A.9", "sec": "A", "t": "İlk akreditasyonda tanık denetimi ertelendiyse 18 ay içinde tamamlandığı ve tanık öncesi akredite belge düzenlenmediği doğrulanmış.", "d": "EA-2/17 M:2026 Annex B (18 ay kuralı)", "k": "Kayıt incelemesi"}, {"no": "B.1", "sec": "B", "t": "Başvuru imalatçı veya yetkili temsilcisi tarafından yapılıyor; yetkili temsilci başvurularında vekâletnamenin ilgili yükümlülükleri açıkça kapsadığı kontrol ediliyor.", "d": "Ek IV-A md. 2, 11 (yetkili temsilci maddesi)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.2", "sec": "B", "t": "Başvuruda aynı başvurunun başka bir onaylanmış kuruluşa yapılmadığına dair yazılı beyan bulunuyor.", "d": "Ek IV-A md. 2, 11 — tek OK beyanı", "k": "Dosya örneklemesi"}, {"no": "B.3", "sec": "B", "t": "Başvuru dosyası Direktifin istediği tüm unsurları içeriyor: (a) imalatçının ve varsa yetkili temsilcinin adı/adresi ile imalat yeri, (b) tek OK beyanı, (c) teknik dosya, (d) temsilî numune veya incelenebileceği yer, (e) tasarım çözümünün yeterliliğine ilişkin destekleyici kanıt.", "d": "Ek IV-A md. 2, 11", "k": "Dosya örneklemesi"}, {"no": "B.4", "sec": "B", "t": "Başvurunun gözden geçirilmesinde kapsam (NANDO), yetkinlik ve kaynak yeterliliği ile tarafsızlık riski değerlendiriliyor ve kayda alınıyor.", "d": "ISO/IEC 17065 md. 7.3 / ISO/IEC 17021-1 md. 9.1.2; Md. 24(6)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.5", "sec": "B", "t": "Müşteri sözleşmesinde OK'nın ve akreditasyon kuruluşunun (tanık denetimi için) tesislere, sahalara ve kayıtlara erişim hakkı açıkça yazılı.", "d": "ISO/IEC 17065 md. 4.1.2; iyi uygulama: AA L05 §1.3", "k": "Dosya örneklemesi"}, {"no": "B.6", "sec": "B", "t": "Alt yüklenici veya bağlı kuruluş kullanılacaksa müşterinin onayı alınmış.", "d": "2014/33/AB Md. 26(3)", "k": "Dosya örneklemesi"}, {"no": "B.7", "sec": "B", "t": "Orantılılık: değerlendirme planı işletmenin büyüklüğü, yapısı, teknolojinin karmaşıklığı ve üretimin seri/kütle niteliği dikkate alınarak hazırlanmış; ancak koruma düzeyinden taviz verilmemiş.", "d": "2014/33/AB Md. 24(6)(c), Md. 32(2)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.8", "sec": "B", "t": "OK deney programı için ek numune talep edebildiğini prosedüründe tanımlamış; numunelerin kimliklendirilmesi ve muhafazası kayıt altında.", "d": "Ek IV-A md. 2(d); ISO/IEC 17065 md. 7.4", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C.1", "sec": "C", "t": "Teknik dosya, aksamın md. 1'deki koşulları karşılayıp karşılamadığını değerlendirmeye imkân veriyor ve yeterli risk analizi ve değerlendirmesi içeriyor; OK risk değerlendirmesinin yeterliliğini incelemiş.", "d": "Ek IV-A md. 3 (giriş); NB-L RfU 0/007", "k": "Dosya örneklemesi"}, {"no": "C.2", "sec": "C", "t": "Md. 3(a)–(h) bütünlüğü kontrol ediliyor: tanım ve kullanım alanı, çizimler/şemalar, açıklamalar, standart listesi, tasarım hesapları, deney raporları, talimat kopyası, seri üretim tedbirleri.", "d": "Ek IV-A md. 3(a)–(h)", "k": "Dosya örneklemesi"}, {"no": "C.3", "sec": "C", "t": "Kullanım alanı sınırları (özellikle hız, yük ve güç) ve ortam koşulları (özellikle patlayıcı ortam ve dış etkenler) teknik dosyada tanımlı ve değerlendirmede dikkate alınmış.", "d": "Ek IV-A md. 3(a)", "k": "Dosya örneklemesi"}, {"no": "C.4", "sec": "C", "t": "Kısmen uygulanan uyumlaştırılmış standartlarda uygulanan bölümler belirtilmiş; standart dışı çözümler için başvurulan diğer teknik şartnameler listelenmiş.", "d": "Ek IV-A md. 3(d), 2(e)", "k": "Dosya örneklemesi"}, {"no": "C.5", "sec": "C", "t": "Destekleyici kanıt kapsamındaki imalatçı/laboratuvar deney sonuçlarının güvenilirliği (yöntem, ekipman, yetkinlik) OK tarafından değerlendirilmiş.", "d": "Ek IV-A md. 2(e)", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C.6", "sec": "C", "t": "Md. 3(h) seri üretim tedbirleri (üretim kontrolü, ayar ve son deney yöntemi, izlenebilirlik) dokümanter olarak incelenmiş.", "d": "Ek IV-A md. 3(h)", "k": "Dosya örneklemesi"}, {"no": "C.7", "sec": "C", "t": "Muayene ve deneylerin yapılacağı yer başvuranla kararlaştırılmış ve kayda alınmış.", "d": "Ek IV-A md. 4(b)", "k": "Dosya örneklemesi"}, {"no": "C.8", "sec": "C", "t": "Numunenin teknik dosyaya uygun imal edildiği doğrulanmış; uyumlaştırılmış standarda göre tasarlanan unsurlar ile diğer teknik şartnamelere göre tasarlananlar ayrı ayrı tanımlanmış.", "d": "Ek IV-A md. 4(c)", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C.9", "sec": "C", "t": "Uyumlaştırılmış standart uygulandığında tip deneyleri standarttaki yönteme göre yapılıyor (EN 81-50:2014 md. 5.2–5.9 / AB RG'de atıf durumuna göre EN ISO 8100-2).", "d": "Ek IV-A md. 4(d); NB-L RfU 1/001", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C.10", "sec": "C", "t": "Standart uygulanmayan çözümler için OK kendi analizini ve uygun deneyleri yapmış; aksamın doğru monte edildiği asansörün TSGG'yi karşılamasını sağlayacağı gerekçelendirilmiş.", "d": "Ek IV-A md. 4(e), md. 1", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C.11", "sec": "C", "t": "Elektrikli güvenlik tertibatlarında Ek III/6 kapsamı doğru belirleniyor (elektronik içeren tasarım ayrımı); kapsam dışı tasarımlar için tip incelemesi gereksiz yere yapılmıyor ya da tersine atlanmıyor.", "d": "NB-L RfU 1/005", "k": "Dosya örneklemesi"}, {"no": "C.12", "sec": "C", "t": "UCM önleme tertibatlarında algılama, tetikleme ve durdurma işlevlerinin tek bir tertibatla mı yoksa kombinasyonla mı sağlandığı belirleniyor ve belgeye yansıtılıyor.", "d": "NB-L RfU 1/008", "k": "Dosya örneklemesi"}, {"no": "C.13", "sec": "C", "t": "PESSRAL aksamlarında ömür, görev süresi, kanıt deneyi aralığı gibi güvenliği etkileyen ölçütler belgede veya ekinde belirtiliyor.", "d": "NB-L RfU 1/014", "k": "Dosya örneklemesi"}, {"no": "C.14", "sec": "C", "t": "Deney ekipmanı (kuvvet, hız, mesafe, zaman, basınç ölçümü) kalibreli ve izlenebilir; ölçüm belirsizliği karar kuralında dikkate alınmış.", "d": "EA-2/17 Annex A (t): ISO/IEC 17025 md. 6.4, 6.5, 7.6", "k": "Kayıt incelemesi + Tanık denetimi"}, {"no": "C.15", "sec": "C", "t": "Deneyler dış laboratuvarda yapılıyorsa laboratuvarın Md. 24 şartlarını karşıladığı değerlendirilmiş, bildirim otoritesine bilgi verilmiş, sorumluluk OK'da kalmış.", "d": "2014/33/AB Md. 26(1), 26(2), 26(4); ISO/IEC 17065 md. 6.2.2", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "D.1", "sec": "D", "t": "Değerlendirme personeli her aksam türü için tanımlı yetkinlik kriterlerine göre yetkilendirilmiş (Ek I, EN 81-20/50 veya EN ISO 8100-1/-2, ilgili RfU'lar).", "d": "Md. 24(7)(a)–(c); ISO/IEC 17020 md. 6.1.2–6.1.3 (pk)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "D.2", "sec": "D", "t": "Deney yapan personelin deney yöntemlerine ilişkin yetkinliği ve izlenmesi kayıtlı.", "d": "ISO/IEC 17025 md. 6.2 (t)", "k": "Kayıt incelemesi + Tanık denetimi"}, {"no": "E.1", "sec": "E", "t": "Değerlendirme raporu (Ek IV-A md. 4 son paragraf) yapılan inceleme, doğrulama ve deneyleri ve sonuçlarını kanıtlarla birlikte kaydediyor.", "d": "2014/33/AB Md. 24(7)(d)", "k": "Dosya örneklemesi"}, {"no": "E.2", "sec": "E", "t": "Gözden geçirme ve belgelendirme kararı, değerlendirmeyi yapmamış yetkin kişi(ler)ce veriliyor; karar kaydı tarihli ve imzalı.", "d": "ISO/IEC 17065 md. 7.5, 7.6 (cd) / ISO/IEC 17021-1 md. 9.5", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "E.3", "sec": "E", "t": "TSGG veya uyumlaştırılmış standartlar/diğer teknik şartnameler karşılanmadığında düzeltici faaliyet isteniyor ve belge düzenlenmiyor.", "d": "2014/33/AB Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "E.4", "sec": "E", "t": "Ret kararında ayrıntılı gerekçe başvurana yazılı bildiriliyor.", "d": "2014/33/AB ilgili ek; Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "E.5", "sec": "E", "t": "OK kararlarına karşı itiraz prosedürü mevcut, müşteriye duyuruluyor ve itirazlar kararı verenden bağımsız kişilerce ele alınıyor.", "d": "2014/33/AB Md. 33; ISO/IEC 17065 md. 7.13", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "E.6", "sec": "E", "t": "Değerlendirme raporunun içeriği yalnız imalatçının onayıyla (bildirim otoritesine karşı yükümlülükler saklı) açıklanıyor.", "d": "Ek IV-A md. 4 son paragraf", "k": "Prosedür incelemesi"}, {"no": "F.1", "sec": "F", "t": "Belge imalatçının adı ve adresini, inceleme sonuçlarını, geçerlilik koşullarını ve onaylı tipi tanımlamaya yarayan bilgileri içeriyor.", "d": "Ek IV-A md. 5", "k": "Dosya örneklemesi"}, {"no": "F.2", "sec": "F", "t": "Belge ve ekleri, imal edilen aksamların tipe uygunluğunun değerlendirilmesine ve işletmedeki kontrolüne (in-service control) imkân verecek tüm bilgileri içeriyor (ayar değerleri, kullanım sınırları, montaj koşulları, işaretleme).", "d": "Ek IV-A md. 5; NB-L RfU 1/002", "k": "Dosya örneklemesi"}, {"no": "F.3", "sec": "F", "t": "Belge yapısı EN 81-50 Ek A model formu veya eşdeğeri esas alınarak hazırlanmış; aksam türüne özgü içerik bulunuyor.", "d": "NB-L RfU 1/002", "k": "Dosya örneklemesi"}, {"no": "F.4", "sec": "F", "t": "Belgede/ekte, tasarım aşaması belgesinin üretim aşamasında Ek VI veya Ek IX ile tamamlanması gerektiği ve CE işareti yanında bulunacak OK numarasının üretim modülü OK'sına ait olduğu açıklanıyor (iyi uygulama).", "d": "Md. 15, Md. 19(3); Ek VI md. 5.1, Ek IX md. 5.1", "k": "Dosya örneklemesi"}, {"no": "G.1", "sec": "G", "t": "OK genel kabul görmüş tekniğin gelişimini izliyor; onaylı tipin artık şartları karşılamayabileceğini gösteren değişikliklerde ek inceleme gerekip gerekmediğine karar verip imalatçıyı bilgilendiriyor.", "d": "Ek IV-A md. 6", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "G.2", "sec": "G", "t": "Uyumlaştırılmış standart revizyonlarında (ör. EN 81-50 → EN ISO 8100-2) mevcut belgelerin gözden geçirilmesi planlanmış ve kayıt altında.", "d": "Ek IV-A md. 6; NB-L RfU 2/028", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "G.3", "sec": "G", "t": "İmalatçının tip değişikliği bildirimleri inceleniyor; belgenin geçerliliği, ek inceleme ihtiyacı, belgeye ilave veya yeni başvuru kararı gerekçeli veriliyor.", "d": "Ek IV-A md. 7", "k": "Dosya örneklemesi"}, {"no": "G.4", "sec": "G", "t": "Belgenin askıya alınması, kısıtlanması veya geri çekilmesi için kriterler ve süreç tanımlı ve uygulanıyor.", "d": "Md. 32(4), 32(5); ISO/IEC 17065 md. 7.11", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "H.1", "sec": "H", "t": "Kayıt saklama: belge, ekleri ve ilaveleri ile teknik dosya ve değerlendirme raporu belge tarihinden itibaren 15 yıl saklanıyor.", "d": "2014/33/AB ilgili ek; ISO/IEC 17065 md. 7.12 / 17021-1 md. 9.9 / 17020 md. 7.3, 8.4", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "H.2", "sec": "H", "t": "Bildirim otoritesine verilen/geri çekilen belgeler (onaylar) bildiriliyor; reddedilen, askıya alınan veya kısıtlanan belgelerin listesi periyodik olarak veya talep üzerine sunuluyor.", "d": "Ek IV-A md. 8, 9; Md. 34(1)", "k": "Kayıt incelemesi"}, {"no": "H.3", "sec": "H", "t": "Diğer onaylanmış kuruluşlara reddedilen, askıya alınan, geri çekilen veya kısıtlanan belgeler bildiriliyor; talep hâlinde verilen belgeler hakkında bilgi veriliyor.", "d": "Ek IV-A md. 8, 9; Md. 34(2)", "k": "Kayıt incelemesi"}, {"no": "H.4", "sec": "H", "t": "Komisyon ve üye devletlerin talebi hâlinde belge kopyası (ve ilgili eklerde öngörüldüğünde teknik dosya/rapor) verilebiliyor; prosedürde tanımlı.", "d": "Ek IV-A md. 8, 9", "k": "Prosedür incelemesi"}, {"no": "H.5", "sec": "H", "t": "Ekonomik operatörün saklama yükümlülüğü (aksamın piyasaya arzından sonra 10 yıl — Ek IV-A md. 10) belge/sözleşme ekinde veya bilgilendirme notunda müşteriye bildiriliyor.", "d": "2014/33/AB ilgili ek (iyi uygulama)", "k": "Dosya örneklemesi"}, {"no": "H.6", "sec": "H", "t": "Gizlilik: değerlendirme sırasında elde edilen bilgiler yalnız yetkili makamlarla paylaşılıyor; mülkiyet hakları korunuyor.", "d": "2014/33/AB Md. 24(10)", "k": "Prosedür incelemesi + Mülakat"}, {"no": "H.7", "sec": "H", "t": "OK, NB-L Koordinasyon Grubu çalışmalarına katılıyor veya personeli bilgilendiriliyor; tasdik edilmiş RfU'ların (Temmuz 2026 derlemesi) bu modüle ilişkin olanları prosedürlere işlenmiş.", "d": "2014/33/AB Md. 24(11), Md. 36; NB-L RfU 16.07.2026", "k": "Prosedür incelemesi + Kayıt incelemesi + Mülakat"}], "tanik": {"faaliyet": "Aksam tip deneyi (laboratuvar) — aksam türü bazında", "grup": "B* veya G veya H1", "not": "Aksam ve asansör ürün kategorileri önemli ölçüde farklı; G/H1 ile gruplama aksam tasarım yetkinliğini kanıtlamaz. Dosya incelemesi + teknik mülakat önerilir."}, "yon": "asansor"}, {"id": "IX", "code": "A2", "grup": "aksam", "ad": "Aksam Modül C2 (Ek IX)", "baslik": "EK IX — GÜVENLİK AKSAMLARI İÇİN RASTGELE KONTROLLÜ TİPE UYGUNLUK (MODÜL C2)", "ozet": [["Ürün", "AB tip inceleme belgesi (Ek IV-A) bulunan güvenlik aksamları"], ["Direktif dayanağı", "Md. 15(a) — Ek IV-A + Ek IX"], ["Başvuran / OK çıktısı", "İmalatçı (md. 2 yükümlülüğü yetkili temsilciye devredilemez) / tipe uygunluk belgesi; OK numarası her aksamda CE yanında"], ["Akreditasyon (EA-2/17 M:2026)", "EN ISO/IEC 17065 · cd + pk + t · kabul edilmeyen: 17021-1, 17024, 17029"], ["Tanık gruplaması", "Tablo 2: C2 ← C1 veya C2 veya A1 veya A2 veya B* veya F veya G — numune alma + deney gözlemi önerilir"], ["Saklama süreleri", "OK: Direktifte süre yok (ISO/IEC 17065 md. 7.12 kayıt politikası; en az 10 yıl önerilir) · İmalatçı: AB uygunluk beyanı 10 yıl (md. 5.2)"]], "items": [{"no": "A.1", "sec": "A", "t": "Kuruluş bu modül (Ek IX) için EN ISO/IEC 17065 esas alınarak akredite edilmiş/denetleniyor mu? Farklı bir standart kullanılıyorsa bildirim otoritesinin yayımlanmış bağlayıcı gerekliliğine dayanan gerekçe AK tarafından kayda alınmış mı?", "d": "EA-2/17 M:2026 §4.2, Annex A Tablo 1", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "A.2", "sec": "A", "t": "Bu modül için kabul edilmeyen standartlar (ISO/IEC 17021-1, 17024, 17029) akreditasyon dayanağı olarak kullanılmıyor.", "d": "EA-2/17 M:2026 Annex A Tablo 1", "k": "Kayıt incelemesi"}, {"no": "A.3", "sec": "A", "t": "'cd' gerekliliği: EN ISO/IEC 17065 md. 4.1.2, 4.1.3, 7.5 ve 7.6'nın (belgelendirme anlaşması, belge/işaret kullanımı, gözden geçirme ve karar) bu modül için ayrıca kanıtlandığı doğrulanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (cd)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "A.4", "sec": "A", "t": "'pk' gerekliliği: ürün bilgisine dayalı mesleki yargı — EN ISO/IEC 17020 md. 6.1.2, 6.1.3 ve 6.1.6–6.1.10 (yetkinlik kriterleri, görevlendirme, eğitim, gözetim, saha izleme, kayıtlar) bu modülün personeli için kanıtlanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (pk)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "A.5", "sec": "A", "t": "'t' gerekliliği: OK deneyleri kendisi yapıyorsa EN ISO/IEC 17025 md. 6 ve 7 (7.9 hariç) karşılanmalı; deneyler dış laboratuvarda yapılıyorsa Md. 26 kapsamında alt yüklenici değerlendirmesi aranmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (t); 2014/33/AB Md. 26", "k": "Prosedür incelemesi + Kayıt incelemesi + Tanık denetimi"}, {"no": "A.6", "sec": "A", "t": "Kapsam ifadesi: Direktif (2014/33/AB), ek ve modül (Ek IX) ile ürün kapsamı (Ek III aksam türleri) açıkça yazılmış; NANDO'ya veri girişine uygun.", "d": "EA-2/17 M:2026 §5; ISO/IEC 17011 md. 7.8", "k": "Kayıt incelemesi"}, {"no": "A.7", "sec": "A", "t": "Akreditasyon kapsamı ile bildirim (NANDO) kapsamı tutarlı; bildirim dışı bir modül/ürün için belge düzenlenmemiş.", "d": "2014/33/AB Md. 28(3), Md. 32(1)", "k": "Kayıt incelemesi + Dosya örneklemesi"}, {"no": "A.8", "sec": "A", "t": "Tanık denetimi planı: kapsam döngüsünde en az bir rastgele kontrolde OK'nın sahada numune alması ve deneyi izlenmiş mi (veya Tablo 2 gruplamasına göre gerekçelendirilmiş mi)?", "d": "EA-2/17 M:2026 Annex B Tablo 2", "k": "Kayıt incelemesi"}, {"no": "A.9", "sec": "A", "t": "İlk akreditasyonda tanık denetimi ertelendiyse 18 ay içinde tamamlandığı ve tanık öncesi akredite belge düzenlenmediği doğrulanmış.", "d": "EA-2/17 M:2026 Annex B (18 ay kuralı)", "k": "Kayıt incelemesi"}, {"no": "B.1", "sec": "B", "t": "Başvuru imalatçı veya yetkili temsilcisi tarafından yapılıyor; yetkili temsilci başvurularında vekâletnamenin ilgili yükümlülükleri açıkça kapsadığı kontrol ediliyor.", "d": "Ek IX md. 3, 6 (yetkili temsilci maddesi)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.2", "sec": "B", "t": "Başvuruda aynı başvurunun başka bir onaylanmış kuruluşa yapılmadığına dair yazılı beyan bulunuyor.", "d": "Ek IX md. 3, 6 — tek OK beyanı", "k": "Dosya örneklemesi"}, {"no": "B.3", "sec": "B", "t": "Başvuru dosyası Direktifin istediği tüm unsurları içeriyor: (a) imalatçının ve varsa yetkili temsilcinin adı/adresi, (b) tek OK beyanı, (c) imal edilen aksamlara ilişkin tüm ilgili bilgiler, (d) numunenin alınabileceği tesisin adresi.", "d": "Ek IX md. 3, 6", "k": "Dosya örneklemesi"}, {"no": "B.4", "sec": "B", "t": "Başvurunun gözden geçirilmesinde kapsam (NANDO), yetkinlik ve kaynak yeterliliği ile tarafsızlık riski değerlendiriliyor ve kayda alınıyor.", "d": "ISO/IEC 17065 md. 7.3 / ISO/IEC 17021-1 md. 9.1.2; Md. 24(6)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.5", "sec": "B", "t": "Müşteri sözleşmesinde OK'nın ve akreditasyon kuruluşunun (tanık denetimi için) tesislere, sahalara ve kayıtlara erişim hakkı açıkça yazılı.", "d": "ISO/IEC 17065 md. 4.1.2; iyi uygulama: AA L05 §1.3", "k": "Dosya örneklemesi"}, {"no": "B.6", "sec": "B", "t": "Alt yüklenici veya bağlı kuruluş kullanılacaksa müşterinin onayı alınmış.", "d": "2014/33/AB Md. 26(3)", "k": "Dosya örneklemesi"}, {"no": "B.7", "sec": "B", "t": "Orantılılık: değerlendirme planı işletmenin büyüklüğü, yapısı, teknolojinin karmaşıklığı ve üretimin seri/kütle niteliği dikkate alınarak hazırlanmış; ancak koruma düzeyinden taviz verilmemiş.", "d": "2014/33/AB Md. 24(6)(c), Md. 32(2)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.8", "sec": "B", "t": "Dayanak AB tip inceleme belgesinin (ve eklerinin) geçerliliği ve kapsamı doğrulanıyor; belge başka OK'ya aitse belge ve ekleri temin edilmiş.", "d": "Ek IX md. 1; Ek IV-A md. 5", "k": "Dosya örneklemesi"}, {"no": "B.9", "sec": "B", "t": "Yetkili temsilcinin md. 2 (imalat sürecinin ve izlenmesinin uygunluğu) yükümlülüğünü üstlenmediği kontrol ediliyor.", "d": "Ek IX md. 6", "k": "Dosya örneklemesi"}, {"no": "C.1", "sec": "C", "t": "Rastgele kontrol aralıkları imalatçı tarafından öngörülemeyecek şekilde planlanıyor; aralığın belirlenmesinde üretim hacmi, aksamın riski ve önceki sonuçlar kullanılıyor; plan kayıtlı.", "d": "Ek IX md. 4", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "C.2", "sec": "C", "t": "Nihai ürünlerden yeterli büyüklükte numune sahada OK tarafından alınıyor (imalatçı seçmiyor); numune büyüklüğünün yeterliliği gerekçelendirilmiş.", "d": "Ek IX md. 4", "k": "Prosedür incelemesi + Dosya örneklemesi + Tanık denetimi"}, {"no": "C.3", "sec": "C", "t": "Numunelerin kimliklendirilmesi, mühürlenmesi, taşınması ve muhafazası güvence altına alınıyor.", "d": "ISO/IEC 17065 md. 7.4; ISO/IEC 17025 md. 7.4 (t)", "k": "Prosedür incelemesi + Tanık denetimi"}, {"no": "C.4", "sec": "C", "t": "Kontroller, AB tip inceleme belgesi ve eklerindeki tip tanımına göre yapılıyor (boyutlar, malzeme, ayar değerleri, işaretleme, tip etiketi, yazılım sürümü vb.).", "d": "Ek IX md. 1, 4", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C.5", "sec": "C", "t": "Uyumlaştırılmış standartlarda öngörülen deneyler ve/veya diğer teknik şartnamelerdeki eşdeğer deneyler uygulanıyor; deney yöntemi kayıtlı.", "d": "Ek IX md. 4", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C.6", "sec": "C", "t": "Kontrol edilecek noktalar onaylanmış kuruluşların ortak mutabakatıyla (aksamın temel özellikleri dikkate alınarak) belirlenmiş noktalarla uyumlu; ortak doküman yoksa OK'nın gerekçeli kontrol listesi var.", "d": "Ek IX md. 4 (3. paragraf); Md. 36", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C.7", "sec": "C", "t": "Numunelerden biri veya birkaçı uygunsuz çıktığında alınacak 'uygun önlemler' tanımlı (ek numune, sıklığın artırılması, imalatçıdan düzeltici faaliyet, belgenin askıya alınması, gerekirse makamlara bilgi) ve uygulanmış.", "d": "Ek IX md. 4; Md. 32(4)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C.8", "sec": "C", "t": "C2'nin kalite sistemi modülü olmadığı, ancak imalatçının imalat süreci ve izleme tedbirlerinin (md. 2) bilgi olarak alındığı ve kontrol planına yansıtıldığı doğrulanıyor.", "d": "Ek IX md. 2, 3(c)", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C.9", "sec": "C", "t": "Deney ekipmanı kalibreli ve izlenebilir; deney imalatçı tesisinde imalatçı ekipmanıyla yapılıyorsa ekipmanın yeterliliği OK tarafından doğrulanmış.", "d": "ISO/IEC 17025 md. 6.4, 6.5 (t); ISO/IEC 17065 md. 6.2", "k": "Kayıt incelemesi + Tanık denetimi"}, {"no": "C.10", "sec": "C", "t": "Deneyler dış laboratuvarda yapılıyorsa Md. 26 şartları sağlanmış.", "d": "2014/33/AB Md. 26", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "D.1", "sec": "D", "t": "Numune alma ve deney personelinin aksam türüne özgü teknik bilgisi ve yetkilendirmesi kayıtlı.", "d": "Md. 24(7); ISO/IEC 17020 md. 6.1.2–6.1.3 (pk)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "E.1", "sec": "E", "t": "Rastgele kontrol raporu yapılan inceleme, doğrulama ve deneyleri ve sonuçlarını kanıtlarla birlikte kaydediyor.", "d": "2014/33/AB Md. 24(7)(d)", "k": "Dosya örneklemesi"}, {"no": "E.2", "sec": "E", "t": "Gözden geçirme ve belgelendirme kararı, değerlendirmeyi yapmamış yetkin kişi(ler)ce veriliyor; karar kaydı tarihli ve imzalı.", "d": "ISO/IEC 17065 md. 7.5, 7.6 (cd) / ISO/IEC 17021-1 md. 9.5", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "E.3", "sec": "E", "t": "TSGG veya uyumlaştırılmış standartlar/diğer teknik şartnameler karşılanmadığında düzeltici faaliyet isteniyor ve belge düzenlenmiyor.", "d": "2014/33/AB Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "E.4", "sec": "E", "t": "Ret kararında ayrıntılı gerekçe başvurana yazılı bildiriliyor.", "d": "2014/33/AB ilgili ek; Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "E.5", "sec": "E", "t": "OK kararlarına karşı itiraz prosedürü mevcut, müşteriye duyuruluyor ve itirazlar kararı verenden bağımsız kişilerce ele alınıyor.", "d": "2014/33/AB Md. 33; ISO/IEC 17065 md. 7.13", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "F.1", "sec": "F", "t": "Yapılan inceleme ve deneylere ilişkin tipe uygunluk belgesi düzenleniyor; belge dayanak AB tip inceleme belgesine, incelenen numunelere ve sonuçlara atıf yapıyor.", "d": "Ek IX md. 4 (4. paragraf)", "k": "Dosya örneklemesi"}, {"no": "F.2", "sec": "F", "t": "İmalatçının, OK'nın sorumluluğunda, uygun her aksama CE işareti ve OK kimlik numarasını iliştirmesi için kurallar tanımlı; OK numarasının yetkisiz kullanımı izleniyor.", "d": "Ek IX md. 5.1; Md. 19(3); ISO/IEC 17065 md. 4.1.3 (cd)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "F.3", "sec": "F", "t": "AB uygunluk beyanının imalatçı tarafından düzenlendiği ve OK'nın beyan düzenlemediği netleştirilmiş.", "d": "Ek IX md. 5.2", "k": "Dosya örneklemesi"}, {"no": "G.1", "sec": "G", "t": "Rastgele kontrollerin sürekliliği izleniyor; plan dışı gecikmeler kayda alınıyor ve gerekçelendiriliyor.", "d": "Ek IX md. 4", "k": "Kayıt incelemesi"}, {"no": "G.2", "sec": "G", "t": "Dayanak AB tip inceleme belgesinin değişmesi, askıya alınması veya geri çekilmesi hâlinde C2 belgesinin durumu değerlendiriliyor.", "d": "Ek IV-A md. 7; Ek IX md. 1", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "G.3", "sec": "G", "t": "Belgenin askıya alınması, kısıtlanması veya geri çekilmesi süreci tanımlı ve uygulanıyor.", "d": "Md. 32(4), 32(5); ISO/IEC 17065 md. 7.11", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "H.1", "sec": "H", "t": "Kayıt saklama: Direktif C2 için OK saklama süresi öngörmüyor; kayıtların en az ekonomik operatörün 10 yıllık süresini kapsayacak şekilde saklanması önerilir.", "d": "2014/33/AB ilgili ek; ISO/IEC 17065 md. 7.12 / 17021-1 md. 9.9 / 17020 md. 7.3, 8.4", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "H.2", "sec": "H", "t": "Bildirim otoritesine verilen/geri çekilen belgeler (onaylar) bildiriliyor; reddedilen, askıya alınan veya kısıtlanan belgelerin listesi periyodik olarak veya talep üzerine sunuluyor.", "d": "Ek IX md. 4 (son paragraf); Md. 34(1)", "k": "Kayıt incelemesi"}, {"no": "H.3", "sec": "H", "t": "Diğer onaylanmış kuruluşlara reddedilen, askıya alınan, geri çekilen veya kısıtlanan belgeler bildiriliyor; talep hâlinde verilen belgeler hakkında bilgi veriliyor.", "d": "Ek IX md. 4 (son paragraf); Md. 34(2)", "k": "Kayıt incelemesi"}, {"no": "H.4", "sec": "H", "t": "Komisyon ve üye devletlerin talebi hâlinde belge kopyası (ve ilgili eklerde öngörüldüğünde teknik dosya/rapor) verilebiliyor; prosedürde tanımlı.", "d": "Ek IX md. 4 (son paragraf)", "k": "Prosedür incelemesi"}, {"no": "H.5", "sec": "H", "t": "Ekonomik operatörün saklama yükümlülüğü (AB uygunluk beyanı 10 yıl — Ek IX md. 5.2) belge/sözleşme ekinde veya bilgilendirme notunda müşteriye bildiriliyor.", "d": "2014/33/AB ilgili ek (iyi uygulama)", "k": "Dosya örneklemesi"}, {"no": "H.6", "sec": "H", "t": "Gizlilik: değerlendirme sırasında elde edilen bilgiler yalnız yetkili makamlarla paylaşılıyor; mülkiyet hakları korunuyor.", "d": "2014/33/AB Md. 24(10)", "k": "Prosedür incelemesi + Mülakat"}, {"no": "H.7", "sec": "H", "t": "OK, NB-L Koordinasyon Grubu çalışmalarına katılıyor veya personeli bilgilendiriliyor; tasdik edilmiş RfU'ların (Temmuz 2026 derlemesi) bu modüle ilişkin olanları prosedürlere işlenmiş.", "d": "2014/33/AB Md. 24(11), Md. 36; NB-L RfU 16.07.2026", "k": "Prosedür incelemesi + Kayıt incelemesi + Mülakat"}], "tanik": {"faaliyet": "OK'nın sahada numune alması ve deney", "grup": "C1 veya C2 veya A1 veya A2 veya B* veya F veya G", "not": "Rastgele kontrolün öngörülemezliği planlamayı zorlaştırır; müşteriyle önceden erişim mutabakatı gerekir."}, "yon": "asansor"}, {"id": "VI", "code": "A3", "grup": "aksam", "ad": "Aksam Modül E (Ek VI)", "baslik": "EK VI — GÜVENLİK AKSAMLARI İÇİN ÜRÜN KALİTE GÜVENCESİNE DAYALI TİPE UYGUNLUK (MODÜL E)", "ozet": [["Ürün", "AB tip inceleme belgesi (Ek IV-A) bulunan güvenlik aksamları"], ["Direktif dayanağı", "Md. 15(b) — Ek IV-A + Ek VI"], ["Başvuran / OK çıktısı", "İmalatçı veya yetkili temsilcisi / son muayene ve deney için kalite sistemi onay kararı; OK numarası her aksamda CE yanında"], ["Akreditasyon (EA-2/17 M:2026)", "EN ISO/IEC 17065 · cd + qa · kabul edilmeyen: 17024, 17025, 17029"], ["Tanık gruplaması", "Tablo 2: E ← E veya E1 veya D veya D1 veya H veya H1 (asansör modülleriyle gruplama gerekçelendirilmeli)"], ["Saklama süreleri", "OK: Direktifte süre yok (en az 10 yıl önerilir) · İmalatçı: 10 yıl (md. 6)"]], "items": [{"no": "A.1", "sec": "A", "t": "Kuruluş bu modül (Ek VI) için EN ISO/IEC 17065 esas alınarak akredite edilmiş/denetleniyor mu? Farklı bir standart kullanılıyorsa bildirim otoritesinin yayımlanmış bağlayıcı gerekliliğine dayanan gerekçe AK tarafından kayda alınmış mı?", "d": "EA-2/17 M:2026 §4.2, Annex A Tablo 1", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "A.2", "sec": "A", "t": "Bu modül için kabul edilmeyen standartlar (ISO/IEC 17024, 17025, 17029) akreditasyon dayanağı olarak kullanılmıyor.", "d": "EA-2/17 M:2026 Annex A Tablo 1", "k": "Kayıt incelemesi"}, {"no": "A.3", "sec": "A", "t": "'cd' gerekliliği: EN ISO/IEC 17065 md. 4.1.2, 4.1.3, 7.5 ve 7.6'nın (belgelendirme anlaşması, belge/işaret kullanımı, gözden geçirme ve karar) bu modül için ayrıca kanıtlandığı doğrulanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (cd)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "A.4", "sec": "A", "t": "'qa' gerekliliği: kalite sistemlerini değerlendirme ve onaylama yeteneği — EN ISO/IEC 17021-1 md. 7.1.1, 7.1.2, 7.2.4, 7.2.5, 7.2.8, 7.2.10 ve 9.1–9.4, 9.6 kanıtlanmalı (17065 ile akredite olunsa bile).", "d": "EA-2/17 M:2026 Annex A anahtarı (qa)", "k": "Prosedür incelemesi + Kayıt incelemesi + Mülakat"}, {"no": "A.5", "sec": "A", "t": "Kapsam ifadesi: Direktif (2014/33/AB), ek ve modül (Ek VI) ile ürün kapsamı (Ek III aksam türleri) açıkça yazılmış; NANDO'ya veri girişine uygun.", "d": "EA-2/17 M:2026 §5; ISO/IEC 17011 md. 7.8", "k": "Kayıt incelemesi"}, {"no": "A.6", "sec": "A", "t": "Akreditasyon kapsamı ile bildirim (NANDO) kapsamı tutarlı; bildirim dışı bir modül/ürün için belge düzenlenmemiş.", "d": "2014/33/AB Md. 28(3), Md. 32(1)", "k": "Kayıt incelemesi + Dosya örneklemesi"}, {"no": "A.7", "sec": "A", "t": "Tanık denetimi planı: kapsam döngüsünde en az bir ilk/gözetim KS denetimi imalatçı tesisinde izlenmiş mi?", "d": "EA-2/17 M:2026 Annex B Tablo 2", "k": "Kayıt incelemesi"}, {"no": "A.8", "sec": "A", "t": "İlk akreditasyonda tanık denetimi ertelendiyse 18 ay içinde tamamlandığı ve tanık öncesi akredite belge düzenlenmediği doğrulanmış.", "d": "EA-2/17 M:2026 Annex B (18 ay kuralı)", "k": "Kayıt incelemesi"}, {"no": "B.1", "sec": "B", "t": "Başvuru imalatçı veya yetkili temsilcisi tarafından yapılıyor; yetkili temsilci başvurularında vekâletnamenin ilgili yükümlülükleri açıkça kapsadığı kontrol ediliyor.", "d": "Ek VI md. 3.1, 8 (yetkili temsilci maddesi)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.2", "sec": "B", "t": "Başvuruda aynı başvurunun başka bir onaylanmış kuruluşa yapılmadığına dair yazılı beyan bulunuyor.", "d": "Ek VI md. 3.1, 8 — tek OK beyanı", "k": "Dosya örneklemesi"}, {"no": "B.3", "sec": "B", "t": "Başvuru dosyası Direktifin istediği tüm unsurları içeriyor: (a) imalatçının/yetkili temsilcinin adı ve adresi, (b) tek OK beyanı, (c) son muayene ve deneylerin yapıldığı tesisin adresi, (d) aksamlara ilişkin tüm ilgili bilgiler, (e) KS dokümantasyonu, (f) onaylı aksamların teknik dosyası ve AB tip inceleme belgesi kopyası.", "d": "Ek VI md. 3.1, 8", "k": "Dosya örneklemesi"}, {"no": "B.4", "sec": "B", "t": "Başvurunun gözden geçirilmesinde kapsam (NANDO), yetkinlik ve kaynak yeterliliği ile tarafsızlık riski değerlendiriliyor ve kayda alınıyor.", "d": "ISO/IEC 17065 md. 7.3 / ISO/IEC 17021-1 md. 9.1.2; Md. 24(6)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.5", "sec": "B", "t": "Müşteri sözleşmesinde OK'nın ve akreditasyon kuruluşunun (tanık denetimi için) tesislere, sahalara ve kayıtlara erişim hakkı açıkça yazılı.", "d": "ISO/IEC 17065 md. 4.1.2; iyi uygulama: AA L05 §1.3", "k": "Dosya örneklemesi"}, {"no": "B.6", "sec": "B", "t": "Alt yüklenici veya bağlı kuruluş kullanılacaksa müşterinin onayı alınmış.", "d": "2014/33/AB Md. 26(3)", "k": "Dosya örneklemesi"}, {"no": "B.7", "sec": "B", "t": "Orantılılık: değerlendirme planı işletmenin büyüklüğü, yapısı, teknolojinin karmaşıklığı ve üretimin seri/kütle niteliği dikkate alınarak hazırlanmış; ancak koruma düzeyinden taviz verilmemiş.", "d": "2014/33/AB Md. 24(6)(c), Md. 32(2)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C1.1", "sec": "C1", "t": "KS kapsamında her aksamın muayene edildiği ve uyumlaştırılmış standartlardaki veya eşdeğer deneylerin uygulandığı doğrulanıyor.", "d": "Ek VI md. 3.2 (1. paragraf)", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C1.2", "sec": "C1", "t": "KS dokümantasyonu yazılı politika, prosedür ve talimatlarla sistematik; kalite programları, planlar, el kitapları ve kayıtların tutarlı yorumlanmasına imkân veriyor.", "d": "Ek VI md. 3.2 (2. paragraf)", "k": "Dosya örneklemesi"}, {"no": "C1.3", "sec": "C1", "t": "(a) Kalite hedefleri tanımlı.", "d": "Ek VI md. 3.2(a)", "k": "Dosya örneklemesi"}, {"no": "C1.4", "sec": "C1", "t": "(b) Ürün kalitesine ilişkin organizasyon yapısı, yönetimin sorumluluk ve yetkileri tanımlı.", "d": "Ek VI md. 3.2(b)", "k": "Dosya örneklemesi"}, {"no": "C1.5", "sec": "C1", "t": "(c) İmalattan sonra yapılacak muayene ve deneyler (son muayene planı, deney yöntemleri, kabul kriterleri) tanımlı ve AB tip inceleme belgesindeki tip tanımıyla bağlantılı.", "d": "Ek VI md. 3.2(c)", "k": "Dosya örneklemesi"}, {"no": "C1.6", "sec": "C1", "t": "(d) KS'nin etkin işleyişini izleme araçları (iç denetim, YGG, uygunsuzluk yönetimi) tanımlı.", "d": "Ek VI md. 3.2(d)", "k": "Dosya örneklemesi"}, {"no": "C1.7", "sec": "C1", "t": "(e) Kalite kayıtları: muayene raporları, deney verileri, kalibrasyon verileri, personel nitelik raporları.", "d": "Ek VI md. 3.2(e)", "k": "Dosya örneklemesi"}, {"no": "C1.8", "sec": "C1", "t": "Denetim ekibi teknik dosyayı (md. 3.1(f)) gözden geçirerek imalatçının Direktif gerekliliklerini tanıma ve gerekli muayeneleri yapma yeteneğini doğrulamış.", "d": "Ek VI md. 3.3", "k": "Dosya örneklemesi"}, {"no": "C1.9", "sec": "C1", "t": "Denetim ekibi kalite yönetim sistemleri deneyimine ek olarak, ilgili asansör teknolojisinde değerlendirme deneyimi ve Ek I TSGG bilgisi olan en az bir üye içeriyor.", "d": "Ek VI md. 3.3 (değerlendirme maddesi); Md. 24(7)", "k": "Kayıt incelemesi + Dosya örneklemesi"}, {"no": "C1.10", "sec": "C1", "t": "İlk değerlendirme imalatçının tesisine değerlendirme ziyaretini içeriyor; ziyaret kayıtları (yer, tarih, görüşülen kişiler, örneklenen kayıtlar) dosyada.", "d": "Ek VI md. 3.3", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C1.11", "sec": "C1", "t": "Denetim programı ve denetim süresi belirlenmiş; ilgili IAF MD dokümanları (ör. çok sahalı örnekleme, denetim süresi) dikkate alınmış; NB-L kararı varsa öncelikli.", "d": "ISO/IEC 17021-1 md. 9.1.3, 9.1.4 (qa); EA-2/17 M:2026 Annex A Not 4–5", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C1.12", "sec": "C1", "t": "Uyumlaştırılmış standart karinesi yalnız atfı AB Resmî Gazetesi'nde yayımlanmış bir standarda dayandırılıyor; ISO 9001 belgesi tek başına kalite sistemi onayının yerine kullanılmıyor.", "d": "Ek VI md. 3.3 (karine cümlesi)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C1.13", "sec": "C1", "t": "Değerlendirme kararı başvurana bildiriliyor; bildirim denetim sonuçlarını ve gerekçeli değerlendirme kararını içeriyor.", "d": "Ek VI md. 3.3", "k": "Dosya örneklemesi"}, {"no": "D.1", "sec": "D", "t": "KS denetçileri için asansör aksamlarına özgü yetkinlik kriterleri (17021-1 md. 7.1.1, 7.1.2) belirlenmiş; denetçi ve teknik uzman seçimi ve izlemesi kayıtlı.", "d": "ISO/IEC 17021-1 md. 7.1.1, 7.1.2, 7.2.4, 7.2.5, 7.2.8, 7.2.10 (qa)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "E.1", "sec": "E", "t": "Denetim raporu yapılan inceleme, doğrulama ve deneyleri ve sonuçlarını kanıtlarla birlikte kaydediyor.", "d": "2014/33/AB Md. 24(7)(d)", "k": "Dosya örneklemesi"}, {"no": "E.2", "sec": "E", "t": "Gözden geçirme ve belgelendirme kararı, değerlendirmeyi yapmamış yetkin kişi(ler)ce veriliyor; karar kaydı tarihli ve imzalı.", "d": "ISO/IEC 17065 md. 7.5, 7.6 (cd) / ISO/IEC 17021-1 md. 9.5", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "E.3", "sec": "E", "t": "TSGG veya uyumlaştırılmış standartlar/diğer teknik şartnameler karşılanmadığında düzeltici faaliyet isteniyor ve belge düzenlenmiyor.", "d": "2014/33/AB Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "E.4", "sec": "E", "t": "Ret kararında ayrıntılı gerekçe başvurana yazılı bildiriliyor.", "d": "2014/33/AB ilgili ek; Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "E.5", "sec": "E", "t": "OK kararlarına karşı itiraz prosedürü mevcut, müşteriye duyuruluyor ve itirazlar kararı verenden bağımsız kişilerce ele alınıyor.", "d": "2014/33/AB Md. 33; ISO/IEC 17065 md. 7.13", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "F.1", "sec": "F", "t": "Kalite sistemi onay belgesi asgari şu bilgileri içeriyor: OK adı ve kimlik no; belge sahibinin adı/adresi; dayanak (2014/33/AB Ek …); belge no; onay kapsamı; değerlendirme raporuyla ilişki; ek bilgiler; yer, tarih, imza ve ad; geçerlilik süresi.", "d": "NB-L RfU 3/005", "k": "Dosya örneklemesi"}, {"no": "F.2", "sec": "F", "t": "İmalatçının, OK'nın sorumluluğunda, uygun her aksama CE işareti ve OK kimlik numarasını iliştirmesi kuralları tanımlı ve izleniyor.", "d": "Ek VI md. 5.1; Md. 19(3)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "F.3", "sec": "F", "t": "Onay kararı kapsamındaki aksamların AB tip inceleme belgeleri listelenmiş (iyi uygulama).", "d": "Ek VI md. 3.1(f)", "k": "Dosya örneklemesi"}, {"no": "G.1", "sec": "G", "t": "Kalite sistemindeki planlanan değişiklikler OK'ya bildiriliyor; OK değişikliği değerlendirip sistemin şartları karşılamaya devam edip etmediğine veya yeniden değerlendirme gerekip gerekmediğine karar veriyor; karar gerekçeli bildiriliyor.", "d": "Ek VI md. 3.5", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "G.2", "sec": "G", "t": "Gözetimde OK'ya son muayene, deney ve depolama yerlerine erişim sağlanıyor; KS dokümantasyonu ve kalite kayıtları (muayene raporları, deney verileri, kalibrasyon, personel nitelikleri) örnekleniyor.", "d": "Ek VI md. 4.2", "k": "Dosya örneklemesi"}, {"no": "G.3", "sec": "G", "t": "Periyodik denetimler yapılıyor ve her denetim sonunda müşteriye denetim raporu veriliyor; gözetim sıklığı tanımlı (en az yıllık önerilir) ve uygulanıyor.", "d": "Ek VI md. 4.3; ISO/IEC 17021-1 md. 9.6 (qa)", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "G.4", "sec": "G", "t": "Habersiz ziyaret politikası tanımlı (imalatçının son muayene ve deney tesisleri); ziyaretlerde gerektiğinde deney yapılıyor/yaptırılıyor; ziyaret raporu ve varsa deney raporu veriliyor.", "d": "Ek VI md. 4.4", "k": "Prosedür incelemesi + Dosya örneklemesi + Kayıt incelemesi"}, {"no": "G.5", "sec": "G", "t": "Onay kapsamı sınırlamaları yalnız ürünle ilişkili (ör. teknoloji, aksam türü, tahrik tipi) olarak tanımlanıyor.", "d": "NB-L RfU 3/004", "k": "Dosya örneklemesi"}, {"no": "G.6", "sec": "G", "t": "Gözetimde uygunsuzluk tespitinde düzeltici faaliyet isteniyor; etkisiz kalırsa onay kısıtlanıyor, askıya alınıyor veya geri çekiliyor.", "d": "2014/33/AB Md. 32(4), 32(5)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "G.7", "sec": "G", "t": "Onayın geçerlilik süresi ve yeniden belgelendirme döngüsü tanımlı ve belgede yazılı.", "d": "NB-L RfU 3/005 (md. 9 geçerlilik süresi); ISO/IEC 17021-1 md. 9.6.3", "k": "Dosya örneklemesi"}, {"no": "H.1", "sec": "H", "t": "Kayıt saklama: Direktif Ek VI için OK saklama süresi öngörmüyor; onay kararları, denetim raporları ve kayıtların en az 10 yıl saklanması önerilir.", "d": "2014/33/AB ilgili ek; ISO/IEC 17065 md. 7.12 / 17021-1 md. 9.9 / 17020 md. 7.3, 8.4", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "H.2", "sec": "H", "t": "Bildirim otoritesine verilen/geri çekilen belgeler (onaylar) bildiriliyor; reddedilen, askıya alınan veya kısıtlanan belgelerin listesi periyodik olarak veya talep üzerine sunuluyor.", "d": "Ek VI md. 7; Md. 34(1)", "k": "Kayıt incelemesi"}, {"no": "H.3", "sec": "H", "t": "Diğer onaylanmış kuruluşlara reddedilen, askıya alınan, geri çekilen veya kısıtlanan belgeler bildiriliyor; talep hâlinde verilen belgeler hakkında bilgi veriliyor.", "d": "Ek VI md. 7; Md. 34(2)", "k": "Kayıt incelemesi"}, {"no": "H.4", "sec": "H", "t": "Komisyon ve üye devletlerin talebi hâlinde belge kopyası (ve ilgili eklerde öngörüldüğünde teknik dosya/rapor) verilebiliyor; prosedürde tanımlı.", "d": "Ek VI md. 7", "k": "Prosedür incelemesi"}, {"no": "H.5", "sec": "H", "t": "Ekonomik operatörün saklama yükümlülüğü (10 yıl — Ek VI md. 6) belge/sözleşme ekinde veya bilgilendirme notunda müşteriye bildiriliyor.", "d": "2014/33/AB ilgili ek (iyi uygulama)", "k": "Dosya örneklemesi"}, {"no": "H.6", "sec": "H", "t": "Gizlilik: değerlendirme sırasında elde edilen bilgiler yalnız yetkili makamlarla paylaşılıyor; mülkiyet hakları korunuyor.", "d": "2014/33/AB Md. 24(10)", "k": "Prosedür incelemesi + Mülakat"}, {"no": "H.7", "sec": "H", "t": "OK, NB-L Koordinasyon Grubu çalışmalarına katılıyor veya personeli bilgilendiriliyor; tasdik edilmiş RfU'ların (Temmuz 2026 derlemesi) bu modüle ilişkin olanları prosedürlere işlenmiş.", "d": "2014/33/AB Md. 24(11), Md. 36; NB-L RfU 16.07.2026", "k": "Prosedür incelemesi + Kayıt incelemesi + Mülakat"}], "tanik": {"faaliyet": "İmalatçı tesisinde ilk/gözetim KS denetimi", "grup": "E veya E1 veya D veya D1 veya H veya H1", "not": "Asansör D/E/H1 ile gruplama yapılıyorsa aksam ürün bilgisi ayrıca dosya incelemesiyle doğrulanmalı."}, "yon": "asansor"}, {"id": "VII", "code": "A4", "grup": "aksam", "ad": "Aksam Modül H (Ek VII)", "baslik": "EK VII — GÜVENLİK AKSAMLARI İÇİN TAM KALİTE GÜVENCESİNE DAYALI UYGUNLUK (MODÜL H)", "ozet": [["Ürün", "Güvenlik aksamları (tasarım + imalat + son muayene + deney tek KS altında; ayrıca tip incelemesi yok)"], ["Direktif dayanağı", "Md. 15(c)"], ["Başvuran / OK çıktısı", "İmalatçı veya yetkili temsilcisi / tam kalite sistemi onay kararı; OK numarası her aksamda CE yanında"], ["Akreditasyon (EA-2/17 M:2026)", "EN ISO/IEC 17021-1 · zorunlu gerekler qa + cd + pk · kabul edilmeyen: 17024, 17025, 17029 · IAF MD dokümanları tam uygulanır"], ["Tanık gruplaması", "Tablo 2: H ← H veya H1"], ["Saklama süreleri", "OK: onay kararı, ekleri ve teknik dosya 15 yıl (md. 7) · İmalatçı: 10 yıl (md. 6)"]], "items": [{"no": "A.1", "sec": "A", "t": "Kuruluş bu modül (Ek VII) için EN ISO/IEC 17021-1 esas alınarak akredite edilmiş/denetleniyor mu? Farklı bir standart kullanılıyorsa bildirim otoritesinin yayımlanmış bağlayıcı gerekliliğine dayanan gerekçe AK tarafından kayda alınmış mı?", "d": "EA-2/17 M:2026 §4.2, Annex A Tablo 1", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "A.2", "sec": "A", "t": "Bu modül için kabul edilmeyen standartlar (ISO/IEC 17024, 17025, 17029) akreditasyon dayanağı olarak kullanılmıyor.", "d": "EA-2/17 M:2026 Annex A Tablo 1", "k": "Kayıt incelemesi"}, {"no": "A.3", "sec": "A", "t": "'qa' gerekliliği: kalite sistemlerini değerlendirme ve onaylama yeteneği — EN ISO/IEC 17021-1 md. 7.1.1, 7.1.2, 7.2.4, 7.2.5, 7.2.8, 7.2.10 ve 9.1–9.4, 9.6 kanıtlanmalı (17065 ile akredite olunsa bile).", "d": "EA-2/17 M:2026 Annex A anahtarı (qa)", "k": "Prosedür incelemesi + Kayıt incelemesi + Mülakat"}, {"no": "A.4", "sec": "A", "t": "'cd' gerekliliği: EN ISO/IEC 17065 md. 4.1.2, 4.1.3, 7.5 ve 7.6'nın (belgelendirme anlaşması, belge/işaret kullanımı, gözden geçirme ve karar) bu modül için ayrıca kanıtlandığı doğrulanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (cd)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "A.5", "sec": "A", "t": "'pk' gerekliliği: ürün bilgisine dayalı mesleki yargı — EN ISO/IEC 17020 md. 6.1.2, 6.1.3 ve 6.1.6–6.1.10 (yetkinlik kriterleri, görevlendirme, eğitim, gözetim, saha izleme, kayıtlar) bu modülün personeli için kanıtlanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (pk)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "A.6", "sec": "A", "t": "Kapsam ifadesi: Direktif (2014/33/AB), ek ve modül (Ek VII) ile ürün kapsamı (Ek III aksam kategorileri) açıkça yazılmış; NANDO'ya veri girişine uygun.", "d": "EA-2/17 M:2026 §5; ISO/IEC 17011 md. 7.8", "k": "Kayıt incelemesi"}, {"no": "A.7", "sec": "A", "t": "Akreditasyon kapsamı ile bildirim (NANDO) kapsamı tutarlı; bildirim dışı bir modül/ürün için belge düzenlenmemiş.", "d": "2014/33/AB Md. 28(3), Md. 32(1)", "k": "Kayıt incelemesi + Dosya örneklemesi"}, {"no": "A.8", "sec": "A", "t": "Tanık denetimi planı: kapsam döngüsünde imalatçı tesisinde (tasarım bölümü dâhil) en az bir denetim izlenmiş mi?", "d": "EA-2/17 M:2026 Annex B Tablo 2", "k": "Kayıt incelemesi"}, {"no": "A.9", "sec": "A", "t": "İlk akreditasyonda tanık denetimi ertelendiyse 18 ay içinde tamamlandığı ve tanık öncesi akredite belge düzenlenmediği doğrulanmış.", "d": "EA-2/17 M:2026 Annex B (18 ay kuralı)", "k": "Kayıt incelemesi"}, {"no": "A.10", "sec": "A", "t": "Modül H 17021-1 ile akredite edildiğinden 17021-1'in tüm şartları ve ilgili IAF MD dokümanları tam olarak uygulanıyor; NB-L kararları çelişki hâlinde önceliklidir.", "d": "EA-2/17 M:2026 Annex A Not 4, Not 5", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "B.1", "sec": "B", "t": "Başvuru imalatçı veya yetkili temsilcisi tarafından yapılıyor; yetkili temsilci başvurularında vekâletnamenin ilgili yükümlülükleri açıkça kapsadığı kontrol ediliyor.", "d": "Ek VII md. 3.1, 8 (yetkili temsilci maddesi)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.2", "sec": "B", "t": "Başvuruda aynı başvurunun başka bir onaylanmış kuruluşa yapılmadığına dair yazılı beyan bulunuyor.", "d": "Ek VII md. 3.1, 8 — tek OK beyanı", "k": "Dosya örneklemesi"}, {"no": "B.3", "sec": "B", "t": "Başvuru dosyası Direktifin istediği tüm unsurları içeriyor: (a) imalatçının/yetkili temsilcinin adı ve adresi, (b) tasarım, imalat, muayene ve deney yerlerinin adresleri, (c) aksamlara ilişkin tüm bilgiler, (d) imal edilecek her aksam kategorisinden bir model için Ek IV-A md. 3 teknik dosyası, (e) KS dokümantasyonu, (f) tek OK beyanı.", "d": "Ek VII md. 3.1, 8", "k": "Dosya örneklemesi"}, {"no": "B.4", "sec": "B", "t": "Başvurunun gözden geçirilmesinde kapsam (NANDO), yetkinlik ve kaynak yeterliliği ile tarafsızlık riski değerlendiriliyor ve kayda alınıyor.", "d": "ISO/IEC 17065 md. 7.3 / ISO/IEC 17021-1 md. 9.1.2; Md. 24(6)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.5", "sec": "B", "t": "Müşteri sözleşmesinde OK'nın ve akreditasyon kuruluşunun (tanık denetimi için) tesislere, sahalara ve kayıtlara erişim hakkı açıkça yazılı.", "d": "ISO/IEC 17065 md. 4.1.2; iyi uygulama: AA L05 §1.3", "k": "Dosya örneklemesi"}, {"no": "B.6", "sec": "B", "t": "Alt yüklenici veya bağlı kuruluş kullanılacaksa müşterinin onayı alınmış.", "d": "2014/33/AB Md. 26(3)", "k": "Dosya örneklemesi"}, {"no": "B.7", "sec": "B", "t": "Orantılılık: değerlendirme planı işletmenin büyüklüğü, yapısı, teknolojinin karmaşıklığı ve üretimin seri/kütle niteliği dikkate alınarak hazırlanmış; ancak koruma düzeyinden taviz verilmemiş.", "d": "2014/33/AB Md. 24(6)(c), Md. 32(2)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.8", "sec": "B", "t": "Kapsamdaki her aksam kategorisi için en az bir modelin teknik dosyası alınmış; kategori sayısı ile model dosyası sayısı tutarlı.", "d": "Ek VII md. 3.1(d)", "k": "Dosya örneklemesi"}, {"no": "C1.1", "sec": "C1", "t": "KS dokümantasyonu yazılı politika, prosedür ve talimatlarla sistematik ve tutarlı yorumlanabilir.", "d": "Ek VII md. 3.2", "k": "Dosya örneklemesi"}, {"no": "C1.2", "sec": "C1", "t": "(a) Tasarım ve ürün kalitesine ilişkin kalite hedefleri, organizasyon, sorumluluk ve yetkiler.", "d": "Ek VII md. 3.2(a)", "k": "Dosya örneklemesi"}, {"no": "C1.3", "sec": "C1", "t": "(b) Teknik tasarım spesifikasyonları; uygulanacak standartlar; uyumlaştırılmış standartlar tam uygulanmıyorsa kullanılacak diğer teknik şartnameler ve araçlar.", "d": "Ek VII md. 3.2(b)", "k": "Dosya örneklemesi"}, {"no": "C1.4", "sec": "C1", "t": "(c) Tasarım kontrolü ve tasarım doğrulama teknikleri, süreçleri ve sistematik faaliyetleri (tip deneyleri dâhil).", "d": "Ek VII md. 3.2(c)", "k": "Dosya örneklemesi"}, {"no": "C1.5", "sec": "C1", "t": "(d) İmalat, kalite kontrol ve kalite güvence teknikleri, süreçleri ve sistematik faaliyetleri.", "d": "Ek VII md. 3.2(d)", "k": "Dosya örneklemesi"}, {"no": "C1.6", "sec": "C1", "t": "(e) İmalattan önce, imalat sırasında ve sonrasında yapılacak muayene ve deneyler ile sıklıkları.", "d": "Ek VII md. 3.2(e)", "k": "Dosya örneklemesi"}, {"no": "C1.7", "sec": "C1", "t": "(f) Kalite kayıtları: muayene raporları, deney verileri, kalibrasyon verileri, personel nitelikleri.", "d": "Ek VII md. 3.2(f)", "k": "Dosya örneklemesi"}, {"no": "C1.8", "sec": "C1", "t": "(g) İstenen tasarım ve ürün kalitesine ulaşılmasının ve KS'nin etkin işleyişinin izlenmesi.", "d": "Ek VII md. 3.2(g)", "k": "Dosya örneklemesi"}, {"no": "C1.9", "sec": "C1", "t": "Denetim ekibi kalite yönetim sistemleri deneyimine ek olarak, ilgili asansör teknolojisinde değerlendirme deneyimi ve Ek I TSGG bilgisi olan en az bir üye içeriyor.", "d": "Ek VII md. 3.3 (değerlendirme maddesi); Md. 24(7)", "k": "Kayıt incelemesi + Dosya örneklemesi"}, {"no": "C1.10", "sec": "C1", "t": "İlk değerlendirme imalatçının tesisine değerlendirme ziyaretini içeriyor; ziyaret kayıtları (yer, tarih, görüşülen kişiler, örneklenen kayıtlar) dosyada.", "d": "Ek VII md. 3.3", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C1.11", "sec": "C1", "t": "Denetim programı ve denetim süresi belirlenmiş; ilgili IAF MD dokümanları (ör. çok sahalı örnekleme, denetim süresi) dikkate alınmış; NB-L kararı varsa öncelikli.", "d": "ISO/IEC 17021-1 md. 9.1.3, 9.1.4 (qa); EA-2/17 M:2026 Annex A Not 4–5", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C1.12", "sec": "C1", "t": "Uyumlaştırılmış standart karinesi yalnız atfı AB Resmî Gazetesi'nde yayımlanmış bir standarda dayandırılıyor; ISO 9001 belgesi tek başına kalite sistemi onayının yerine kullanılmıyor.", "d": "Ek VII md. 3.3 (karine cümlesi)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C1.13", "sec": "C1", "t": "Değerlendirme kararı başvurana bildiriliyor; bildirim denetim sonuçlarını ve gerekçeli değerlendirme kararını içeriyor.", "d": "Ek VII md. 3.3", "k": "Dosya örneklemesi"}, {"no": "C1.14", "sec": "C1", "t": "17021-1 md. 9.3 uyarınca ilk belgelendirme denetimi (aşama 1 / aşama 2) planlanmış ve uygulanmış.", "d": "ISO/IEC 17021-1 md. 9.3", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "C2.1", "sec": "C2", "t": "Denetim ekibi md. 3.1(d)'deki teknik dosyaları gözden geçirerek imalatçının Ek I TSGG'yi tanıma ve gerekli incelemeleri yapma yeteneğini doğrulamış.", "d": "Ek VII md. 3.3", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C2.2", "sec": "C2", "t": "İmalatçının tasarım yetkinliği değerlendirilmiş: risk analizi yapabilme, aksam tasarımını tanımlama ve spesifikasyonların karşılanıp karşılanmadığını deneyle doğrulama (parça satın alınması mümkün, sorumluluk imalatçıda).", "d": "NB-L RfU 3/002 (95/16/AT Ek IX — Md. 44 uyarınca geçerli)", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C2.3", "sec": "C2", "t": "İmalatçının tip deneyleri (EN 81-50 / EN ISO 8100-2 yöntemleri) ve tasarım doğrulama kayıtları (analiz, hesap, deney) OK'nın pk yetkinliğine sahip personelince incelenmiş.", "d": "Ek VII md. 4.2(b); NB-L RfU 1/001", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C2.4", "sec": "C2", "t": "UCM önleme tertibatlarında Modül H durumuna ilişkin RfU 1/008 hükümleri dikkate alınmış.", "d": "NB-L RfU 1/008", "k": "Dosya örneklemesi"}, {"no": "D.1", "sec": "D", "t": "KS denetçileri ve teknik uzmanlar için aksam kategorisine özgü yetkinlik kriterleri tanımlı; ekipte tasarım değerlendirmesini yapabilecek ürün bilgisi (pk) bulunuyor.", "d": "ISO/IEC 17021-1 md. 7.1, 7.2; ISO/IEC 17020 md. 6.1.2–6.1.3 (pk)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "E.1", "sec": "E", "t": "Denetim raporu yapılan inceleme, doğrulama ve deneyleri ve sonuçlarını kanıtlarla birlikte kaydediyor.", "d": "2014/33/AB Md. 24(7)(d)", "k": "Dosya örneklemesi"}, {"no": "E.2", "sec": "E", "t": "Gözden geçirme ve belgelendirme kararı, değerlendirmeyi yapmamış yetkin kişi(ler)ce veriliyor; karar kaydı tarihli ve imzalı.", "d": "ISO/IEC 17065 md. 7.5, 7.6 (cd) / ISO/IEC 17021-1 md. 9.5", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "E.3", "sec": "E", "t": "TSGG veya uyumlaştırılmış standartlar/diğer teknik şartnameler karşılanmadığında düzeltici faaliyet isteniyor ve belge düzenlenmiyor.", "d": "2014/33/AB Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "E.4", "sec": "E", "t": "Ret kararında ayrıntılı gerekçe başvurana yazılı bildiriliyor.", "d": "2014/33/AB ilgili ek; Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "E.5", "sec": "E", "t": "OK kararlarına karşı itiraz prosedürü mevcut, müşteriye duyuruluyor ve itirazlar kararı verenden bağımsız kişilerce ele alınıyor.", "d": "2014/33/AB Md. 33; ISO/IEC 17021-1 md. 9.7, 9.8", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "F.1", "sec": "F", "t": "Kalite sistemi onay belgesi asgari şu bilgileri içeriyor: OK adı ve kimlik no; belge sahibinin adı/adresi; dayanak (2014/33/AB Ek …); belge no; onay kapsamı; değerlendirme raporuyla ilişki; ek bilgiler; yer, tarih, imza ve ad; geçerlilik süresi. Onay kapsamı aksam kategorisi/teknolojisi bazında yazılı.", "d": "NB-L RfU 3/005", "k": "Dosya örneklemesi"}, {"no": "F.2", "sec": "F", "t": "İmalatçının, OK'nın sorumluluğunda, uygun her aksama CE işareti ve OK kimlik numarasını iliştirmesi kuralları tanımlı ve izleniyor.", "d": "Ek VII md. 5.1; Md. 19(3)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "G.1", "sec": "G", "t": "Kalite sistemindeki planlanan değişiklikler OK'ya bildiriliyor; OK değişikliği değerlendirip sistemin şartları karşılamaya devam edip etmediğine veya yeniden değerlendirme gerekip gerekmediğine karar veriyor; karar gerekçeli bildiriliyor.", "d": "Ek VII md. 3.5", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "G.2", "sec": "G", "t": "Gözetimde OK'ya tasarım, imalat, muayene, deney ve depolama yerlerine; tasarım bölümündeki kalite kayıtlarına (analiz, hesap, deney) erişim sağlanıyor; KS dokümantasyonu ve kalite kayıtları (muayene raporları, deney verileri, kalibrasyon, personel nitelikleri) örnekleniyor.", "d": "Ek VII md. 4.2", "k": "Dosya örneklemesi"}, {"no": "G.3", "sec": "G", "t": "Periyodik denetimler yapılıyor ve her denetim sonunda müşteriye denetim raporu veriliyor; gözetim sıklığı tanımlı (en az yıllık önerilir) ve uygulanıyor.", "d": "Ek VII md. 4.3; ISO/IEC 17021-1 md. 9.6 (qa)", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "G.4", "sec": "G", "t": "Habersiz ziyaret politikası tanımlı (imalatçının tesisleri); ziyaretlerde gerektiğinde deney yapılıyor/yaptırılıyor; ziyaret raporu ve varsa deney raporu veriliyor.", "d": "Ek VII md. 4.4", "k": "Prosedür incelemesi + Dosya örneklemesi + Kayıt incelemesi"}, {"no": "G.5", "sec": "G", "t": "Onay kapsamı sınırlamaları yalnız ürünle ilişkili (ör. teknoloji, aksam türü, tahrik tipi) olarak tanımlanıyor.", "d": "NB-L RfU 3/004", "k": "Dosya örneklemesi"}, {"no": "G.6", "sec": "G", "t": "Gözetimde uygunsuzluk tespitinde düzeltici faaliyet isteniyor; etkisiz kalırsa onay kısıtlanıyor, askıya alınıyor veya geri çekiliyor.", "d": "2014/33/AB Md. 32(4), 32(5)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "G.7", "sec": "G", "t": "Onayın geçerlilik süresi ve yeniden belgelendirme döngüsü tanımlı ve belgede yazılı.", "d": "NB-L RfU 3/005 (md. 9 geçerlilik süresi); ISO/IEC 17021-1 md. 9.6.3", "k": "Dosya örneklemesi"}, {"no": "G.8", "sec": "G", "t": "Yeni bir aksam kategorisinin eklenmesi kapsam genişletme olarak ele alınıyor ve o kategori için model teknik dosyası inceleniyor.", "d": "Ek VII md. 3.1(d), 3.5", "k": "Dosya örneklemesi"}, {"no": "G.9", "sec": "G", "t": "Gözetim ve yeniden belgelendirme 17021-1 md. 9.6'ya göre (3 yıllık döngü) yürütülüyor.", "d": "ISO/IEC 17021-1 md. 9.6", "k": "Kayıt incelemesi"}, {"no": "H.1", "sec": "H", "t": "Kayıt saklama: onay kararı, ekleri ve ilaveleri ile teknik dosya düzenlenme tarihinden itibaren 15 yıl saklanıyor.", "d": "2014/33/AB ilgili ek; ISO/IEC 17065 md. 7.12 / 17021-1 md. 9.9 / 17020 md. 7.3, 8.4", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "H.2", "sec": "H", "t": "Bildirim otoritesine verilen/geri çekilen belgeler (onaylar) bildiriliyor; reddedilen, askıya alınan veya kısıtlanan belgelerin listesi periyodik olarak veya talep üzerine sunuluyor.", "d": "Ek VII md. 7; Md. 34(1)", "k": "Kayıt incelemesi"}, {"no": "H.3", "sec": "H", "t": "Diğer onaylanmış kuruluşlara reddedilen, askıya alınan, geri çekilen veya kısıtlanan belgeler bildiriliyor; talep hâlinde verilen belgeler hakkında bilgi veriliyor.", "d": "Ek VII md. 7; Md. 34(2)", "k": "Kayıt incelemesi"}, {"no": "H.4", "sec": "H", "t": "Komisyon ve üye devletlerin talebi hâlinde belge kopyası (ve ilgili eklerde öngörüldüğünde teknik dosya/rapor) verilebiliyor; prosedürde tanımlı.", "d": "Ek VII md. 7", "k": "Prosedür incelemesi"}, {"no": "H.5", "sec": "H", "t": "Ekonomik operatörün saklama yükümlülüğü (10 yıl — Ek VII md. 6) belge/sözleşme ekinde veya bilgilendirme notunda müşteriye bildiriliyor.", "d": "2014/33/AB ilgili ek (iyi uygulama)", "k": "Dosya örneklemesi"}, {"no": "H.6", "sec": "H", "t": "Gizlilik: değerlendirme sırasında elde edilen bilgiler yalnız yetkili makamlarla paylaşılıyor; mülkiyet hakları korunuyor.", "d": "2014/33/AB Md. 24(10)", "k": "Prosedür incelemesi + Mülakat"}, {"no": "H.7", "sec": "H", "t": "OK, NB-L Koordinasyon Grubu çalışmalarına katılıyor veya personeli bilgilendiriliyor; tasdik edilmiş RfU'ların (Temmuz 2026 derlemesi) bu modüle ilişkin olanları prosedürlere işlenmiş.", "d": "2014/33/AB Md. 24(11), Md. 36; NB-L RfU 16.07.2026", "k": "Prosedür incelemesi + Kayıt incelemesi + Mülakat"}], "tanik": {"faaliyet": "İmalatçı tesisinde tasarım dâhil KS denetimi", "grup": "H veya H1", "not": "17021-1 akreditasyonu; IAF MD tam uygulanır."}, "yon": "asansor"}, {"id": "IV-B", "code": "L1", "grup": "asansor", "ad": "Asansör Modül B (Ek IV-B)", "baslik": "EK IV KISIM B — ASANSÖRLER İÇİN AB TİP İNCELEMESİ (MODÜL B) — ÖZET ÇEKLİST", "ozet": [["Ürün", "Model asansör veya uzatma/varyant öngörülmeyen asansör; numune asansör uç kısımları içerir, en az üç durak (iki durak: RfU 2/008, belgeye sınırlama)"], ["Direktif dayanağı", "Md. 16(1)(a) — üretim/montaj aşaması için Ek V, Ek X veya Ek XII ile birlikte"], ["Başvuran / OK çıktısı", "Monte eden veya yetkili temsilcisi / AB tip inceleme belgesi ve ekleri"], ["Akreditasyon (EA-2/17 M:2026)", "EN ISO/IEC 17065 · cd + pk + t · kabul edilmeyen: 17021-1, 17024, 17025, 17029"], ["Tanık gruplaması", "Tablo 2: B ← B* veya G veya H1; Modül B tasarımı için dosya incelemesi + teknik mülakat tercih edilir (Annex B ilke 2)"], ["Saklama süreleri", "OK: 15 yıl (md. 6) · Monte eden: 10 yıl (md. 11)"], ["Not", "Ayrıntılı denetim için klasördeki 'Ek_IVB_AB_Tip_Incelemesi_Denetim_Ceklisti_1.xlsx' (161 madde) kullanılır; bu sayfa modüller arası karşılaştırma için özet sürümdür."]], "items": [{"no": "A.1", "sec": "A", "t": "Kuruluş bu modül (Ek IV Kısım B) için EN ISO/IEC 17065 esas alınarak akredite edilmiş/denetleniyor mu? Farklı bir standart kullanılıyorsa bildirim otoritesinin yayımlanmış bağlayıcı gerekliliğine dayanan gerekçe AK tarafından kayda alınmış mı?", "d": "EA-2/17 M:2026 §4.2, Annex A Tablo 1", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "A.2", "sec": "A", "t": "Bu modül için kabul edilmeyen standartlar (ISO/IEC 17021-1, 17024, 17025, 17029) akreditasyon dayanağı olarak kullanılmıyor.", "d": "EA-2/17 M:2026 Annex A Tablo 1", "k": "Kayıt incelemesi"}, {"no": "A.3", "sec": "A", "t": "'cd' gerekliliği: EN ISO/IEC 17065 md. 4.1.2, 4.1.3, 7.5 ve 7.6'nın (belgelendirme anlaşması, belge/işaret kullanımı, gözden geçirme ve karar) bu modül için ayrıca kanıtlandığı doğrulanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (cd)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "A.4", "sec": "A", "t": "'pk' gerekliliği: ürün bilgisine dayalı mesleki yargı — EN ISO/IEC 17020 md. 6.1.2, 6.1.3 ve 6.1.6–6.1.10 (yetkinlik kriterleri, görevlendirme, eğitim, gözetim, saha izleme, kayıtlar) bu modülün personeli için kanıtlanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (pk)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "A.5", "sec": "A", "t": "'t' gerekliliği: OK deneyleri kendisi yapıyorsa EN ISO/IEC 17025 md. 6 ve 7 (7.9 hariç) karşılanmalı; deneyler dış laboratuvarda yapılıyorsa Md. 26 kapsamında alt yüklenici değerlendirmesi aranmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (t); 2014/33/AB Md. 26", "k": "Prosedür incelemesi + Kayıt incelemesi + Tanık denetimi"}, {"no": "A.6", "sec": "A", "t": "Kapsam ifadesi: Direktif (2014/33/AB), ek ve modül (Ek IV Kısım B) ile ürün kapsamı (elektrikli / hidrolik tahrikli asansörler) açıkça yazılmış; NANDO'ya veri girişine uygun.", "d": "EA-2/17 M:2026 §5; ISO/IEC 17011 md. 7.8", "k": "Kayıt incelemesi"}, {"no": "A.7", "sec": "A", "t": "Akreditasyon kapsamı ile bildirim (NANDO) kapsamı tutarlı; bildirim dışı bir modül/ürün için belge düzenlenmemiş.", "d": "2014/33/AB Md. 28(3), Md. 32(1)", "k": "Kayıt incelemesi + Dosya örneklemesi"}, {"no": "A.8", "sec": "A", "t": "Tanık denetimi planı: elektrikli ve hidrolik asansörler için dosya incelemesi + teknik mülakat; numune muayenesi ve deneylerinin en az birinde tanık denetimi planlanmış mı?", "d": "EA-2/17 M:2026 Annex B Tablo 2", "k": "Kayıt incelemesi"}, {"no": "A.9", "sec": "A", "t": "İlk akreditasyonda tanık denetimi ertelendiyse 18 ay içinde tamamlandığı ve tanık öncesi akredite belge düzenlenmediği doğrulanmış.", "d": "EA-2/17 M:2026 Annex B (18 ay kuralı)", "k": "Kayıt incelemesi"}, {"no": "B.1", "sec": "B", "t": "Başvuru monte eden veya yetkili temsilcisi tarafından yapılıyor; yetkili temsilci başvurularında vekâletnamenin ilgili yükümlülükleri açıkça kapsadığı kontrol ediliyor.", "d": "Ek IV-B md. 2, 12 (yetkili temsilci maddesi)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.2", "sec": "B", "t": "Başvuruda aynı başvurunun başka bir onaylanmış kuruluşa yapılmadığına dair yazılı beyan bulunuyor.", "d": "Ek IV-B md. 2, 12 — tek OK beyanı", "k": "Dosya örneklemesi"}, {"no": "B.3", "sec": "B", "t": "Başvuru dosyası Direktifin istediği tüm unsurları içeriyor: (a) monte edenin/yetkili temsilcinin adı ve adresi, (b) tek OK beyanı, (c) teknik dosya, (d) numune asansörün incelenebileceği yer, (e) destekleyici kanıt.", "d": "Ek IV-B md. 2, 12", "k": "Dosya örneklemesi"}, {"no": "B.4", "sec": "B", "t": "Başvurunun gözden geçirilmesinde kapsam (NANDO), yetkinlik ve kaynak yeterliliği ile tarafsızlık riski değerlendiriliyor ve kayda alınıyor.", "d": "ISO/IEC 17065 md. 7.3 / ISO/IEC 17021-1 md. 9.1.2; Md. 24(6)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.5", "sec": "B", "t": "Müşteri sözleşmesinde OK'nın ve akreditasyon kuruluşunun (tanık denetimi için) tesislere, sahalara ve kayıtlara erişim hakkı açıkça yazılı.", "d": "ISO/IEC 17065 md. 4.1.2; iyi uygulama: AA L05 §1.3", "k": "Dosya örneklemesi"}, {"no": "B.6", "sec": "B", "t": "Alt yüklenici veya bağlı kuruluş kullanılacaksa müşterinin onayı alınmış.", "d": "2014/33/AB Md. 26(3)", "k": "Dosya örneklemesi"}, {"no": "B.7", "sec": "B", "t": "Orantılılık: değerlendirme planı işletmenin büyüklüğü, yapısı, teknolojinin karmaşıklığı ve üretimin seri/kütle niteliği dikkate alınarak hazırlanmış; ancak koruma düzeyinden taviz verilmemiş.", "d": "2014/33/AB Md. 24(6)(c), Md. 32(2)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.8", "sec": "B", "t": "Numune asansör uç kısımları içeriyor ve en az üç durağa (üst, orta, alt) hizmet ediyor; iki duraklı numunede sınırlama belgeye açıkça yazılıyor.", "d": "Ek IV-B md. 2(d); NB-L RfU 2/008", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C.1", "sec": "C", "t": "Model tanımı izin verilen tüm varyasyonları açıkça gösteriyor; varyasyonlar asgari ve azami değerleriyle teknik dosyada belirtilmiş.", "d": "Ek IV-B md. 3(a); Md. 16(3)", "k": "Dosya örneklemesi"}, {"no": "C.2", "sec": "C", "t": "Ürün yelpazesinin benzerliği hesap ve/veya tasarım planlarıyla gösterilmiş ve OK tarafından doğrulanmış (en olumsuz kombinasyon).", "d": "Md. 16(4)", "k": "Dosya örneklemesi"}, {"no": "C.3", "sec": "C", "t": "Md. 3(b)–(c) çizimleri, şemaları ve açıklamaları inceleme girdisi olarak dosyada; belgeye eklenen yerleşim çiziminden ayrı tutulmuş.", "d": "Ek IV-B md. 3(b), 3(c)", "k": "Dosya örneklemesi"}, {"no": "C.4", "sec": "C", "t": "Dikkate alınan TSGG listesi ve uygulanan uyumlaştırılmış standartlar (kısmi uygulamada bölümler) ile diğer teknik şartnameler listelenmiş; ek standartların ana standartla kullanımı analiz edilmiş.", "d": "Ek IV-B md. 3(d), 3(e); NB-L RfU 2/028", "k": "Dosya örneklemesi"}, {"no": "C.5", "sec": "C", "t": "Güvenlik aksamlarının AB uygunluk beyanları dosyada; Ek III dışı bileşen belgelerinin kabulü OK kararıyla gerekçelendirilmiş; aksam belgesi revizyonları izleniyor.", "d": "Ek IV-B md. 3(f); NB-L RfU 1/010, 1/011", "k": "Dosya örneklemesi"}, {"no": "C.6", "sec": "C", "t": "Tasarım hesaplarının sonuçları ve deney raporları incelenmiş; kritik hesaplar OK tarafından doğrulanmış.", "d": "Ek IV-B md. 3(g), 3(h)", "k": "Dosya örneklemesi"}, {"no": "C.7", "sec": "C", "t": "Ek I 6.2 talimatları; kurtarma, muayene, deney ve kuyu ekipmanına erişim için özel araç ve yöntemler tanımlı.", "d": "Ek IV-B md. 3(i); NB-L RfU 2/011, 2/012, 2/013", "k": "Dosya örneklemesi"}, {"no": "C.8", "sec": "C", "t": "Kurulum aşamasında seri üretilen asansörün TSGG'ye uygunluğunu sağlayan tedbirler (md. 3(j)) dokümanter olarak ve yüzeysel olmayan biçimde incelenmiş.", "d": "Ek IV-B md. 3(j)", "k": "Dosya örneklemesi"}, {"no": "C.9", "sec": "C", "t": "Risk değerlendirmesinin asgari unsurları kontrol edilmiş.", "d": "NB-L RfU 0/007", "k": "Dosya örneklemesi"}, {"no": "C.10", "sec": "C", "t": "Numune asansörün teknik dosyaya uygun imal edildiği doğrulanmış; uyumlaştırılmış standart ve diğer şartname unsurları ayrıştırılmış.", "d": "Ek IV-B md. 4(c)", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C.11", "sec": "C", "t": "Uyumlaştırılmış standart uygulandığında doğru uygulandığını kontrol eden muayene ve deneyler yapılmış.", "d": "Ek IV-B md. 4(d)", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C.12", "sec": "C", "t": "Standart dışı çözümlerde OK kendi analizini ve deneylerini yaparak ilgili TSGG'nin karşılandığını gerekçelendirmiş.", "d": "Ek IV-B md. 4(e)", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C.13", "sec": "C", "t": "Kurtarma ve erişim yöntemlerinin talimatta yazıldığı gibi güvenle uygulanabildiği fonksiyonel olarak kontrol edilmiş.", "d": "NB-L RfU 2/012, 2/013", "k": "Tanık denetimi"}, {"no": "D.1", "sec": "D", "t": "Personel elektrikli/hidrolik asansör tasarım değerlendirmesi için yetkilendirilmiş (Ek I, EN 81-20/50 veya EN ISO 8100-1/-2, RfU'lar).", "d": "Md. 24(7); ISO/IEC 17020 md. 6.1.2–6.1.3 (pk)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "E.1", "sec": "E", "t": "Değerlendirme raporu (Ek IV-B md. 5) yapılan inceleme, doğrulama ve deneyleri ve sonuçlarını kanıtlarla birlikte kaydediyor.", "d": "2014/33/AB Md. 24(7)(d)", "k": "Dosya örneklemesi"}, {"no": "E.2", "sec": "E", "t": "Gözden geçirme ve belgelendirme kararı, değerlendirmeyi yapmamış yetkin kişi(ler)ce veriliyor; karar kaydı tarihli ve imzalı.", "d": "ISO/IEC 17065 md. 7.5, 7.6 (cd) / ISO/IEC 17021-1 md. 9.5", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "E.3", "sec": "E", "t": "TSGG veya uyumlaştırılmış standartlar/diğer teknik şartnameler karşılanmadığında düzeltici faaliyet isteniyor ve belge düzenlenmiyor.", "d": "2014/33/AB Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "E.4", "sec": "E", "t": "Ret kararında ayrıntılı gerekçe başvurana yazılı bildiriliyor.", "d": "2014/33/AB ilgili ek; Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "E.5", "sec": "E", "t": "OK kararlarına karşı itiraz prosedürü mevcut, müşteriye duyuruluyor ve itirazlar kararı verenden bağımsız kişilerce ele alınıyor.", "d": "2014/33/AB Md. 33; ISO/IEC 17065 md. 7.13", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "F.1", "sec": "F", "t": "Belge monte edenin adı/adresi, sonuçlar, geçerlilik koşulları ve onaylı tipi tanımlayan bilgileri içeriyor; ekler son muayenede uygunluğun değerlendirilmesine imkân veren tüm bilgileri (varyasyon sınırları, koşullar, aksam listesi) taşıyor.", "d": "Ek IV-B md. 6", "k": "Dosya örneklemesi"}, {"no": "F.2", "sec": "F", "t": "İncelemeye konu teknik dosya belgeleri (ad/no/rev./tarih) belge ekinde veya raporda listelenmiş (iyi uygulama).", "d": "Ek IV-B md. 5, 6", "k": "Dosya örneklemesi"}, {"no": "G.1", "sec": "G", "t": "OK tekniğin gelişimini izliyor; standart revizyonlarında (EN 81-20/50 → EN ISO 8100-1/-2) belgeler gözden geçiriliyor.", "d": "Ek IV-B md. 7", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "G.2", "sec": "G", "t": "Teknik dosyada belirtilmeyen varyasyonlar dâhil tip değişiklikleri inceleniyor; ilave veya yeni başvuru kararı gerekçeli.", "d": "Ek IV-B md. 8; NB-L RfU 1/011", "k": "Dosya örneklemesi"}, {"no": "G.3", "sec": "G", "t": "Belgenin askıya alınması, kısıtlanması veya geri çekilmesi süreci tanımlı.", "d": "Md. 32(4), 32(5); ISO/IEC 17065 md. 7.11", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "H.1", "sec": "H", "t": "Kayıt saklama: belge, ekler, ilaveler, teknik dosya ve değerlendirme raporu 15 yıl saklanıyor.", "d": "2014/33/AB ilgili ek; ISO/IEC 17065 md. 7.12 / 17021-1 md. 9.9 / 17020 md. 7.3, 8.4", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "H.2", "sec": "H", "t": "Bildirim otoritesine verilen/geri çekilen belgeler (onaylar) bildiriliyor; reddedilen, askıya alınan veya kısıtlanan belgelerin listesi periyodik olarak veya talep üzerine sunuluyor.", "d": "Ek IV-B md. 9, 10; Md. 34(1)", "k": "Kayıt incelemesi"}, {"no": "H.3", "sec": "H", "t": "Diğer onaylanmış kuruluşlara reddedilen, askıya alınan, geri çekilen veya kısıtlanan belgeler bildiriliyor; talep hâlinde verilen belgeler hakkında bilgi veriliyor.", "d": "Ek IV-B md. 9, 10; Md. 34(2)", "k": "Kayıt incelemesi"}, {"no": "H.4", "sec": "H", "t": "Komisyon ve üye devletlerin talebi hâlinde belge kopyası (ve ilgili eklerde öngörüldüğünde teknik dosya/rapor) verilebiliyor; prosedürde tanımlı.", "d": "Ek IV-B md. 9, 10", "k": "Prosedür incelemesi"}, {"no": "H.5", "sec": "H", "t": "Ekonomik operatörün saklama yükümlülüğü (asansörün piyasaya arzından sonra 10 yıl — Ek IV-B md. 11) belge/sözleşme ekinde veya bilgilendirme notunda müşteriye bildiriliyor.", "d": "2014/33/AB ilgili ek (iyi uygulama)", "k": "Dosya örneklemesi"}, {"no": "H.6", "sec": "H", "t": "Gizlilik: değerlendirme sırasında elde edilen bilgiler yalnız yetkili makamlarla paylaşılıyor; mülkiyet hakları korunuyor.", "d": "2014/33/AB Md. 24(10)", "k": "Prosedür incelemesi + Mülakat"}, {"no": "H.7", "sec": "H", "t": "OK, NB-L Koordinasyon Grubu çalışmalarına katılıyor veya personeli bilgilendiriliyor; tasdik edilmiş RfU'ların (Temmuz 2026 derlemesi) bu modüle ilişkin olanları prosedürlere işlenmiş.", "d": "2014/33/AB Md. 24(11), Md. 36; NB-L RfU 16.07.2026", "k": "Prosedür incelemesi + Kayıt incelemesi + Mülakat"}], "tanik": {"faaliyet": "Numune asansör muayenesi ve deneyleri", "grup": "B* veya G veya H1", "not": "Tasarım değerlendirmesi için dosya incelemesi + teknik mülakat tercih edilir."}, "yon": "asansor"}, {"id": "V", "code": "L2", "grup": "asansor", "ad": "Son Muayene (Ek V)", "baslik": "EK V — ASANSÖRLER İÇİN SON MUAYENE", "ozet": [["Ürün", "AB tip inceleme belgesine (Ek IV-B) veya onaylı Ek XI kalite sistemine göre tasarlanıp imal edilen, piyasaya arz edilmek üzere olan asansör"], ["Direktif dayanağı", "Md. 16(1)(a)(i) ve 16(1)(b)(i)"], ["Başvuran / OK çıktısı", "Monte eden veya yetkili temsilcisi / son muayene belgesi; OK numarası kabinde CE yanında; kayıt defteri sayfaları"], ["Akreditasyon (EA-2/17 S1)", "EN ISO/IEC 17020 (yalnız Tip A) · cd + pk + t · kabul edilmeyen: 17021-1, 17024, 17029 (uyumlu olmayan modül — S1)"], ["Tanık gruplaması", "Ek V, Tablo 2'de yer almaz; AK gruplamayı gerekçelendirmeli — elektrikli ve hidrolik asansörde ayrı yerinde tanık önerilir"], ["Saklama süreleri", "OK: Direktifte süre yok (en az 10 yıl önerilir) · Monte eden: AB uygunluk beyanı + son muayene belgesi 10 yıl (md. 5.2)"]], "items": [{"no": "A.1", "sec": "A", "t": "Kuruluş bu modül (Ek V) için EN ISO/IEC 17020 esas alınarak akredite edilmiş/denetleniyor mu? Farklı bir standart kullanılıyorsa bildirim otoritesinin yayımlanmış bağlayıcı gerekliliğine dayanan gerekçe AK tarafından kayda alınmış mı?", "d": "EA-2/17 M:2026 §4.2, Annex A Tablo 1; S1", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "A.2", "sec": "A", "t": "Bu modül için kabul edilmeyen standartlar (ISO/IEC 17021-1, 17024, 17029) akreditasyon dayanağı olarak kullanılmıyor.", "d": "EA-2/17 M:2026 Annex A Tablo 1; S1", "k": "Kayıt incelemesi"}, {"no": "A.3", "sec": "A", "t": "'cd' gerekliliği: EN ISO/IEC 17065 md. 4.1.2, 4.1.3, 7.5 ve 7.6'nın (belgelendirme anlaşması, belge/işaret kullanımı, gözden geçirme ve karar) bu modül için ayrıca kanıtlandığı doğrulanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (cd)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "A.4", "sec": "A", "t": "'pk' gerekliliği: ürün bilgisine dayalı mesleki yargı — EN ISO/IEC 17020 md. 6.1.2, 6.1.3 ve 6.1.6–6.1.10 (yetkinlik kriterleri, görevlendirme, eğitim, gözetim, saha izleme, kayıtlar) bu modülün personeli için kanıtlanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (pk)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "A.5", "sec": "A", "t": "'t' gerekliliği: OK deneyleri kendisi yapıyorsa EN ISO/IEC 17025 md. 6 ve 7 (7.9 hariç) karşılanmalı; deneyler dış laboratuvarda yapılıyorsa Md. 26 kapsamında alt yüklenici değerlendirmesi aranmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (t); 2014/33/AB Md. 26", "k": "Prosedür incelemesi + Kayıt incelemesi + Tanık denetimi"}, {"no": "A.6", "sec": "A", "t": "Kapsam ifadesi: Direktif (2014/33/AB), ek ve modül (Ek V) ile ürün kapsamı (elektrikli / hidrolik tahrikli asansörler) açıkça yazılmış; NANDO'ya veri girişine uygun.", "d": "EA-2/17 M:2026 §5; ISO/IEC 17011 md. 7.8", "k": "Kayıt incelemesi"}, {"no": "A.7", "sec": "A", "t": "Akreditasyon kapsamı ile bildirim (NANDO) kapsamı tutarlı; bildirim dışı bir modül/ürün için belge düzenlenmemiş.", "d": "2014/33/AB Md. 28(3), Md. 32(1)", "k": "Kayıt incelemesi + Dosya örneklemesi"}, {"no": "A.8", "sec": "A", "t": "Tanık denetimi planı: elektrikli ve hidrolik asansör son muayenelerinin her birinde, akreditasyon döngüsünde en az bir tam son muayene yerinde izlenmiş mi?", "d": "EA-2/17 M:2026 Annex B Tablo 2", "k": "Kayıt incelemesi"}, {"no": "A.9", "sec": "A", "t": "İlk akreditasyonda tanık denetimi ertelendiyse 18 ay içinde tamamlandığı ve tanık öncesi akredite belge düzenlenmediği doğrulanmış.", "d": "EA-2/17 M:2026 Annex B (18 ay kuralı)", "k": "Kayıt incelemesi"}, {"no": "A.10", "sec": "A", "t": "Kuruluşun Tip A muayene kuruluşu olduğu (tasarım, imalat, tedarik, montaj, kullanım, bakım faaliyetlerinden bağımsızlık) kanıtlanmış.", "d": "EA-2/17 S1 Not 1; ISO/IEC 17020 Ek A.1; Md. 24(4)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "B.1", "sec": "B", "t": "Başvuru monte eden veya yetkili temsilcisi tarafından yapılıyor; yetkili temsilci başvurularında vekâletnamenin ilgili yükümlülükleri açıkça kapsadığı kontrol ediliyor.", "d": "Ek V md. 3.1, 7 (yetkili temsilci maddesi)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.2", "sec": "B", "t": "Başvuruda aynı başvurunun başka bir onaylanmış kuruluşa yapılmadığına dair yazılı beyan bulunuyor.", "d": "Ek V md. 3.1, 7 — tek OK beyanı", "k": "Dosya örneklemesi"}, {"no": "B.3", "sec": "B", "t": "Başvuru dosyası Direktifin istediği tüm unsurları içeriyor: (a) asansörün tam planı, (b) son muayene için gerekli planlar ve şemalar, özellikle kumanda devre şemaları, (c) Ek I 6.2 talimatlarının kopyası, (d) tek OK beyanı.", "d": "Ek V md. 3.1, 7", "k": "Dosya örneklemesi"}, {"no": "B.4", "sec": "B", "t": "Başvurunun gözden geçirilmesinde kapsam (NANDO), yetkinlik ve kaynak yeterliliği ile tarafsızlık riski değerlendiriliyor ve kayda alınıyor.", "d": "ISO/IEC 17065 md. 7.3 / ISO/IEC 17021-1 md. 9.1.2; Md. 24(6)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.5", "sec": "B", "t": "Müşteri sözleşmesinde OK'nın ve akreditasyon kuruluşunun (tanık denetimi için) tesislere, sahalara ve kayıtlara erişim hakkı açıkça yazılı.", "d": "ISO/IEC 17065 md. 4.1.2; iyi uygulama: AA L05 §1.3", "k": "Dosya örneklemesi"}, {"no": "B.6", "sec": "B", "t": "Alt yüklenici veya bağlı kuruluş kullanılacaksa müşterinin onayı alınmış.", "d": "2014/33/AB Md. 26(3)", "k": "Dosya örneklemesi"}, {"no": "B.7", "sec": "B", "t": "Orantılılık: değerlendirme planı işletmenin büyüklüğü, yapısı, teknolojinin karmaşıklığı ve üretimin seri/kütle niteliği dikkate alınarak hazırlanmış; ancak koruma düzeyinden taviz verilmemiş.", "d": "2014/33/AB Md. 24(6)(c), Md. 32(2)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.8", "sec": "B", "t": "Dayanak doğrulanıyor: AB tip inceleme belgesi (Ek IV-B) veya Ek XI kalite sistemi onayı ve gerekiyorsa AB tasarım inceleme belgesi geçerli ve bu asansörü kapsıyor; belge başka OK'ya aitse belge ve ekleri temin edilmiş.", "d": "Ek V md. 2(a), 2(b), 3.2", "k": "Dosya örneklemesi"}, {"no": "B.9", "sec": "B", "t": "OK, uygunluğun doğrulanması için gerekli olmayan ayrıntılı planları veya kesin bilgileri talep etmiyor.", "d": "Ek V md. 3.1 (2. paragraf)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.10", "sec": "B", "t": "Reddedilen bir son muayenenin yeniden başvurusunun aynı OK'ya yapıldığı kontrol ediliyor (başvuruda önceki başvuru/ret beyanı alınması önerilir).", "d": "Ek V md. 4 (2. paragraf)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C.1", "sec": "C", "t": "Muayene, ilgili uyumlaştırılmış standartlardaki veya eşdeğer muayene ve deneylere dayalı yazılı bir muayene talimatı/kontrol listesi ile yapılıyor (ör. EN 81-20 Ek D veya EN ISO 8100-1'deki karşılığı).", "d": "Ek V md. 3.1 (3. paragraf); ISO/IEC 17020 md. 7.1", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C.2", "sec": "C", "t": "Doküman incelemesiyle asansörün onaylı tipe (Ek IV-B) uyduğu kontrol ediliyor: anma yükü, hız, seyir, durak sayısı, kuyu boşlukları, tahrik, askı vb. belgedeki varyasyon sınırları içinde.", "d": "Ek V md. 3.2(a); Md. 16(3); Ek IV-B md. 6", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C.3", "sec": "C", "t": "Ek XI yolunda asansörün onaylı KS'ye ve gerekiyorsa AB tasarım inceleme belgesine uygunluğu kontrol ediliyor; belgedeki sahada yapılacak deneyler uygulanıyor.", "d": "Ek V md. 3.2(b); NB-L RfU 3/009 md. 8", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C.4", "sec": "C", "t": "Belgede yer alan koşulların (kurulumda yerine getirilecek şartlar) sahada sağlandığı tek tek doğrulanıyor.", "d": "Ek V md. 3.2; Ek IV-B md. 6", "k": "Tanık denetimi"}, {"no": "C.5", "sec": "C", "t": "Deney (a): asansör boş ve azami yükle çalıştırılarak güvenlik tertibatlarının (son durdurucular, kilitler vb.) doğru montajı ve çalışması kontrol ediliyor.", "d": "Ek V md. 3.3(a)", "k": "Tanık denetimi"}, {"no": "C.6", "sec": "C", "t": "Deney (b): azami yükte ve boşken enerji kesilmesi hâlinde güvenlik tertibatlarının doğru çalışması kontrol ediliyor.", "d": "Ek V md. 3.3(b)", "k": "Tanık denetimi"}, {"no": "C.7", "sec": "C", "t": "Deney (c): beyan yükünün 1,25 katı yükle statik deney yapılıyor (beyan yükü Ek I md. 5'teki değer).", "d": "Ek V md. 3.3(c)", "k": "Tanık denetimi"}, {"no": "C.8", "sec": "C", "t": "Deneylerden sonra asansörün kullanımını bozabilecek deformasyon veya bozulma olmadığı kontrol ediliyor ve kayda geçiyor.", "d": "Ek V md. 3.3 (son paragraf)", "k": "Tanık denetimi"}, {"no": "C.9", "sec": "C", "t": "Sahadaki güvenlik aksamlarının CE işareti, tip etiketi, ayar değerleri ve belgeleri (AB tip inceleme belgesi / AB uygunluk beyanı) ile tip belgesindeki aksam listesi eşleştiriliyor.", "d": "Ek I; NB-L RfU 1/010, 1/011", "k": "Tanık denetimi"}, {"no": "C.10", "sec": "C", "t": "Kurtarma işlemleri, muayene/deney noktalarına güvenli erişim ve kuyu ekipmanına erişim için öngörülen araç ve yöntemlerin talimatta doğru yazıldığı ve güvenle uygulanabildiği fonksiyonel olarak kontrol ediliyor.", "d": "NB-L RfU 2/011, 2/012, 2/013", "k": "Tanık denetimi"}, {"no": "C.11", "sec": "C", "t": "Kullanım talimatının (Ek I 6.2) içeriği ve kayıt defterinin varlığı kontrol ediliyor.", "d": "Ek V md. 3.1(c), md. 4", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C.12", "sec": "C", "t": "Ölçüm ve deney ekipmanı (deney ağırlıkları, hız/kuvvet/mesafe ölçerler, yalıtım ve topraklama ölçerleri, basınç göstergesi) kalibreli, izlenebilir ve kullanım öncesi kontrollü.", "d": "ISO/IEC 17020 md. 6.2; ISO/IEC 17025 md. 6.4, 6.5 (t)", "k": "Kayıt incelemesi + Tanık denetimi"}, {"no": "C.13", "sec": "C", "t": "Muayene kayıtları, her deneyin sonucunu ve ölçülen değerleri izlenebilir biçimde içeriyor.", "d": "ISO/IEC 17020 md. 7.3", "k": "Dosya örneklemesi"}, {"no": "C.14", "sec": "C", "t": "Son muayenenin herhangi bir bölümü alt yükleniciye verilmişse Md. 26 şartları sağlanmış ve sorumluluk OK'da.", "d": "2014/33/AB Md. 26; ISO/IEC 17020 md. 6.3", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "D.1", "sec": "D", "t": "Muayene personeli elektrikli/hidrolik asansör türleri için yetkinlik kriterlerine göre yetkilendirilmiş; sahada performans izlemesi (eşlikli muayene) yapılıyor ve kayıtlı.", "d": "ISO/IEC 17020 md. 6.1.2, 6.1.3, 6.1.6–6.1.10 (pk)", "k": "Kayıt incelemesi + Mülakat + Tanık denetimi"}, {"no": "D.2", "sec": "D", "t": "Muayene personelinin monte edenle bağlantısı (istihdam, danışmanlık, akrabalık) tarafsızlık analizinde ele alınmış.", "d": "Md. 24(4), 24(8); ISO/IEC 17020 md. 4.1", "k": "Kayıt incelemesi + Mülakat"}, {"no": "E.1", "sec": "E", "t": "Son muayene raporu yapılan inceleme, doğrulama ve deneyleri ve sonuçlarını kanıtlarla birlikte kaydediyor.", "d": "2014/33/AB Md. 24(7)(d)", "k": "Dosya örneklemesi"}, {"no": "E.2", "sec": "E", "t": "Gözden geçirme ve belgelendirme kararı, değerlendirmeyi yapmamış yetkin kişi(ler)ce veriliyor; karar kaydı tarihli ve imzalı.", "d": "ISO/IEC 17065 md. 7.5, 7.6 (cd) / ISO/IEC 17021-1 md. 9.5", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "E.3", "sec": "E", "t": "TSGG veya uyumlaştırılmış standartlar/diğer teknik şartnameler karşılanmadığında düzeltici faaliyet isteniyor ve belge düzenlenmiyor.", "d": "2014/33/AB Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "E.4", "sec": "E", "t": "Ret kararında ayrıntılı gerekçe başvurana yazılı bildiriliyor; ret hâlinde alınması gereken düzeltici önlemler de belirtiliyor (Ek V md. 4).", "d": "2014/33/AB ilgili ek; Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "E.5", "sec": "E", "t": "OK kararlarına karşı itiraz prosedürü mevcut, müşteriye duyuruluyor ve itirazlar kararı verenden bağımsız kişilerce ele alınıyor.", "d": "2014/33/AB Md. 33; ISO/IEC 17020 md. 7.5, 7.6", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "F.1", "sec": "F", "t": "Son muayene belgesi yapılan inceleme ve deneyleri belirtiyor; belge/rapor içeriği ISO/IEC 17020 md. 7.4 şartlarını karşılıyor.", "d": "Ek V md. 4; ISO/IEC 17020 md. 7.4", "k": "Dosya örneklemesi"}, {"no": "F.2", "sec": "F", "t": "OK kimlik numarası CE işaretinin yanına OK tarafından iliştiriliyor veya iliştirtiliyor; etiket/numara kontrolü ve kayıt sistemi (hangi asansöre hangi etiket) mevcut.", "d": "Ek V md. 4, 5.1; Md. 18, 19", "k": "Prosedür incelemesi + Dosya örneklemesi + Tanık denetimi"}, {"no": "F.3", "sec": "F", "t": "Kayıt defterinin (Ek I 6.2) ilgili sayfaları OK tarafından dolduruluyor.", "d": "Ek V md. 4", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "F.4", "sec": "F", "t": "Monte edenin CE işaretini kabine iliştirmesi son muayenede doğrulanıyor; AB uygunluk beyanının monte eden tarafından düzenlendiği (OK'nın düzenlemediği) netleştirilmiş.", "d": "Ek V md. 5.1, 5.2", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "H.1", "sec": "H", "t": "Kayıt saklama: Direktif Ek V için OK saklama süresi öngörmüyor; son muayene kayıtları ve belgelerinin en az 10 yıl saklanması önerilir.", "d": "2014/33/AB ilgili ek; ISO/IEC 17065 md. 7.12 / 17021-1 md. 9.9 / 17020 md. 7.3, 8.4", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "H.2", "sec": "H", "t": "Bildirim otoritesine verilen/geri çekilen belgeler (onaylar) bildiriliyor; reddedilen, askıya alınan veya kısıtlanan belgelerin listesi periyodik olarak veya talep üzerine sunuluyor.", "d": "Ek V md. 6; Md. 34(1)", "k": "Kayıt incelemesi"}, {"no": "H.3", "sec": "H", "t": "Diğer onaylanmış kuruluşlara reddedilen, askıya alınan, geri çekilen veya kısıtlanan belgeler bildiriliyor; talep hâlinde verilen belgeler hakkında bilgi veriliyor.", "d": "Ek V md. 6; Md. 34(2)", "k": "Kayıt incelemesi"}, {"no": "H.4", "sec": "H", "t": "Komisyon ve üye devletlerin talebi hâlinde belge kopyası (ve ilgili eklerde öngörüldüğünde teknik dosya/rapor) verilebiliyor; prosedürde tanımlı.", "d": "Ek V md. 6", "k": "Prosedür incelemesi"}, {"no": "H.5", "sec": "H", "t": "Ekonomik operatörün saklama yükümlülüğü (AB uygunluk beyanı ve son muayene belgesi 10 yıl — Ek V md. 5.2) belge/sözleşme ekinde veya bilgilendirme notunda müşteriye bildiriliyor.", "d": "2014/33/AB ilgili ek (iyi uygulama)", "k": "Dosya örneklemesi"}, {"no": "H.6", "sec": "H", "t": "Gizlilik: değerlendirme sırasında elde edilen bilgiler yalnız yetkili makamlarla paylaşılıyor; mülkiyet hakları korunuyor.", "d": "2014/33/AB Md. 24(10)", "k": "Prosedür incelemesi + Mülakat"}, {"no": "H.7", "sec": "H", "t": "OK, NB-L Koordinasyon Grubu çalışmalarına katılıyor veya personeli bilgilendiriliyor; tasdik edilmiş RfU'ların (Temmuz 2026 derlemesi) bu modüle ilişkin olanları prosedürlere işlenmiş.", "d": "2014/33/AB Md. 24(11), Md. 36; NB-L RfU 16.07.2026", "k": "Prosedür incelemesi + Kayıt incelemesi + Mülakat"}], "tanik": {"faaliyet": "Tam son muayene (Ek V md. 3.3 deneyleri)", "grup": "Tablo 2'de yok (S1)", "not": "Uyumlu olmayan modül; gruplama AK tarafından gerekçelendirilmeli. Elektrikli ve hidrolik için ayrı tanık önerilir."}, "yon": "asansor"}, {"id": "VIII", "code": "L3", "grup": "asansor", "ad": "Asansör Modül G (Ek VIII)", "baslik": "EK VIII — ASANSÖRLER İÇİN BİRİM DOĞRULAMAYA DAYALI UYGUNLUK (MODÜL G)", "ozet": [["Ürün", "Tek bir asansör (model asansöre dayanmayan); tasarım + kurulu asansörün doğrulanması"], ["Direktif dayanağı", "Md. 16(1)(c)"], ["Başvuran / OK çıktısı", "Monte eden veya yetkili temsilcisi / yapılan deneylere ilişkin uygunluk belgesi; OK numarası kabinde CE yanında; kayıt defteri sayfaları"], ["Akreditasyon (EA-2/17 M:2026)", "EN ISO/IEC 17065 · cd + pk + t · kabul edilmeyen: 17021-1, 17024, 17025, 17029"], ["Tanık gruplaması", "Tablo 2: G ← G veya (B* + F1) veya (B* + F); G aynı zamanda B ve C2 için gruplama seçeneğidir"], ["Saklama süreleri", "OK: Direktifte süre yok (en az 10 yıl önerilir) · Monte eden: uygunluk belgesi + teknik dosya 10 yıl (md. 6)"]], "items": [{"no": "A.1", "sec": "A", "t": "Kuruluş bu modül (Ek VIII) için EN ISO/IEC 17065 esas alınarak akredite edilmiş/denetleniyor mu? Farklı bir standart kullanılıyorsa bildirim otoritesinin yayımlanmış bağlayıcı gerekliliğine dayanan gerekçe AK tarafından kayda alınmış mı?", "d": "EA-2/17 M:2026 §4.2, Annex A Tablo 1", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "A.2", "sec": "A", "t": "Bu modül için kabul edilmeyen standartlar (ISO/IEC 17021-1, 17024, 17025, 17029) akreditasyon dayanağı olarak kullanılmıyor.", "d": "EA-2/17 M:2026 Annex A Tablo 1", "k": "Kayıt incelemesi"}, {"no": "A.3", "sec": "A", "t": "'cd' gerekliliği: EN ISO/IEC 17065 md. 4.1.2, 4.1.3, 7.5 ve 7.6'nın (belgelendirme anlaşması, belge/işaret kullanımı, gözden geçirme ve karar) bu modül için ayrıca kanıtlandığı doğrulanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (cd)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "A.4", "sec": "A", "t": "'pk' gerekliliği: ürün bilgisine dayalı mesleki yargı — EN ISO/IEC 17020 md. 6.1.2, 6.1.3 ve 6.1.6–6.1.10 (yetkinlik kriterleri, görevlendirme, eğitim, gözetim, saha izleme, kayıtlar) bu modülün personeli için kanıtlanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (pk)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "A.5", "sec": "A", "t": "'t' gerekliliği: OK deneyleri kendisi yapıyorsa EN ISO/IEC 17025 md. 6 ve 7 (7.9 hariç) karşılanmalı; deneyler dış laboratuvarda yapılıyorsa Md. 26 kapsamında alt yüklenici değerlendirmesi aranmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (t); 2014/33/AB Md. 26", "k": "Prosedür incelemesi + Kayıt incelemesi + Tanık denetimi"}, {"no": "A.6", "sec": "A", "t": "Kapsam ifadesi: Direktif (2014/33/AB), ek ve modül (Ek VIII) ile ürün kapsamı (elektrikli / hidrolik tahrikli asansörler) açıkça yazılmış; NANDO'ya veri girişine uygun.", "d": "EA-2/17 M:2026 §5; ISO/IEC 17011 md. 7.8", "k": "Kayıt incelemesi"}, {"no": "A.7", "sec": "A", "t": "Akreditasyon kapsamı ile bildirim (NANDO) kapsamı tutarlı; bildirim dışı bir modül/ürün için belge düzenlenmemiş.", "d": "2014/33/AB Md. 28(3), Md. 32(1)", "k": "Kayıt incelemesi + Dosya örneklemesi"}, {"no": "A.8", "sec": "A", "t": "Tanık denetimi planı: kapsam döngüsünde en az bir birim doğrulamanın saha deneyleri izlenmiş ve tasarım değerlendirmesi dosya incelemesi + teknik mülakatla örneklenmiş mi?", "d": "EA-2/17 M:2026 Annex B Tablo 2", "k": "Kayıt incelemesi"}, {"no": "A.9", "sec": "A", "t": "İlk akreditasyonda tanık denetimi ertelendiyse 18 ay içinde tamamlandığı ve tanık öncesi akredite belge düzenlenmediği doğrulanmış.", "d": "EA-2/17 M:2026 Annex B (18 ay kuralı)", "k": "Kayıt incelemesi"}, {"no": "B.1", "sec": "B", "t": "Başvuru monte eden veya yetkili temsilcisi tarafından yapılıyor; yetkili temsilci başvurularında vekâletnamenin ilgili yükümlülükleri açıkça kapsadığı kontrol ediliyor.", "d": "Ek VIII md. 2.2, 7 (yetkili temsilci maddesi)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.2", "sec": "B", "t": "Başvuruda aynı başvurunun başka bir onaylanmış kuruluşa yapılmadığına dair yazılı beyan bulunuyor.", "d": "Ek VIII md. 2.2, 7 — tek OK beyanı", "k": "Dosya örneklemesi"}, {"no": "B.3", "sec": "B", "t": "Başvuru dosyası Direktifin istediği tüm unsurları içeriyor: (a) monte edenin/yetkili temsilcinin adı ve adresi, (b) asansörün kurulduğu yer, (c) benzer başvurunun başka OK'ya yapılmadığı beyanı, (d) teknik dosya.", "d": "Ek VIII md. 2.2, 7", "k": "Dosya örneklemesi"}, {"no": "B.4", "sec": "B", "t": "Başvurunun gözden geçirilmesinde kapsam (NANDO), yetkinlik ve kaynak yeterliliği ile tarafsızlık riski değerlendiriliyor ve kayda alınıyor.", "d": "ISO/IEC 17065 md. 7.3 / ISO/IEC 17021-1 md. 9.1.2; Md. 24(6)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.5", "sec": "B", "t": "Müşteri sözleşmesinde OK'nın ve akreditasyon kuruluşunun (tanık denetimi için) tesislere, sahalara ve kayıtlara erişim hakkı açıkça yazılı.", "d": "ISO/IEC 17065 md. 4.1.2; iyi uygulama: AA L05 §1.3", "k": "Dosya örneklemesi"}, {"no": "B.6", "sec": "B", "t": "Alt yüklenici veya bağlı kuruluş kullanılacaksa müşterinin onayı alınmış.", "d": "2014/33/AB Md. 26(3)", "k": "Dosya örneklemesi"}, {"no": "B.7", "sec": "B", "t": "Orantılılık: değerlendirme planı işletmenin büyüklüğü, yapısı, teknolojinin karmaşıklığı ve üretimin seri/kütle niteliği dikkate alınarak hazırlanmış; ancak koruma düzeyinden taviz verilmemiş.", "d": "2014/33/AB Md. 24(6)(c), Md. 32(2)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.8", "sec": "B", "t": "Reddedilen birim doğrulamanın yeniden başvurusunun aynı OK'ya yapıldığı kontrol ediliyor.", "d": "Ek VIII md. 4 (3. paragraf)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C.1", "sec": "C", "t": "Teknik dosya asgari unsurları içeriyor: (a) tanım, (b) tasarım ve imalat çizimleri/şemaları, (c) açıklamalar, (d) TSGG listesi, (e) standart listesi ve kısmi uygulamada bölümler, (f) güvenlik aksamlarının AB tip inceleme belgesi kopyaları, (g) hesap sonuçları, (h) deney raporları, (i) Ek I 6.2 talimat kopyası.", "d": "Ek VIII md. 3(a)–(i)", "k": "Dosya örneklemesi"}, {"no": "C.2", "sec": "C", "t": "Ek VIII md. 3(f)'nin aksamların AB tip inceleme belgesi kopyalarını istediği (Ek IV-B md. 3(f)'deki AB uygunluk beyanından farklı) prosedürde doğru yansıtılmış.", "d": "Ek VIII md. 3(f)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C.3", "sec": "C", "t": "OK teknik dosyayı inceleyerek tasarımın TSGG'ye uygunluğunu değerlendiriyor (tasarım değerlendirmesi pk gerektirir); kritik hesaplar doğrulanıyor.", "d": "Ek VIII md. 4 (1. paragraf)", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C.4", "sec": "C", "t": "Risk değerlendirmesinin asgari unsurları kontrol ediliyor.", "d": "NB-L RfU 0/007", "k": "Dosya örneklemesi"}, {"no": "C.5", "sec": "C", "t": "Standart dışı çözümler için OK kendi analizini ve uygun deneyleri yapıyor; çözüm ve gerekçe raporda.", "d": "Ek VIII md. 4; Md. 14", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C.6", "sec": "C", "t": "Gizli kalacak veya sonradan erişilemeyecek bölümler (kuyu yapısı, ankrajlar, ray bağlantıları) için ara muayene ihtiyacı değerlendiriliyor (iyi uygulama).", "d": "Ek VIII md. 2.1, 4", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C.7", "sec": "C", "t": "Asansör üzerinde ilgili uyumlaştırılmış standartlardaki veya eşdeğer deneyler yapılıyor; asgari olarak Ek V md. 3.3 (a), (b), (c) deneyleri dâhil.", "d": "Ek VIII md. 4 (1. paragraf); Ek V md. 3.3", "k": "Tanık denetimi"}, {"no": "C.8", "sec": "C", "t": "Sahadaki güvenlik aksamlarının dosyadaki AB tip inceleme belgeleriyle eşleştiği; Ek III dışı bileşen belgelerinin kabulü gerekçeli.", "d": "Ek VIII md. 3(f); NB-L RfU 1/010", "k": "Tanık denetimi"}, {"no": "C.9", "sec": "C", "t": "Kurtarma ve erişim yöntemleri fonksiyonel olarak kontrol ediliyor.", "d": "NB-L RfU 2/011, 2/012, 2/013", "k": "Tanık denetimi"}, {"no": "C.10", "sec": "C", "t": "Ölçüm ve deney ekipmanı kalibreli ve izlenebilir.", "d": "ISO/IEC 17025 md. 6.4, 6.5 (t)", "k": "Kayıt incelemesi + Tanık denetimi"}, {"no": "D.1", "sec": "D", "t": "Personel hem tasarım değerlendirmesi hem saha doğrulaması için yetkilendirilmiş; tek kişi her ikisini yapıyorsa iki yetkinlik de kanıtlı.", "d": "Md. 24(7); ISO/IEC 17020 md. 6.1.2–6.1.3 (pk)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "E.1", "sec": "E", "t": "Birim doğrulama raporu yapılan inceleme, doğrulama ve deneyleri ve sonuçlarını kanıtlarla birlikte kaydediyor.", "d": "2014/33/AB Md. 24(7)(d)", "k": "Dosya örneklemesi"}, {"no": "E.2", "sec": "E", "t": "Gözden geçirme ve belgelendirme kararı, değerlendirmeyi yapmamış yetkin kişi(ler)ce veriliyor; karar kaydı tarihli ve imzalı.", "d": "ISO/IEC 17065 md. 7.5, 7.6 (cd) / ISO/IEC 17021-1 md. 9.5", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "E.3", "sec": "E", "t": "TSGG veya uyumlaştırılmış standartlar/diğer teknik şartnameler karşılanmadığında düzeltici faaliyet isteniyor ve belge düzenlenmiyor.", "d": "2014/33/AB Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "E.4", "sec": "E", "t": "Ret kararında ayrıntılı gerekçe başvurana yazılı bildiriliyor; ret hâlinde alınması gereken düzeltici önlemler de belirtiliyor (Ek VIII md. 4).", "d": "2014/33/AB ilgili ek; Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "E.5", "sec": "E", "t": "OK kararlarına karşı itiraz prosedürü mevcut, müşteriye duyuruluyor ve itirazlar kararı verenden bağımsız kişilerce ele alınıyor.", "d": "2014/33/AB Md. 33; ISO/IEC 17065 md. 7.13", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "F.1", "sec": "F", "t": "Yapılan deneylere ilişkin uygunluk belgesi düzenleniyor; belge asansörü (yer, seri no, temel parametreler), dayanak dokümanları ve yapılan deneyleri tanımlıyor.", "d": "Ek VIII md. 4 (2. paragraf)", "k": "Dosya örneklemesi"}, {"no": "F.2", "sec": "F", "t": "Kayıt defterinin (Ek I 6.2) ilgili sayfaları OK tarafından dolduruluyor.", "d": "Ek VIII md. 4", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "F.3", "sec": "F", "t": "Monte edenin kabine CE işaretini ve OK sorumluluğunda OK kimlik numarasını iliştirmesi kontrol ediliyor; numara kullanım kaydı tutuluyor.", "d": "Ek VIII md. 5.1; Md. 19(3)", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "H.1", "sec": "H", "t": "Kayıt saklama: Direktif Ek VIII için OK saklama süresi öngörmüyor; teknik dosya incelemesi, deney kayıtları ve belgelerin en az 10 yıl saklanması önerilir.", "d": "2014/33/AB ilgili ek; ISO/IEC 17065 md. 7.12 / 17021-1 md. 9.9 / 17020 md. 7.3, 8.4", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "H.2", "sec": "H", "t": "Bildirim otoritesine verilen/geri çekilen belgeler (onaylar) bildiriliyor; reddedilen, askıya alınan veya kısıtlanan belgelerin listesi periyodik olarak veya talep üzerine sunuluyor.", "d": "Ek VIII md. 4 (son paragraf); Md. 34(1)", "k": "Kayıt incelemesi"}, {"no": "H.3", "sec": "H", "t": "Diğer onaylanmış kuruluşlara reddedilen, askıya alınan, geri çekilen veya kısıtlanan belgeler bildiriliyor; talep hâlinde verilen belgeler hakkında bilgi veriliyor.", "d": "Ek VIII md. 4 (son paragraf); Md. 34(2)", "k": "Kayıt incelemesi"}, {"no": "H.4", "sec": "H", "t": "Komisyon ve üye devletlerin talebi hâlinde belge kopyası (ve ilgili eklerde öngörüldüğünde teknik dosya/rapor) verilebiliyor; prosedürde tanımlı.", "d": "Ek VIII md. 4 (son paragraf)", "k": "Prosedür incelemesi"}, {"no": "H.5", "sec": "H", "t": "Ekonomik operatörün saklama yükümlülüğü (uygunluk belgesi ve teknik dosya 10 yıl — Ek VIII md. 6) belge/sözleşme ekinde veya bilgilendirme notunda müşteriye bildiriliyor.", "d": "2014/33/AB ilgili ek (iyi uygulama)", "k": "Dosya örneklemesi"}, {"no": "H.6", "sec": "H", "t": "Gizlilik: değerlendirme sırasında elde edilen bilgiler yalnız yetkili makamlarla paylaşılıyor; mülkiyet hakları korunuyor.", "d": "2014/33/AB Md. 24(10)", "k": "Prosedür incelemesi + Mülakat"}, {"no": "H.7", "sec": "H", "t": "OK, NB-L Koordinasyon Grubu çalışmalarına katılıyor veya personeli bilgilendiriliyor; tasdik edilmiş RfU'ların (Temmuz 2026 derlemesi) bu modüle ilişkin olanları prosedürlere işlenmiş.", "d": "2014/33/AB Md. 24(11), Md. 36; NB-L RfU 16.07.2026", "k": "Prosedür incelemesi + Kayıt incelemesi + Mülakat"}], "tanik": {"faaliyet": "Saha doğrulaması + tasarım değerlendirmesi", "grup": "G veya (B* + F1) veya (B* + F)", "not": "G tanığı B ve C2 için de gruplama seçeneğidir."}, "yon": "asansor"}, {"id": "X", "code": "L4", "grup": "asansor", "ad": "Asansör Modül E (Ek X)", "baslik": "EK X — ASANSÖRLER İÇİN ÜRÜN KALİTE GÜVENCESİNE DAYALI TİPE UYGUNLUK (MODÜL E)", "ozet": [["Ürün", "AB tip inceleme belgesine (Ek IV-B) veya Ek XI'e göre tasarlanmış asansörler — monte edenin son muayene ve deney kalite sistemi"], ["Direktif dayanağı", "Md. 16(1)(a)(ii) ve 16(1)(b)(ii)"], ["Başvuran / OK çıktısı", "Monte eden veya yetkili temsilcisi / kalite sistemi onay kararı; OK numarası kabinde CE yanında"], ["Akreditasyon (EA-2/17 M:2026)", "EN ISO/IEC 17065 · cd + qa · kabul edilmeyen: 17024, 17025, 17029"], ["Tanık gruplaması", "Tablo 2: E ← E veya E1 veya D veya D1 veya H veya H1"], ["Saklama süreleri", "OK: Direktifte süre yok (en az 10 yıl önerilir) · Monte eden: son asansörün piyasaya arzından sonra 10 yıl (md. 5)"]], "items": [{"no": "A.1", "sec": "A", "t": "Kuruluş bu modül (Ek X) için EN ISO/IEC 17065 esas alınarak akredite edilmiş/denetleniyor mu? Farklı bir standart kullanılıyorsa bildirim otoritesinin yayımlanmış bağlayıcı gerekliliğine dayanan gerekçe AK tarafından kayda alınmış mı?", "d": "EA-2/17 M:2026 §4.2, Annex A Tablo 1", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "A.2", "sec": "A", "t": "Bu modül için kabul edilmeyen standartlar (ISO/IEC 17024, 17025, 17029) akreditasyon dayanağı olarak kullanılmıyor.", "d": "EA-2/17 M:2026 Annex A Tablo 1", "k": "Kayıt incelemesi"}, {"no": "A.3", "sec": "A", "t": "'cd' gerekliliği: EN ISO/IEC 17065 md. 4.1.2, 4.1.3, 7.5 ve 7.6'nın (belgelendirme anlaşması, belge/işaret kullanımı, gözden geçirme ve karar) bu modül için ayrıca kanıtlandığı doğrulanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (cd)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "A.4", "sec": "A", "t": "'qa' gerekliliği: kalite sistemlerini değerlendirme ve onaylama yeteneği — EN ISO/IEC 17021-1 md. 7.1.1, 7.1.2, 7.2.4, 7.2.5, 7.2.8, 7.2.10 ve 9.1–9.4, 9.6 kanıtlanmalı (17065 ile akredite olunsa bile).", "d": "EA-2/17 M:2026 Annex A anahtarı (qa)", "k": "Prosedür incelemesi + Kayıt incelemesi + Mülakat"}, {"no": "A.5", "sec": "A", "t": "Kapsam ifadesi: Direktif (2014/33/AB), ek ve modül (Ek X) ile ürün kapsamı (elektrikli / hidrolik tahrikli asansörler) açıkça yazılmış; NANDO'ya veri girişine uygun.", "d": "EA-2/17 M:2026 §5; ISO/IEC 17011 md. 7.8", "k": "Kayıt incelemesi"}, {"no": "A.6", "sec": "A", "t": "Akreditasyon kapsamı ile bildirim (NANDO) kapsamı tutarlı; bildirim dışı bir modül/ürün için belge düzenlenmemiş.", "d": "2014/33/AB Md. 28(3), Md. 32(1)", "k": "Kayıt incelemesi + Dosya örneklemesi"}, {"no": "A.7", "sec": "A", "t": "Tanık denetimi planı: kapsam döngüsünde monte eden tesisinde ve bir kurulum sahasında KS denetimi izlenmiş mi?", "d": "EA-2/17 M:2026 Annex B Tablo 2", "k": "Kayıt incelemesi"}, {"no": "A.8", "sec": "A", "t": "İlk akreditasyonda tanık denetimi ertelendiyse 18 ay içinde tamamlandığı ve tanık öncesi akredite belge düzenlenmediği doğrulanmış.", "d": "EA-2/17 M:2026 Annex B (18 ay kuralı)", "k": "Kayıt incelemesi"}, {"no": "B.1", "sec": "B", "t": "Başvuru monte eden veya yetkili temsilcisi tarafından yapılıyor; yetkili temsilci başvurularında vekâletnamenin ilgili yükümlülükleri açıkça kapsadığı kontrol ediliyor.", "d": "Ek X md. 3.1, 8 (yetkili temsilci maddesi)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.2", "sec": "B", "t": "Başvuruda aynı başvurunun başka bir onaylanmış kuruluşa yapılmadığına dair yazılı beyan bulunuyor.", "d": "Ek X md. 3.1, 8 — tek OK beyanı", "k": "Dosya örneklemesi"}, {"no": "B.3", "sec": "B", "t": "Başvuru dosyası Direktifin istediği tüm unsurları içeriyor: (a) monte edenin/yetkili temsilcinin adı ve adresi, (b) kurulacak asansörlere ilişkin tüm bilgiler, (c) KS dokümantasyonu, (d) kurulacak asansörlerin teknik dosyası, (e) tek OK beyanı.", "d": "Ek X md. 3.1, 8", "k": "Dosya örneklemesi"}, {"no": "B.4", "sec": "B", "t": "Başvurunun gözden geçirilmesinde kapsam (NANDO), yetkinlik ve kaynak yeterliliği ile tarafsızlık riski değerlendiriliyor ve kayda alınıyor.", "d": "ISO/IEC 17065 md. 7.3 / ISO/IEC 17021-1 md. 9.1.2; Md. 24(6)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.5", "sec": "B", "t": "Müşteri sözleşmesinde OK'nın ve akreditasyon kuruluşunun (tanık denetimi için) tesislere, sahalara ve kayıtlara erişim hakkı açıkça yazılı.", "d": "ISO/IEC 17065 md. 4.1.2; iyi uygulama: AA L05 §1.3", "k": "Dosya örneklemesi"}, {"no": "B.6", "sec": "B", "t": "Alt yüklenici veya bağlı kuruluş kullanılacaksa müşterinin onayı alınmış.", "d": "2014/33/AB Md. 26(3)", "k": "Dosya örneklemesi"}, {"no": "B.7", "sec": "B", "t": "Orantılılık: değerlendirme planı işletmenin büyüklüğü, yapısı, teknolojinin karmaşıklığı ve üretimin seri/kütle niteliği dikkate alınarak hazırlanmış; ancak koruma düzeyinden taviz verilmemiş.", "d": "2014/33/AB Md. 24(6)(c), Md. 32(2)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.8", "sec": "B", "t": "Dayanak AB tip inceleme belgeleri (Ek IV-B) veya Ek XI onayı kapsamı ile KS onayının kapsamı eşleştiriliyor.", "d": "Ek X md. 1", "k": "Dosya örneklemesi"}, {"no": "C1.1", "sec": "C1", "t": "KS kapsamında her asansörün muayene edildiği ve uyumlaştırılmış standartlardaki veya eşdeğer deneylerin uygulandığı doğrulanıyor.", "d": "Ek X md. 3.2 (1. paragraf)", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C1.2", "sec": "C1", "t": "KS dokümantasyonu yazılı politika, prosedür ve talimatlarla sistematik ve tutarlı yorumlanabilir.", "d": "Ek X md. 3.2 (2. paragraf)", "k": "Dosya örneklemesi"}, {"no": "C1.3", "sec": "C1", "t": "(a) Kalite hedefleri tanımlı.", "d": "Ek X md. 3.2(a)", "k": "Dosya örneklemesi"}, {"no": "C1.4", "sec": "C1", "t": "(b) Ürün kalitesine ilişkin organizasyon, sorumluluk ve yetkiler tanımlı.", "d": "Ek X md. 3.2(b)", "k": "Dosya örneklemesi"}, {"no": "C1.5", "sec": "C1", "t": "(c) Piyasaya arzdan önce yapılacak muayene ve deneyler tanımlı ve asgari olarak Ek V md. 3.3 deneylerini içeriyor.", "d": "Ek X md. 3.2(c); Ek V md. 3.3", "k": "Dosya örneklemesi"}, {"no": "C1.6", "sec": "C1", "t": "(d) KS'nin etkin işleyişini izleme araçları tanımlı.", "d": "Ek X md. 3.2(d)", "k": "Dosya örneklemesi"}, {"no": "C1.7", "sec": "C1", "t": "(e) Kalite kayıtları (muayene raporları, deney verileri, kalibrasyon, personel nitelikleri).", "d": "Ek X md. 3.2(e)", "k": "Dosya örneklemesi"}, {"no": "C1.8", "sec": "C1", "t": "Monte edenin son muayene personelinin yetkinlik ve yetkilendirme kayıtları ile deney ekipmanının kalibrasyonu incelenmiş.", "d": "Ek X md. 3.2(e), 4.2(c)", "k": "Dosya örneklemesi"}, {"no": "C1.9", "sec": "C1", "t": "Son muayene alt yükleniciye verilmişse monte edenin güvenilirlik, yetkinlik ve bağımsızlık şartlarını içeren prosedürü, talimatları ve alt yüklenici işini değerlendirmesi OK tarafından kontrol edilmiş.", "d": "NB-L RfU 3/012", "k": "Dosya örneklemesi"}, {"no": "C1.10", "sec": "C1", "t": "Monte edenin son muayenede asansörün onaylı tipe ve varyasyon sınırlarına uygunluğunu kontrol ettiği doğrulanmış.", "d": "Ek X md. 1; Md. 16(3)", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C1.11", "sec": "C1", "t": "Denetim ekibi kalite yönetim sistemleri deneyimine ek olarak, ilgili asansör teknolojisinde değerlendirme deneyimi ve Ek I TSGG bilgisi olan en az bir üye içeriyor.", "d": "Ek X md. 3.3 (değerlendirme maddesi); Md. 24(7)", "k": "Kayıt incelemesi + Dosya örneklemesi"}, {"no": "C1.12", "sec": "C1", "t": "İlk değerlendirme monte edenin tesisine değerlendirme ziyaretini ve bir kurulum sahası ziyaretini içeriyor; ziyaret kayıtları (yer, tarih, görüşülen kişiler, örneklenen kayıtlar) dosyada.", "d": "Ek X md. 3.3", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C1.13", "sec": "C1", "t": "Denetim programı ve denetim süresi belirlenmiş; ilgili IAF MD dokümanları (ör. çok sahalı örnekleme, denetim süresi) dikkate alınmış; NB-L kararı varsa öncelikli.", "d": "ISO/IEC 17021-1 md. 9.1.3, 9.1.4 (qa); EA-2/17 M:2026 Annex A Not 4–5", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C1.14", "sec": "C1", "t": "Uyumlaştırılmış standart karinesi yalnız atfı AB Resmî Gazetesi'nde yayımlanmış bir standarda dayandırılıyor; ISO 9001 belgesi tek başına kalite sistemi onayının yerine kullanılmıyor.", "d": "Ek X md. 3.3 (karine cümlesi)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C1.15", "sec": "C1", "t": "Değerlendirme kararı başvurana bildiriliyor; bildirim denetim sonuçlarını ve gerekçeli değerlendirme kararını içeriyor.", "d": "Ek X md. 3.3", "k": "Dosya örneklemesi"}, {"no": "D.1", "sec": "D", "t": "KS denetçileri için asansör kurulumu ve son muayeneye özgü yetkinlik kriterleri tanımlı.", "d": "ISO/IEC 17021-1 md. 7.1.1, 7.1.2, 7.2.4, 7.2.5, 7.2.8, 7.2.10 (qa)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "E.1", "sec": "E", "t": "Denetim raporu yapılan inceleme, doğrulama ve deneyleri ve sonuçlarını kanıtlarla birlikte kaydediyor.", "d": "2014/33/AB Md. 24(7)(d)", "k": "Dosya örneklemesi"}, {"no": "E.2", "sec": "E", "t": "Gözden geçirme ve belgelendirme kararı, değerlendirmeyi yapmamış yetkin kişi(ler)ce veriliyor; karar kaydı tarihli ve imzalı.", "d": "ISO/IEC 17065 md. 7.5, 7.6 (cd) / ISO/IEC 17021-1 md. 9.5", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "E.3", "sec": "E", "t": "TSGG veya uyumlaştırılmış standartlar/diğer teknik şartnameler karşılanmadığında düzeltici faaliyet isteniyor ve belge düzenlenmiyor.", "d": "2014/33/AB Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "E.4", "sec": "E", "t": "Ret kararında ayrıntılı gerekçe başvurana yazılı bildiriliyor.", "d": "2014/33/AB ilgili ek; Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "E.5", "sec": "E", "t": "OK kararlarına karşı itiraz prosedürü mevcut, müşteriye duyuruluyor ve itirazlar kararı verenden bağımsız kişilerce ele alınıyor.", "d": "2014/33/AB Md. 33; ISO/IEC 17065 md. 7.13", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "F.1", "sec": "F", "t": "Kalite sistemi onay belgesi asgari şu bilgileri içeriyor: OK adı ve kimlik no; belge sahibinin adı/adresi; dayanak (2014/33/AB Ek …); belge no; onay kapsamı; değerlendirme raporuyla ilişki; ek bilgiler; yer, tarih, imza ve ad; geçerlilik süresi.", "d": "NB-L RfU 3/005", "k": "Dosya örneklemesi"}, {"no": "F.2", "sec": "F", "t": "OK kimlik numarasının CE işaretinin yanına OK tarafından iliştirilmesi veya iliştirtilmesi ve monte edenin kabine CE + OK numarasını iliştirmesi kuralları tanımlı; numara kullanımı (asansör seri no listesi) izleniyor.", "d": "Ek X md. 3.4.2 (son paragraf), 7.1; Md. 19(3)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "G.1", "sec": "G", "t": "Kalite sistemindeki planlanan değişiklikler OK'ya bildiriliyor; OK değişikliği değerlendirip sistemin şartları karşılamaya devam edip etmediğine veya yeniden değerlendirme gerekip gerekmediğine karar veriyor; karar gerekçeli bildiriliyor.", "d": "Ek X md. 3.4.1, 3.4.2", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "G.2", "sec": "G", "t": "Gözetimde OK'ya kurulum, muayene ve deney yerlerine erişim sağlanıyor; KS dokümantasyonu ve kalite kayıtları (muayene raporları, deney verileri, kalibrasyon, personel nitelikleri) örnekleniyor.", "d": "Ek X md. 4.2", "k": "Dosya örneklemesi"}, {"no": "G.3", "sec": "G", "t": "Periyodik denetimler yapılıyor ve her denetim sonunda müşteriye denetim raporu veriliyor; gözetim sıklığı tanımlı (en az yıllık önerilir) ve uygulanıyor.", "d": "Ek X md. 4.3; ISO/IEC 17021-1 md. 9.6 (qa)", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "G.4", "sec": "G", "t": "Habersiz ziyaret politikası tanımlı (kurulum sahalarına; gerektiğinde KS'nin ve asansörün işleyişini kontrol için deney); ziyaretlerde gerektiğinde deney yapılıyor/yaptırılıyor; ziyaret raporu ve varsa deney raporu veriliyor.", "d": "Ek X md. 4.4", "k": "Prosedür incelemesi + Dosya örneklemesi + Kayıt incelemesi"}, {"no": "G.5", "sec": "G", "t": "Onay kapsamı sınırlamaları yalnız ürünle ilişkili (ör. teknoloji, aksam türü, tahrik tipi) olarak tanımlanıyor.", "d": "NB-L RfU 3/004", "k": "Dosya örneklemesi"}, {"no": "G.6", "sec": "G", "t": "Gözetimde uygunsuzluk tespitinde düzeltici faaliyet isteniyor; etkisiz kalırsa onay kısıtlanıyor, askıya alınıyor veya geri çekiliyor.", "d": "2014/33/AB Md. 32(4), 32(5)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "G.7", "sec": "G", "t": "Onayın geçerlilik süresi ve yeniden belgelendirme döngüsü tanımlı ve belgede yazılı.", "d": "NB-L RfU 3/005 (md. 9 geçerlilik süresi); ISO/IEC 17021-1 md. 9.6.3", "k": "Dosya örneklemesi"}, {"no": "G.8", "sec": "G", "t": "Gözetimde ziyaret edilen kurulum sahaları asansör türü, bölge ve ekip çeşitliliğini kapsayacak şekilde örnekleniyor.", "d": "Ek X md. 4.3, 4.4", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "H.1", "sec": "H", "t": "Kayıt saklama: Direktif Ek X için OK saklama süresi öngörmüyor; onay kararları, denetim/ziyaret raporları ve kayıtların en az 10 yıl saklanması önerilir.", "d": "2014/33/AB ilgili ek; ISO/IEC 17065 md. 7.12 / 17021-1 md. 9.9 / 17020 md. 7.3, 8.4", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "H.2", "sec": "H", "t": "Bildirim otoritesine verilen/geri çekilen belgeler (onaylar) bildiriliyor; reddedilen, askıya alınan veya kısıtlanan belgelerin listesi periyodik olarak veya talep üzerine sunuluyor.", "d": "Ek X md. 6; Md. 34(1)", "k": "Kayıt incelemesi"}, {"no": "H.3", "sec": "H", "t": "Diğer onaylanmış kuruluşlara reddedilen, askıya alınan, geri çekilen veya kısıtlanan belgeler bildiriliyor; talep hâlinde verilen belgeler hakkında bilgi veriliyor.", "d": "Ek X md. 6; Md. 34(2)", "k": "Kayıt incelemesi"}, {"no": "H.4", "sec": "H", "t": "Komisyon ve üye devletlerin talebi hâlinde belge kopyası (ve ilgili eklerde öngörüldüğünde teknik dosya/rapor) verilebiliyor; prosedürde tanımlı.", "d": "Ek X md. 6", "k": "Prosedür incelemesi"}, {"no": "H.5", "sec": "H", "t": "Ekonomik operatörün saklama yükümlülüğü (son asansörün piyasaya arzından sonra 10 yıl — Ek X md. 5) belge/sözleşme ekinde veya bilgilendirme notunda müşteriye bildiriliyor.", "d": "2014/33/AB ilgili ek (iyi uygulama)", "k": "Dosya örneklemesi"}, {"no": "H.6", "sec": "H", "t": "Gizlilik: değerlendirme sırasında elde edilen bilgiler yalnız yetkili makamlarla paylaşılıyor; mülkiyet hakları korunuyor.", "d": "2014/33/AB Md. 24(10)", "k": "Prosedür incelemesi + Mülakat"}, {"no": "H.7", "sec": "H", "t": "OK, NB-L Koordinasyon Grubu çalışmalarına katılıyor veya personeli bilgilendiriliyor; tasdik edilmiş RfU'ların (Temmuz 2026 derlemesi) bu modüle ilişkin olanları prosedürlere işlenmiş.", "d": "2014/33/AB Md. 24(11), Md. 36; NB-L RfU 16.07.2026", "k": "Prosedür incelemesi + Kayıt incelemesi + Mülakat"}], "tanik": {"faaliyet": "Monte eden tesisi + kurulum sahası denetimi", "grup": "E veya E1 veya D veya D1 veya H veya H1", "not": "Daha karmaşık modül seçilmeli (Annex B ilke 3)."}, "yon": "asansor"}, {"id": "XII", "code": "L5", "grup": "asansor", "ad": "Asansör Modül D (Ek XII)", "baslik": "EK XII — ASANSÖRLER İÇİN ÜRETİM KALİTE GÜVENCESİNE DAYALI TİPE UYGUNLUK (MODÜL D)", "ozet": [["Ürün", "AB tip inceleme belgesine (Ek IV-B) veya Ek XI'e göre tasarlanmış asansörler — imalat, montaj, kurulum, son muayene ve deney kalite sistemi"], ["Direktif dayanağı", "Md. 16(1)(a)(iii) ve 16(1)(b)(iii)"], ["Başvuran / OK çıktısı", "Monte eden veya yetkili temsilcisi / kalite sistemi onay kararı; OK numarası kabinde CE yanında"], ["Akreditasyon (EA-2/17 M:2026)", "EN ISO/IEC 17065 · cd + qa · kabul edilmeyen: 17024, 17025, 17029"], ["Tanık gruplaması", "Tablo 2: D ← D veya D1 veya H veya H1 veya E veya E1 (D, E'den kapsamlıdır; gruplamada daha karmaşık olan seçilir)"], ["Saklama süreleri", "OK: Direktifte süre yok (en az 10 yıl önerilir) · Monte eden: 10 yıl (md. 5)"]], "items": [{"no": "A.1", "sec": "A", "t": "Kuruluş bu modül (Ek XII) için EN ISO/IEC 17065 esas alınarak akredite edilmiş/denetleniyor mu? Farklı bir standart kullanılıyorsa bildirim otoritesinin yayımlanmış bağlayıcı gerekliliğine dayanan gerekçe AK tarafından kayda alınmış mı?", "d": "EA-2/17 M:2026 §4.2, Annex A Tablo 1", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "A.2", "sec": "A", "t": "Bu modül için kabul edilmeyen standartlar (ISO/IEC 17024, 17025, 17029) akreditasyon dayanağı olarak kullanılmıyor.", "d": "EA-2/17 M:2026 Annex A Tablo 1", "k": "Kayıt incelemesi"}, {"no": "A.3", "sec": "A", "t": "'cd' gerekliliği: EN ISO/IEC 17065 md. 4.1.2, 4.1.3, 7.5 ve 7.6'nın (belgelendirme anlaşması, belge/işaret kullanımı, gözden geçirme ve karar) bu modül için ayrıca kanıtlandığı doğrulanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (cd)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "A.4", "sec": "A", "t": "'qa' gerekliliği: kalite sistemlerini değerlendirme ve onaylama yeteneği — EN ISO/IEC 17021-1 md. 7.1.1, 7.1.2, 7.2.4, 7.2.5, 7.2.8, 7.2.10 ve 9.1–9.4, 9.6 kanıtlanmalı (17065 ile akredite olunsa bile).", "d": "EA-2/17 M:2026 Annex A anahtarı (qa)", "k": "Prosedür incelemesi + Kayıt incelemesi + Mülakat"}, {"no": "A.5", "sec": "A", "t": "Kapsam ifadesi: Direktif (2014/33/AB), ek ve modül (Ek XII) ile ürün kapsamı (elektrikli / hidrolik tahrikli asansörler) açıkça yazılmış; NANDO'ya veri girişine uygun.", "d": "EA-2/17 M:2026 §5; ISO/IEC 17011 md. 7.8", "k": "Kayıt incelemesi"}, {"no": "A.6", "sec": "A", "t": "Akreditasyon kapsamı ile bildirim (NANDO) kapsamı tutarlı; bildirim dışı bir modül/ürün için belge düzenlenmemiş.", "d": "2014/33/AB Md. 28(3), Md. 32(1)", "k": "Kayıt incelemesi + Dosya örneklemesi"}, {"no": "A.7", "sec": "A", "t": "Tanık denetimi planı: kapsam döngüsünde monte eden tesisinde ve bir kurulum sahasında KS denetimi izlenmiş mi?", "d": "EA-2/17 M:2026 Annex B Tablo 2", "k": "Kayıt incelemesi"}, {"no": "A.8", "sec": "A", "t": "İlk akreditasyonda tanık denetimi ertelendiyse 18 ay içinde tamamlandığı ve tanık öncesi akredite belge düzenlenmediği doğrulanmış.", "d": "EA-2/17 M:2026 Annex B (18 ay kuralı)", "k": "Kayıt incelemesi"}, {"no": "B.1", "sec": "B", "t": "Başvuru monte eden veya yetkili temsilcisi tarafından yapılıyor; yetkili temsilci başvurularında vekâletnamenin ilgili yükümlülükleri açıkça kapsadığı kontrol ediliyor.", "d": "Ek XII md. 3.1, 8 (yetkili temsilci maddesi)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.2", "sec": "B", "t": "Başvuruda aynı başvurunun başka bir onaylanmış kuruluşa yapılmadığına dair yazılı beyan bulunuyor.", "d": "Ek XII md. 3.1, 8 — tek OK beyanı", "k": "Dosya örneklemesi"}, {"no": "B.3", "sec": "B", "t": "Başvuru dosyası Direktifin istediği tüm unsurları içeriyor: (a) monte edenin/yetkili temsilcinin adı ve adresi, (b) kurulacak asansörlere ilişkin tüm bilgiler, (c) KS dokümantasyonu, (d) kurulacak asansörlerin teknik dosyası, (e) tek OK beyanı.", "d": "Ek XII md. 3.1, 8", "k": "Dosya örneklemesi"}, {"no": "B.4", "sec": "B", "t": "Başvurunun gözden geçirilmesinde kapsam (NANDO), yetkinlik ve kaynak yeterliliği ile tarafsızlık riski değerlendiriliyor ve kayda alınıyor.", "d": "ISO/IEC 17065 md. 7.3 / ISO/IEC 17021-1 md. 9.1.2; Md. 24(6)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.5", "sec": "B", "t": "Müşteri sözleşmesinde OK'nın ve akreditasyon kuruluşunun (tanık denetimi için) tesislere, sahalara ve kayıtlara erişim hakkı açıkça yazılı.", "d": "ISO/IEC 17065 md. 4.1.2; iyi uygulama: AA L05 §1.3", "k": "Dosya örneklemesi"}, {"no": "B.6", "sec": "B", "t": "Alt yüklenici veya bağlı kuruluş kullanılacaksa müşterinin onayı alınmış.", "d": "2014/33/AB Md. 26(3)", "k": "Dosya örneklemesi"}, {"no": "B.7", "sec": "B", "t": "Orantılılık: değerlendirme planı işletmenin büyüklüğü, yapısı, teknolojinin karmaşıklığı ve üretimin seri/kütle niteliği dikkate alınarak hazırlanmış; ancak koruma düzeyinden taviz verilmemiş.", "d": "2014/33/AB Md. 24(6)(c), Md. 32(2)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.8", "sec": "B", "t": "Dayanak AB tip inceleme belgeleri (Ek IV-B) veya Ek XI onayı kapsamı ile KS onayının kapsamı eşleştiriliyor.", "d": "Ek XII md. 1", "k": "Dosya örneklemesi"}, {"no": "C1.1", "sec": "C1", "t": "KS, imalat, montaj, kurulum, son muayene ve deneyi kapsıyor; KS dokümantasyonu yazılı politika, prosedür ve talimatlarla sistematik.", "d": "Ek XII md. 2, 3.2", "k": "Dosya örneklemesi"}, {"no": "C1.2", "sec": "C1", "t": "(a) Ürün kalitesine ilişkin kalite hedefleri, organizasyon, sorumluluk ve yetkiler.", "d": "Ek XII md. 3.2(a)", "k": "Dosya örneklemesi"}, {"no": "C1.3", "sec": "C1", "t": "(b) İmalat, kalite kontrol ve kalite güvence teknikleri, süreçleri ve sistematik faaliyetleri (tedarikçi ve aksam kabul kontrolü dâhil).", "d": "Ek XII md. 3.2(b)", "k": "Dosya örneklemesi"}, {"no": "C1.4", "sec": "C1", "t": "(c) Kurulumdan önce, kurulum sırasında ve sonrasında yapılacak muayene ve deneyler (asgari Ek V md. 3.3 deneyleri önerilir).", "d": "Ek XII md. 3.2(c)", "k": "Dosya örneklemesi"}, {"no": "C1.5", "sec": "C1", "t": "(d) Kalite kayıtları (muayene raporları, deney verileri, kalibrasyon, personel nitelikleri).", "d": "Ek XII md. 3.2(d)", "k": "Dosya örneklemesi"}, {"no": "C1.6", "sec": "C1", "t": "(e) İstenen ürün kalitesine ulaşılmasının ve KS'nin etkin işleyişinin izlenmesi.", "d": "Ek XII md. 3.2(e)", "k": "Dosya örneklemesi"}, {"no": "C1.7", "sec": "C1", "t": "Sipariş konfigürasyonunun onaylı tipin varyasyon aralığıyla eşleştirildiği ve aralık dışı konfigürasyonun ek onaya yönlendirildiği kontrol edilmiş.", "d": "Ek XII md. 1; Md. 16(3); Ek IV-B md. 8", "k": "Dosya örneklemesi"}, {"no": "C1.8", "sec": "C1", "t": "Montaj personeli (taşeron dâhil) yetkinliği, montaj talimatları ve saha kontrol listeleri incelenmiş.", "d": "Ek XII md. 3.2(b), 3.2(d)", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C1.9", "sec": "C1", "t": "Son muayene alt yükleniciye verilmişse monte edenin ilgili prosedürü ve uygulaması OK tarafından kontrol edilmiş.", "d": "NB-L RfU 3/012", "k": "Dosya örneklemesi"}, {"no": "C1.10", "sec": "C1", "t": "Denetim ekibi kalite yönetim sistemleri deneyimine ek olarak, ilgili asansör teknolojisinde değerlendirme deneyimi ve Ek I TSGG bilgisi olan en az bir üye içeriyor.", "d": "Ek XII md. 3.3 (değerlendirme maddesi); Md. 24(7)", "k": "Kayıt incelemesi + Dosya örneklemesi"}, {"no": "C1.11", "sec": "C1", "t": "İlk değerlendirme monte edenin tesisine değerlendirme ziyaretini ve bir kurulum sahası ziyaretini içeriyor; ziyaret kayıtları (yer, tarih, görüşülen kişiler, örneklenen kayıtlar) dosyada.", "d": "Ek XII md. 3.3", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C1.12", "sec": "C1", "t": "Denetim programı ve denetim süresi belirlenmiş; ilgili IAF MD dokümanları (ör. çok sahalı örnekleme, denetim süresi) dikkate alınmış; NB-L kararı varsa öncelikli.", "d": "ISO/IEC 17021-1 md. 9.1.3, 9.1.4 (qa); EA-2/17 M:2026 Annex A Not 4–5", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C1.13", "sec": "C1", "t": "Uyumlaştırılmış standart karinesi yalnız atfı AB Resmî Gazetesi'nde yayımlanmış bir standarda dayandırılıyor; ISO 9001 belgesi tek başına kalite sistemi onayının yerine kullanılmıyor.", "d": "Ek XII md. 3.3 (karine cümlesi)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C1.14", "sec": "C1", "t": "Değerlendirme kararı başvurana bildiriliyor; bildirim denetim sonuçlarını ve gerekçeli değerlendirme kararını içeriyor.", "d": "Ek XII md. 3.3", "k": "Dosya örneklemesi"}, {"no": "D.1", "sec": "D", "t": "KS denetçileri için asansör imalatı, montajı ve kurulumuna özgü yetkinlik kriterleri tanımlı.", "d": "ISO/IEC 17021-1 md. 7.1.1, 7.1.2, 7.2.4, 7.2.5, 7.2.8, 7.2.10 (qa)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "E.1", "sec": "E", "t": "Denetim raporu yapılan inceleme, doğrulama ve deneyleri ve sonuçlarını kanıtlarla birlikte kaydediyor.", "d": "2014/33/AB Md. 24(7)(d)", "k": "Dosya örneklemesi"}, {"no": "E.2", "sec": "E", "t": "Gözden geçirme ve belgelendirme kararı, değerlendirmeyi yapmamış yetkin kişi(ler)ce veriliyor; karar kaydı tarihli ve imzalı.", "d": "ISO/IEC 17065 md. 7.5, 7.6 (cd) / ISO/IEC 17021-1 md. 9.5", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "E.3", "sec": "E", "t": "TSGG veya uyumlaştırılmış standartlar/diğer teknik şartnameler karşılanmadığında düzeltici faaliyet isteniyor ve belge düzenlenmiyor.", "d": "2014/33/AB Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "E.4", "sec": "E", "t": "Ret kararında ayrıntılı gerekçe başvurana yazılı bildiriliyor.", "d": "2014/33/AB ilgili ek; Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "E.5", "sec": "E", "t": "OK kararlarına karşı itiraz prosedürü mevcut, müşteriye duyuruluyor ve itirazlar kararı verenden bağımsız kişilerce ele alınıyor.", "d": "2014/33/AB Md. 33; ISO/IEC 17065 md. 7.13", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "F.1", "sec": "F", "t": "Kalite sistemi onay belgesi asgari şu bilgileri içeriyor: OK adı ve kimlik no; belge sahibinin adı/adresi; dayanak (2014/33/AB Ek …); belge no; onay kapsamı; değerlendirme raporuyla ilişki; ek bilgiler; yer, tarih, imza ve ad; geçerlilik süresi.", "d": "NB-L RfU 3/005", "k": "Dosya örneklemesi"}, {"no": "F.2", "sec": "F", "t": "OK kimlik numarasının CE işaretinin yanına OK tarafından iliştirilmesi veya iliştirtilmesi ve monte edenin kabine CE + OK numarasını iliştirmesi kuralları tanımlı; numara kullanımı izleniyor.", "d": "Ek XII md. 3.4.2 (son paragraf), 7.1; Md. 19(3)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "G.1", "sec": "G", "t": "Kalite sistemindeki planlanan değişiklikler OK'ya bildiriliyor; OK değişikliği değerlendirip sistemin şartları karşılamaya devam edip etmediğine veya yeniden değerlendirme gerekip gerekmediğine karar veriyor; karar gerekçeli bildiriliyor.", "d": "Ek XII md. 3.4.1, 3.4.2", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "G.2", "sec": "G", "t": "Gözetimde OK'ya imalat, montaj, kurulum, muayene, deney ve depolama yerlerine erişim sağlanıyor; KS dokümantasyonu ve kalite kayıtları (muayene raporları, deney verileri, kalibrasyon, personel nitelikleri) örnekleniyor.", "d": "Ek XII md. 4.2", "k": "Dosya örneklemesi"}, {"no": "G.3", "sec": "G", "t": "Periyodik denetimler yapılıyor ve her denetim sonunda müşteriye denetim raporu veriliyor; gözetim sıklığı tanımlı (en az yıllık önerilir) ve uygulanıyor.", "d": "Ek XII md. 4.3; ISO/IEC 17021-1 md. 9.6 (qa)", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "G.4", "sec": "G", "t": "Habersiz ziyaret politikası tanımlı (monte edene; gerektiğinde KS'nin doğru işlediğini doğrulamak için deney); ziyaretlerde gerektiğinde deney yapılıyor/yaptırılıyor; ziyaret raporu ve varsa deney raporu veriliyor.", "d": "Ek XII md. 4.4", "k": "Prosedür incelemesi + Dosya örneklemesi + Kayıt incelemesi"}, {"no": "G.5", "sec": "G", "t": "Onay kapsamı sınırlamaları yalnız ürünle ilişkili (ör. teknoloji, aksam türü, tahrik tipi) olarak tanımlanıyor.", "d": "NB-L RfU 3/004", "k": "Dosya örneklemesi"}, {"no": "G.6", "sec": "G", "t": "Gözetimde uygunsuzluk tespitinde düzeltici faaliyet isteniyor; etkisiz kalırsa onay kısıtlanıyor, askıya alınıyor veya geri çekiliyor.", "d": "2014/33/AB Md. 32(4), 32(5)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "G.7", "sec": "G", "t": "Onayın geçerlilik süresi ve yeniden belgelendirme döngüsü tanımlı ve belgede yazılı.", "d": "NB-L RfU 3/005 (md. 9 geçerlilik süresi); ISO/IEC 17021-1 md. 9.6.3", "k": "Dosya örneklemesi"}, {"no": "G.8", "sec": "G", "t": "Gözetimde imalat/montaj tesisleri ile kurulum sahaları birlikte örnekleniyor.", "d": "Ek XII md. 4.2, 4.3", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "H.1", "sec": "H", "t": "Kayıt saklama: Direktif Ek XII için OK saklama süresi öngörmüyor; onay kararları, denetim/ziyaret raporları ve kayıtların en az 10 yıl saklanması önerilir.", "d": "2014/33/AB ilgili ek; ISO/IEC 17065 md. 7.12 / 17021-1 md. 9.9 / 17020 md. 7.3, 8.4", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "H.2", "sec": "H", "t": "Bildirim otoritesine verilen/geri çekilen belgeler (onaylar) bildiriliyor; reddedilen, askıya alınan veya kısıtlanan belgelerin listesi periyodik olarak veya talep üzerine sunuluyor.", "d": "Ek XII md. 6; Md. 34(1)", "k": "Kayıt incelemesi"}, {"no": "H.3", "sec": "H", "t": "Diğer onaylanmış kuruluşlara reddedilen, askıya alınan, geri çekilen veya kısıtlanan belgeler bildiriliyor; talep hâlinde verilen belgeler hakkında bilgi veriliyor.", "d": "Ek XII md. 6; Md. 34(2)", "k": "Kayıt incelemesi"}, {"no": "H.4", "sec": "H", "t": "Komisyon ve üye devletlerin talebi hâlinde belge kopyası (ve ilgili eklerde öngörüldüğünde teknik dosya/rapor) verilebiliyor; prosedürde tanımlı.", "d": "Ek XII md. 6", "k": "Prosedür incelemesi"}, {"no": "H.5", "sec": "H", "t": "Ekonomik operatörün saklama yükümlülüğü (10 yıl — Ek XII md. 5) belge/sözleşme ekinde veya bilgilendirme notunda müşteriye bildiriliyor.", "d": "2014/33/AB ilgili ek (iyi uygulama)", "k": "Dosya örneklemesi"}, {"no": "H.6", "sec": "H", "t": "Gizlilik: değerlendirme sırasında elde edilen bilgiler yalnız yetkili makamlarla paylaşılıyor; mülkiyet hakları korunuyor.", "d": "2014/33/AB Md. 24(10)", "k": "Prosedür incelemesi + Mülakat"}, {"no": "H.7", "sec": "H", "t": "OK, NB-L Koordinasyon Grubu çalışmalarına katılıyor veya personeli bilgilendiriliyor; tasdik edilmiş RfU'ların (Temmuz 2026 derlemesi) bu modüle ilişkin olanları prosedürlere işlenmiş.", "d": "2014/33/AB Md. 24(11), Md. 36; NB-L RfU 16.07.2026", "k": "Prosedür incelemesi + Kayıt incelemesi + Mülakat"}], "tanik": {"faaliyet": "Monte eden tesisi + kurulum sahası denetimi", "grup": "D veya D1 veya H veya H1 veya E veya E1", "not": "D, E'yi kapsar; D tanığı E için de kullanılabilir."}, "yon": "asansor"}, {"id": "XI", "code": "L6", "grup": "asansor", "ad": "Asansör Modül H1 (Ek XI)", "baslik": "EK XI — ASANSÖRLER İÇİN TAM KALİTE GÜVENCESİ VE TASARIM İNCELEMESİNE DAYALI UYGUNLUK (MODÜL H1)", "ozet": [["Ürün", "Monte edenin tasarım, imalat, montaj, kurulum, son muayene ve deney faaliyetleri; tasarım uyumlaştırılmış standartlara tam uymuyorsa AB tasarım incelemesi"], ["Direktif dayanağı", "Md. 16(1)(d); ayrıca Md. 16(1)(b) yolunda Ek V, X veya XII için tasarım dayanağı"], ["Başvuran / OK çıktısı", "Monte eden veya yetkili temsilcisi / tam kalite sistemi onay kararı + gerekiyorsa AB tasarım inceleme belgesi; OK numarası kabinde CE yanında"], ["Akreditasyon (EA-2/17 M:2026)", "EN ISO/IEC 17065 · cd + qa + pk · kabul edilmeyen: 17024, 17025, 17029"], ["Tanık gruplaması", "Tablo 2: H1 ← H1 veya (B* + H); H1 aynı zamanda B, D, E ve H için gruplama seçeneğidir"], ["Saklama süreleri", "OK: onay kararı, ekleri ve teknik dosya 15 yıl (md. 6) · Monte eden: 10 yıl (md. 3.3.5, 5)"]], "items": [{"no": "A.1", "sec": "A", "t": "Kuruluş bu modül (Ek XI) için EN ISO/IEC 17065 esas alınarak akredite edilmiş/denetleniyor mu? Farklı bir standart kullanılıyorsa bildirim otoritesinin yayımlanmış bağlayıcı gerekliliğine dayanan gerekçe AK tarafından kayda alınmış mı?", "d": "EA-2/17 M:2026 §4.2, Annex A Tablo 1", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "A.2", "sec": "A", "t": "Bu modül için kabul edilmeyen standartlar (ISO/IEC 17024, 17025, 17029) akreditasyon dayanağı olarak kullanılmıyor.", "d": "EA-2/17 M:2026 Annex A Tablo 1", "k": "Kayıt incelemesi"}, {"no": "A.3", "sec": "A", "t": "'cd' gerekliliği: EN ISO/IEC 17065 md. 4.1.2, 4.1.3, 7.5 ve 7.6'nın (belgelendirme anlaşması, belge/işaret kullanımı, gözden geçirme ve karar) bu modül için ayrıca kanıtlandığı doğrulanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (cd)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "A.4", "sec": "A", "t": "'qa' gerekliliği: kalite sistemlerini değerlendirme ve onaylama yeteneği — EN ISO/IEC 17021-1 md. 7.1.1, 7.1.2, 7.2.4, 7.2.5, 7.2.8, 7.2.10 ve 9.1–9.4, 9.6 kanıtlanmalı (17065 ile akredite olunsa bile).", "d": "EA-2/17 M:2026 Annex A anahtarı (qa)", "k": "Prosedür incelemesi + Kayıt incelemesi + Mülakat"}, {"no": "A.5", "sec": "A", "t": "'pk' gerekliliği: ürün bilgisine dayalı mesleki yargı — EN ISO/IEC 17020 md. 6.1.2, 6.1.3 ve 6.1.6–6.1.10 (yetkinlik kriterleri, görevlendirme, eğitim, gözetim, saha izleme, kayıtlar) bu modülün personeli için kanıtlanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (pk)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "A.6", "sec": "A", "t": "Kapsam ifadesi: Direktif (2014/33/AB), ek ve modül (Ek XI) ile ürün kapsamı (elektrikli / hidrolik tahrikli asansörler) açıkça yazılmış; NANDO'ya veri girişine uygun.", "d": "EA-2/17 M:2026 §5; ISO/IEC 17011 md. 7.8", "k": "Kayıt incelemesi"}, {"no": "A.7", "sec": "A", "t": "Akreditasyon kapsamı ile bildirim (NANDO) kapsamı tutarlı; bildirim dışı bir modül/ürün için belge düzenlenmemiş.", "d": "2014/33/AB Md. 28(3), Md. 32(1)", "k": "Kayıt incelemesi + Dosya örneklemesi"}, {"no": "A.8", "sec": "A", "t": "Tanık denetimi planı: kapsam döngüsünde monte eden tesisinde (tasarım bölümü dâhil) ve bir kurulum sahasında KS denetimi izlenmiş; tasarım incelemesi dosya incelemesi + teknik mülakatla örneklenmiş mi?", "d": "EA-2/17 M:2026 Annex B Tablo 2", "k": "Kayıt incelemesi"}, {"no": "A.9", "sec": "A", "t": "İlk akreditasyonda tanık denetimi ertelendiyse 18 ay içinde tamamlandığı ve tanık öncesi akredite belge düzenlenmediği doğrulanmış.", "d": "EA-2/17 M:2026 Annex B (18 ay kuralı)", "k": "Kayıt incelemesi"}, {"no": "B.1", "sec": "B", "t": "Başvuru monte eden veya yetkili temsilcisi tarafından yapılıyor; yetkili temsilci başvurularında vekâletnamenin ilgili yükümlülükleri açıkça kapsadığı kontrol ediliyor.", "d": "Ek XI md. 3.1, 8 (yetkili temsilci maddesi)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.2", "sec": "B", "t": "Başvuruda aynı başvurunun başka bir onaylanmış kuruluşa yapılmadığına dair yazılı beyan bulunuyor.", "d": "Ek XI md. 3.1, 8 — tek OK beyanı", "k": "Dosya örneklemesi"}, {"no": "B.3", "sec": "B", "t": "Başvuru dosyası Direktifin istediği tüm unsurları içeriyor: (a) monte edenin/yetkili temsilcinin adı ve adresi, (b) kurulacak asansörlere ilişkin, özellikle tasarım ile işletme arasındaki ilişkiyi anlamaya yarayan bilgiler, (c) KS dokümantasyonu, (d) Ek IV-B md. 3'te tanımlanan teknik dosya, (e) tek OK beyanı.", "d": "Ek XI md. 3.1, 8", "k": "Dosya örneklemesi"}, {"no": "B.4", "sec": "B", "t": "Başvurunun gözden geçirilmesinde kapsam (NANDO), yetkinlik ve kaynak yeterliliği ile tarafsızlık riski değerlendiriliyor ve kayda alınıyor.", "d": "ISO/IEC 17065 md. 7.3 / ISO/IEC 17021-1 md. 9.1.2; Md. 24(6)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.5", "sec": "B", "t": "Müşteri sözleşmesinde OK'nın ve akreditasyon kuruluşunun (tanık denetimi için) tesislere, sahalara ve kayıtlara erişim hakkı açıkça yazılı.", "d": "ISO/IEC 17065 md. 4.1.2; iyi uygulama: AA L05 §1.3", "k": "Dosya örneklemesi"}, {"no": "B.6", "sec": "B", "t": "Alt yüklenici veya bağlı kuruluş kullanılacaksa müşterinin onayı alınmış.", "d": "2014/33/AB Md. 26(3)", "k": "Dosya örneklemesi"}, {"no": "B.7", "sec": "B", "t": "Orantılılık: değerlendirme planı işletmenin büyüklüğü, yapısı, teknolojinin karmaşıklığı ve üretimin seri/kütle niteliği dikkate alınarak hazırlanmış; ancak koruma düzeyinden taviz verilmemiş.", "d": "2014/33/AB Md. 24(6)(c), Md. 32(2)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C1.1", "sec": "C1", "t": "KS tasarım, imalat, montaj, kurulum, son muayene ve deneyi kapsıyor; dokümantasyon yazılı politika, prosedür ve talimatlarla sistematik.", "d": "Ek XI md. 2, 3.2", "k": "Dosya örneklemesi"}, {"no": "C1.2", "sec": "C1", "t": "(a) Tasarım ve ürün kalitesine ilişkin kalite hedefleri, organizasyon, sorumluluk ve yetkiler.", "d": "Ek XI md. 3.2(a)", "k": "Dosya örneklemesi"}, {"no": "C1.3", "sec": "C1", "t": "(b) Teknik tasarım spesifikasyonları ve uygulanacak standartlar; uyumlaştırılmış standartlar tam uygulanmıyorsa diğer teknik şartnameler.", "d": "Ek XI md. 3.2(b)", "k": "Dosya örneklemesi"}, {"no": "C1.4", "sec": "C1", "t": "(c) Tasarım kontrolü ve tasarım doğrulama teknikleri, süreçleri ve sistematik faaliyetleri.", "d": "Ek XI md. 3.2(c)", "k": "Dosya örneklemesi"}, {"no": "C1.5", "sec": "C1", "t": "(d) Malzeme, bileşen ve alt montajların kabulünde yapılacak muayene ve deneyler.", "d": "Ek XI md. 3.2(d)", "k": "Dosya örneklemesi"}, {"no": "C1.6", "sec": "C1", "t": "(e) Montaj, kurulum, kalite kontrol ve kalite güvence teknikleri, süreçleri ve sistematik faaliyetleri.", "d": "Ek XI md. 3.2(e)", "k": "Dosya örneklemesi"}, {"no": "C1.7", "sec": "C1", "t": "(f) Kurulumdan önce (kuyu, makine yeri vb. kurulum koşulları), kurulum sırasında ve sonrasında (asgari Ek V md. 3.3 deneyleri) yapılacak muayene ve deneyler.", "d": "Ek XI md. 3.2(f); Ek V md. 3.3", "k": "Dosya örneklemesi"}, {"no": "C1.8", "sec": "C1", "t": "(g) Kalite kayıtları (muayene raporları, deney verileri, kalibrasyon, personel nitelikleri).", "d": "Ek XI md. 3.2(g)", "k": "Dosya örneklemesi"}, {"no": "C1.9", "sec": "C1", "t": "(h) İstenen tasarım ve ürün kalitesine ulaşılmasının ve KS'nin etkin işleyişinin izlenmesi.", "d": "Ek XI md. 3.2(h)", "k": "Dosya örneklemesi"}, {"no": "C1.10", "sec": "C1", "t": "Denetim ekibi md. 3.1(d)'deki teknik dosyayı gözden geçirerek monte edenin TSGG'yi tanıma ve gerekli incelemeleri yapma yeteneğini doğrulamış.", "d": "Ek XI md. 3.4", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C1.11", "sec": "C1", "t": "Monte edenin tasarım yetkinliği değerlendirilmiş: risk analizi, kurulacak asansör konfigürasyonunu tanımlama, spesifikasyonların karşılandığını doğrulama ve uyumlaştırılmış standartlardan sapmaları tespit etme.", "d": "NB-L RfU 3/001 (95/16/AT Ek XIII — Md. 44 uyarınca geçerli)", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C1.12", "sec": "C1", "t": "Onay kapsamı tasarım yetkinliğine göre sınırlandırılmış (ör. bina planlaması + parça tasarımı + katalogdan seçim / parça tasarımı + katalog / yalnız katalogdan seçim).", "d": "NB-L RfU 3/004", "k": "Dosya örneklemesi"}, {"no": "C1.13", "sec": "C1", "t": "Son muayene alt yükleniciye verilmişse monte edenin ilgili prosedürü ve uygulaması OK tarafından kontrol edilmiş.", "d": "NB-L RfU 3/012", "k": "Dosya örneklemesi"}, {"no": "C1.14", "sec": "C1", "t": "Denetim ekibi kalite yönetim sistemleri deneyimine ek olarak, ilgili asansör teknolojisinde değerlendirme deneyimi ve Ek I TSGG bilgisi olan en az bir üye içeriyor.", "d": "Ek XI md. 3.4 (değerlendirme maddesi); Md. 24(7)", "k": "Kayıt incelemesi + Dosya örneklemesi"}, {"no": "C1.15", "sec": "C1", "t": "İlk değerlendirme monte edenin tesisine değerlendirme ziyaretini ve bir kurulum sahası ziyaretini içeriyor; ziyaret kayıtları (yer, tarih, görüşülen kişiler, örneklenen kayıtlar) dosyada.", "d": "Ek XI md. 3.4", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C1.16", "sec": "C1", "t": "Denetim programı ve denetim süresi belirlenmiş; ilgili IAF MD dokümanları (ör. çok sahalı örnekleme, denetim süresi) dikkate alınmış; NB-L kararı varsa öncelikli.", "d": "ISO/IEC 17021-1 md. 9.1.3, 9.1.4 (qa); EA-2/17 M:2026 Annex A Not 4–5", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C1.17", "sec": "C1", "t": "Uyumlaştırılmış standart karinesi yalnız atfı AB Resmî Gazetesi'nde yayımlanmış bir standarda dayandırılıyor; ISO 9001 belgesi tek başına kalite sistemi onayının yerine kullanılmıyor.", "d": "Ek XI md. 3.4 (karine cümlesi)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C1.18", "sec": "C1", "t": "Değerlendirme kararı başvurana bildiriliyor; bildirim denetim sonuçlarını ve gerekçeli değerlendirme kararını içeriyor.", "d": "Ek XI md. 3.4", "k": "Dosya örneklemesi"}, {"no": "C2.1", "sec": "C2", "t": "Tasarımın uyumlaştırılmış standartlara tam uymadığı durumlar tespit ediliyor; tasarım incelemesi gereken hâller (standarttan sapmalar ve standartta ele alınmayan ek hususlar) ve sapmadan etkilenen parçalar kapsama alınıyor.", "d": "Ek XI md. 3.3.1; NB-L RfU 3/006", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C2.2", "sec": "C2", "t": "Tasarım incelemesinde OK, tasarımın TSGG'ye uygunluğunu kendi analiziyle değerlendiriyor; gerektiğinde dokümanter incelemeye ek olarak sahada muayene/deney yapılıyor.", "d": "Ek XI md. 3.3.1; NB-L RfU 3/006", "k": "Dosya örneklemesi + Mülakat + Tanık denetimi"}, {"no": "C2.3", "sec": "C2", "t": "AB tasarım inceleme belgesi geçerlilik sınırlarını ve onaylı tasarımı tanımlayan bilgileri içeriyor; asgari içerik: OK adı/no, belge sahibi, belge no, kapsam (sapmanın tanımı, alternatif çözüm), onay koşulları, çevre koşulları, raporla ilişki, sahada yapılacak deney ve muayeneler, ek bilgi, yer/tarih/imza.", "d": "Ek XI md. 3.3.1; NB-L RfU 3/009", "k": "Dosya örneklemesi"}, {"no": "C2.4", "sec": "C2", "t": "Alternatif çözümün tanımı en az işlevin ayrıntılı açıklamasını, temel ayrıntıları ve diğer parçalarla bağlantıları gösteren çizimleri ve elektrik/hidrolik şemaları içeriyor.", "d": "NB-L RfU 3/009 Not 2", "k": "Dosya örneklemesi"}, {"no": "C2.5", "sec": "C2", "t": "Tasarım TSGG'yi karşılamıyorsa belge reddediliyor ve ayrıntılı gerekçe bildiriliyor.", "d": "Ek XI md. 3.3.2", "k": "Dosya örneklemesi"}, {"no": "C2.6", "sec": "C2", "t": "Onaylı tasarımdaki değişiklikler belgeyi veren OK'nın ek onayına (belgeye ilave) tabi tutuluyor.", "d": "Ek XI md. 3.3.3", "k": "Dosya örneklemesi"}, {"no": "C2.7", "sec": "C2", "t": "Verilen/geri çekilen AB tasarım inceleme belgeleri bildirim otoritesine ve diğer OK'lara bildiriliyor; talep hâlinde Komisyon/üye devletlere teknik dosya ve inceleme sonuçları veriliyor.", "d": "Ek XI md. 3.3.4", "k": "Kayıt incelemesi"}, {"no": "D.1", "sec": "D", "t": "KS denetçileri ve teknik uzmanlar için asansör tasarımı, kurulumu ve son muayeneye özgü yetkinlik kriterleri tanımlı; tasarım incelemesini yapan personelin ürün bilgisi (pk) kanıtlı.", "d": "ISO/IEC 17021-1 md. 7.1, 7.2 (qa); ISO/IEC 17020 md. 6.1.2–6.1.3 (pk)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "E.1", "sec": "E", "t": "Denetim raporu ve tasarım inceleme raporu yapılan inceleme, doğrulama ve deneyleri ve sonuçlarını kanıtlarla birlikte kaydediyor.", "d": "2014/33/AB Md. 24(7)(d)", "k": "Dosya örneklemesi"}, {"no": "E.2", "sec": "E", "t": "Gözden geçirme ve belgelendirme kararı, değerlendirmeyi yapmamış yetkin kişi(ler)ce veriliyor; karar kaydı tarihli ve imzalı.", "d": "ISO/IEC 17065 md. 7.5, 7.6 (cd) / ISO/IEC 17021-1 md. 9.5", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "E.3", "sec": "E", "t": "TSGG veya uyumlaştırılmış standartlar/diğer teknik şartnameler karşılanmadığında düzeltici faaliyet isteniyor ve belge düzenlenmiyor.", "d": "2014/33/AB Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "E.4", "sec": "E", "t": "Ret kararında ayrıntılı gerekçe başvurana yazılı bildiriliyor.", "d": "2014/33/AB ilgili ek; Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "E.5", "sec": "E", "t": "OK kararlarına karşı itiraz prosedürü mevcut, müşteriye duyuruluyor ve itirazlar kararı verenden bağımsız kişilerce ele alınıyor.", "d": "2014/33/AB Md. 33; ISO/IEC 17065 md. 7.13", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "F.1", "sec": "F", "t": "Kalite sistemi onay belgesi asgari şu bilgileri içeriyor: OK adı ve kimlik no; belge sahibinin adı/adresi; dayanak (2014/33/AB Ek …); belge no; onay kapsamı; değerlendirme raporuyla ilişki; ek bilgiler; yer, tarih, imza ve ad; geçerlilik süresi. Ek XI belgesinde 'ek bilgiler' bölümünde sistemin geçerlilik aralığında Md. 16(1) kapsamındaki diğer prosedürlerde de kullanılabileceği belirtiliyor.", "d": "NB-L RfU 3/005", "k": "Dosya örneklemesi"}, {"no": "F.2", "sec": "F", "t": "OK kimlik numarasının CE işaretinin yanına OK tarafından iliştirilmesi veya iliştirtilmesi ve monte edenin kabine CE + OK numarasını iliştirmesi kuralları tanımlı; numara kullanımı izleniyor.", "d": "Ek XI md. 3.5 (son paragraf), 7.1; Md. 19(3)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "G.1", "sec": "G", "t": "Kalite sistemindeki planlanan değişiklikler OK'ya bildiriliyor; OK değişikliği değerlendirip sistemin şartları karşılamaya devam edip etmediğine veya yeniden değerlendirme gerekip gerekmediğine karar veriyor; karar gerekçeli bildiriliyor.", "d": "Ek XI md. 3.5", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "G.2", "sec": "G", "t": "Gözetimde OK'ya tasarım, imalat, montaj, kurulum, muayene, deney ve depolama yerlerine; tasarım, tedarik kabulü ve kurulum bölümlerindeki kalite kayıtlarına erişim sağlanıyor; KS dokümantasyonu ve kalite kayıtları (muayene raporları, deney verileri, kalibrasyon, personel nitelikleri) örnekleniyor.", "d": "Ek XI md. 4.2", "k": "Dosya örneklemesi"}, {"no": "G.3", "sec": "G", "t": "Periyodik denetimler yapılıyor ve her denetim sonunda müşteriye denetim raporu veriliyor; gözetim sıklığı tanımlı (en az yıllık önerilir) ve uygulanıyor.", "d": "Ek XI md. 4.3; ISO/IEC 17021-1 md. 9.6 (qa)", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "G.4", "sec": "G", "t": "Habersiz ziyaret politikası tanımlı (monte edenin tesisleri veya bir asansörün kurulum sahası); ziyaretlerde gerektiğinde deney yapılıyor/yaptırılıyor; ziyaret raporu ve varsa deney raporu veriliyor.", "d": "Ek XI md. 4.4", "k": "Prosedür incelemesi + Dosya örneklemesi + Kayıt incelemesi"}, {"no": "G.5", "sec": "G", "t": "Onay kapsamı sınırlamaları yalnız ürünle ilişkili (ör. teknoloji, aksam türü, tahrik tipi) olarak tanımlanıyor.", "d": "NB-L RfU 3/004", "k": "Dosya örneklemesi"}, {"no": "G.6", "sec": "G", "t": "Gözetimde uygunsuzluk tespitinde düzeltici faaliyet isteniyor; etkisiz kalırsa onay kısıtlanıyor, askıya alınıyor veya geri çekiliyor.", "d": "2014/33/AB Md. 32(4), 32(5)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "G.7", "sec": "G", "t": "Onayın geçerlilik süresi ve yeniden belgelendirme döngüsü tanımlı ve belgede yazılı.", "d": "NB-L RfU 3/005 (md. 9 geçerlilik süresi); ISO/IEC 17021-1 md. 9.6.3", "k": "Dosya örneklemesi"}, {"no": "G.8", "sec": "G", "t": "KS el kitabında hangi değişikliklerin OK'ya bildirileceği ve hangilerinin OK onayı gerektirdiği konusunda mutabakat yazılı; denetimlerde bu mutabakatın kötüye kullanılmadığı kontrol ediliyor.", "d": "NB-L RfU 3/007 (95/16/AT Ek XIII — Md. 44 uyarınca geçerli)", "k": "Dosya örneklemesi"}, {"no": "H.1", "sec": "H", "t": "Kayıt saklama: onay kararı, ekleri ve ilaveleri ile teknik dosya düzenlenme tarihinden itibaren 15 yıl saklanıyor.", "d": "2014/33/AB ilgili ek; ISO/IEC 17065 md. 7.12 / 17021-1 md. 9.9 / 17020 md. 7.3, 8.4", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "H.2", "sec": "H", "t": "Bildirim otoritesine verilen/geri çekilen belgeler (onaylar) bildiriliyor; reddedilen, askıya alınan veya kısıtlanan belgelerin listesi periyodik olarak veya talep üzerine sunuluyor.", "d": "Ek XI md. 6; Md. 34(1)", "k": "Kayıt incelemesi"}, {"no": "H.3", "sec": "H", "t": "Diğer onaylanmış kuruluşlara reddedilen, askıya alınan, geri çekilen veya kısıtlanan belgeler bildiriliyor; talep hâlinde verilen belgeler hakkında bilgi veriliyor.", "d": "Ek XI md. 6; Md. 34(2)", "k": "Kayıt incelemesi"}, {"no": "H.4", "sec": "H", "t": "Komisyon ve üye devletlerin talebi hâlinde belge kopyası (ve ilgili eklerde öngörüldüğünde teknik dosya/rapor) verilebiliyor; prosedürde tanımlı.", "d": "Ek XI md. 6", "k": "Prosedür incelemesi"}, {"no": "H.5", "sec": "H", "t": "Ekonomik operatörün saklama yükümlülüğü (AB tasarım inceleme belgesi ve teknik dosya ile KS kayıtları 10 yıl — Ek XI md. 3.3.5, 5) belge/sözleşme ekinde veya bilgilendirme notunda müşteriye bildiriliyor.", "d": "2014/33/AB ilgili ek (iyi uygulama)", "k": "Dosya örneklemesi"}, {"no": "H.6", "sec": "H", "t": "Gizlilik: değerlendirme sırasında elde edilen bilgiler yalnız yetkili makamlarla paylaşılıyor; mülkiyet hakları korunuyor.", "d": "2014/33/AB Md. 24(10)", "k": "Prosedür incelemesi + Mülakat"}, {"no": "H.7", "sec": "H", "t": "OK, NB-L Koordinasyon Grubu çalışmalarına katılıyor veya personeli bilgilendiriliyor; tasdik edilmiş RfU'ların (Temmuz 2026 derlemesi) bu modüle ilişkin olanları prosedürlere işlenmiş.", "d": "2014/33/AB Md. 24(11), Md. 36; NB-L RfU 16.07.2026", "k": "Prosedür incelemesi + Kayıt incelemesi + Mülakat"}], "tanik": {"faaliyet": "Tasarım dâhil KS denetimi + kurulum sahası; tasarım incelemesi dosyası", "grup": "H1 veya (B* + H)", "not": "H1 tanığı B, D, E, H için gruplama seçeneğidir."}, "yon": "asansor"}, {"id": "M-VII", "code": "M1", "grup": "makine", "yon": "makine", "ad": "Makine Modül B (Ek VII)", "baslik": "EK VII — AB TİP İNCELEMESİ (MODÜL B)", "ozet": [["Ürün", "Ek I Bölüm A (6 kategori) ve Bölüm B (19 kategori) makine ve ilgili ürünler; Bölüm B'de kategoriye özgü standart/ortak spesifikasyon tam uygulanmamışsa üçüncü taraf zorunlu"], ["Direktif dayanağı", "(AB) 2023/1230 Md. 25(2)(a) ve 25(3)(b) — Modül C (Ek VIII) ile birlikte; OK görevi tasarım/tip aşamasında"], ["Başvuran / OK çıktısı", "İmalatçı veya yetkili temsilcisi / AB tip inceleme sertifikası (en fazla 5 yıl) ve ekleri"], ["Akreditasyon (EA-2/17 M:2026)", "EN ISO/IEC 17065 · cd + pk + t · kabul edilmeyen: 17021-1, 17024, 17025, 17029"], ["Tanık gruplaması", "Tablo 2: B ← B* veya G veya H1; tasarım için dosya incelemesi + teknik mülakat tercih edilir"], ["Saklama süreleri", "OK: sertifika, ekler ve teknik dosya sertifika geçerliliğinin bitiminden sonra 5 yıl (md. 8) · İmalatçı: 10 yıl (md. 9)"]], "items": [{"no": "A.1", "sec": "A", "t": "Kuruluş bu modül (Ek VII — Modül B) için EN ISO/IEC 17065 esas alınarak akredite edilmiş/denetleniyor mu? Farklı bir standart kullanılıyorsa bildirim otoritesinin yayımlanmış bağlayıcı gerekliliğine dayanan gerekçe AK tarafından kayda alınmış mı?", "d": "EA-2/17 M:2026 §4.2, Annex A Tablo 1 (Modül B)", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "A.2", "sec": "A", "t": "Bu modül için kabul edilmeyen standartlar (ISO/IEC 17021-1, 17024, 17025, 17029) akreditasyon dayanağı olarak kullanılmıyor.", "d": "EA-2/17 M:2026 Annex A Tablo 1", "k": "Kayıt incelemesi"}, {"no": "A.3", "sec": "A", "t": "'cd' gerekliliği: EN ISO/IEC 17065 md. 4.1.2, 4.1.3, 7.5 ve 7.6'nın (belgelendirme anlaşması, belge/işaret kullanımı, gözden geçirme ve karar) bu modül için ayrıca kanıtlandığı doğrulanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (cd)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "A.4", "sec": "A", "t": "'pk' gerekliliği: ürün bilgisine dayalı mesleki yargı — EN ISO/IEC 17020 md. 6.1.2, 6.1.3 ve 6.1.6–6.1.10 (yetkinlik kriterleri, görevlendirme, eğitim, gözetim, saha izleme, kayıtlar) bu modülün personeli için Ek I kategorileri bazında kanıtlanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (pk)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "A.5", "sec": "A", "t": "'t' gerekliliği: OK deneyleri kendisi yapıyorsa EN ISO/IEC 17025 md. 6 ve 7 (7.9 hariç) karşılanmalı; deneyler dış laboratuvarda yapılıyorsa Md. 32 kapsamında alt yüklenici değerlendirmesi aranmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (t); (AB) 2023/1230 Md. 32", "k": "Prosedür incelemesi + Kayıt incelemesi + Tanık denetimi"}, {"no": "A.6", "sec": "A", "t": "Kapsam ifadesi: mevzuat ((AB) 2023/1230), ek ve modül (Ek VII — Modül B) ile ürün kapsamı (Ek I Bölüm A / Bölüm B kategori numaraları) NANDO sınıflandırmasıyla uyumlu şekilde açıkça yazılmış.", "d": "EA-2/17 M:2026 §5; EA-2/17 S2:2026; ISO/IEC 17011 md. 7.8", "k": "Kayıt incelemesi"}, {"no": "A.7", "sec": "A", "t": "Akreditasyon kapsamı ile bildirim (NANDO) kapsamı tutarlı; bildirim dışı bir modül veya Ek I kategorisi için sertifika düzenlenmemiş.", "d": "(AB) 2023/1230 Md. 34(3), Md. 38(1)", "k": "Kayıt incelemesi + Dosya örneklemesi"}, {"no": "A.8", "sec": "A", "t": "Tanık planı: kapsamdaki Ek I kategori grupları (ahşap işleme makineleri, presler, plastik/kauçuk enjeksiyon, yeraltı makineleri, kişi kaldırma, koruyucu tertibat / lojik ünite, ROPS/FOPS, makine öğrenimli güvenlik bileşenleri) için akreditasyon döngüsünde tip incelemesi dosya incelemesi + teknik mülakatla, sahadaki tip deneyleri tanıkla değerlendirilecek şekilde planlanmış mı?", "d": "EA-2/17 M:2026 Annex B Tablo 2", "k": "Kayıt incelemesi"}, {"no": "A.9", "sec": "A", "t": "İlk akreditasyonda tanık denetimi ertelendiyse 18 ay içinde tamamlandığı ve tanık öncesi akredite sertifika düzenlenmediği doğrulanmış.", "d": "EA-2/17 M:2026 Annex B (18 ay kuralı)", "k": "Kayıt incelemesi"}, {"no": "A.10", "sec": "A", "t": "Uyumlaştırılmış standart veya ortak spesifikasyon bulunmayan ya da imalatçının uygulamadığı durumlar için (özellikle Ek I Bölüm A 5–6: makine öğrenimiyle kendi kendini geliştiren güvenlik işlevleri) OK'nin politika ve prosedürleri gerekçeli analize dayanıyor ve AK tarafından değerlendirilmiş.", "d": "EA-2/17 M:2026 §6; (AB) 2023/1230 Md. 20", "k": "Prosedür incelemesi + Mülakat"}, {"no": "B.1", "sec": "B", "t": "Başvuru imalatçı veya yetkili temsilcisi tarafından yapılıyor; yetkili temsilci başvurularında yetki belgesinin (mandate) Ek VII/3, 7.2, 7.4 ve 9 yükümlülüklerini açıkça kapsadığı kontrol ediliyor.", "d": "Ek VII md. 3, 10", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.2", "sec": "B", "t": "Başvuruda aynı başvurunun başka bir onaylanmış kuruluşa yapılmadığına dair yazılı beyan bulunuyor.", "d": "Ek VII md. 3(b)", "k": "Dosya örneklemesi"}, {"no": "B.3", "sec": "B", "t": "Başvuru dosyası tüm unsurları içeriyor: (a) imalatçının ve varsa yetkili temsilcinin adı/adresi, (b) tek OK beyanı, (c) Ek IV Bölüm A teknik dosyası, (d) üretimi temsil eden numune(ler)e erişim.", "d": "Ek VII md. 3(a)–(d)", "k": "Dosya örneklemesi"}, {"no": "B.4", "sec": "B", "t": "Başvurunun gözden geçirilmesinde ürünün Ek I Bölüm A / Bölüm B kategorisi ve seçilen prosedürün Md. 25'e uygunluğu (Bölüm A'da Modül A seçilemez; B mutlaka C ile tamamlanır), bildirim kapsamı, yetkinlik ve kaynak yeterliliği ile tarafsızlık riski değerlendiriliyor ve kayda alınıyor.", "d": "(AB) 2023/1230 Md. 25, Md. 30(6); ISO/IEC 17065 md. 7.3", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.5", "sec": "B", "t": "Müşteri sözleşmesinde OK'nin ve akreditasyon kuruluşunun (tanık denetimi için) tesislere, deney yerlerine ve kayıtlara erişim hakkı açıkça yazılı.", "d": "ISO/IEC 17065 md. 4.1.2", "k": "Dosya örneklemesi"}, {"no": "B.6", "sec": "B", "t": "Alt yüklenici veya bağlı kuruluş kullanılacaksa müşterinin onayı alınmış.", "d": "(AB) 2023/1230 Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "B.7", "sec": "B", "t": "Orantılılık: değerlendirme planı işletmenin büyüklüğü, sektörü, yapısı, teknolojinin karmaşıklığı ve üretimin seri/kütle niteliği dikkate alınarak hazırlanmış; koruma düzeyinden taviz verilmemiş. Ücretlendirmede KOBİ'lerin özel ihtiyaçları dikkate alınıyor.", "d": "(AB) 2023/1230 Md. 38(2), Md. 30(6)(d), Md. 25(5)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.8", "sec": "B", "t": "Numune: OK deney programı için ek numune talep edebiliyor; kişiye uyarlanan seri ürünlerde kullanıcı aralığını temsil eden numuneler, tek kullanıcıya özel tek üründe temel model isteniyor; numunelerin kimliklendirilmesi ve muhafazası kayıt altında.", "d": "Ek VII md. 3(d); ISO/IEC 17065 md. 7.4", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C.1", "sec": "C", "t": "Teknik dosya, tasarımın yeterliliği açısından incelenmiş; Ek IV-A (h) ve (l) bentlerinin dikkate alınmadığı durumlar prosedürle tutarlı.", "d": "Ek VII md. 4(a)", "k": "Dosya örneklemesi"}, {"no": "C.2", "sec": "C", "t": "Ek IV-A (a)–(o) bütünlüğü kontrol ediliyor: tanım ve amaçlanan kullanım, risk değerlendirmesi (uygulanabilir TSGİ listesi, her TSGİ için koruyucu önlem, artık riskler), çizim ve şemalar, standart/ortak spesifikasyon atıfları, hesap ve deney raporları, kullanım talimatı ve Ek III 1.7.4 bilgileri.", "d": "Ek IV Bölüm A; Ek VII md. 3(c)", "k": "Dosya örneklemesi"}, {"no": "C.3", "sec": "C", "t": "OK, uygulanabilir TSGİ'leri imalatçıdan bağımsız olarak doğruluyor; 2023/1230 ile gelen yeni/genişleyen gereklilikler (Ek III 1.1.9 bozulmaya karşı koruma, 1.2.1 kumanda sistemlerinin güvenliği ve güvenilirliği, kendi kendini geliştiren davranış, otonom mobil makineler) değerlendirmede dikkate alınmış.", "d": "Ek VII md. 1, 4(a); Ek III", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C.4", "sec": "C", "t": "Kişiye uyarlanan seri ürünlerde uyarlama önlemlerinin tanımı yeterlilik açısından incelenmiş.", "d": "Ek VII md. 4(b)", "k": "Dosya örneklemesi"}, {"no": "C.5", "sec": "C", "t": "Numunenin teknik dosyaya uygun imal edildiği doğrulanmış; uyumlaştırılmış standart / ortak spesifikasyona göre tasarlanan unsurlar ile diğer teknik spesifikasyonlara göre tasarlananlar ayrı ayrı tanımlanmış.", "d": "Ek VII md. 4(c)", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C.6", "sec": "C", "t": "İmalatçı uyumlaştırılmış standart / ortak spesifikasyon çözümlerini seçtiğinde bunların doğru uygulandığı uygun inceleme ve deneylerle (ilgili C tipi standardın deney yöntemleri) kontrol edilmiş.", "d": "Ek VII md. 4(d)", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C.7", "sec": "C", "t": "Standart çözümleri uygulanmadığında imalatçının çözümlerinin (diğer teknik spesifikasyonlar dahil) ilgili TSGİ'leri karşıladığı ve doğru uygulandığı OK'nin kendi analizi ve uygun deneylerle gerekçelendirilmiş.", "d": "Ek VII md. 4(e); EA-2/17 M:2026 §6", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C.8", "sec": "C", "t": "Güvenlik işlevi sağlayan yazılım ve makine öğrenimi içeren ürünlerde (Ek I Bölüm A 5–6) sistemin özellikleri, sınırları, veri, geliştirme, deney ve doğrulama süreçleri incelenmiş; fonksiyonel güvenlik değerlendirmesi (ör. EN ISO 13849-1, EN IEC 62061) yetkin personelce yapılmış.", "d": "Ek IV-A (n); Ek III 1.2.1", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C.9", "sec": "C", "t": "Dahil edilen kısmen tamamlanmış makinenin AB ilave beyanı ve montaj talimatı ile diğer mevzuat kapsamındaki bileşenlerin AB uygunluk beyanları dosyada değerlendirilmiş.", "d": "Ek IV-A (j), (k)", "k": "Dosya örneklemesi"}, {"no": "C.10", "sec": "C", "t": "Muayene ve deneylerin yapılacağı yer ve program başvuranla kararlaştırılmış ve kayda alınmış.", "d": "Ek VII md. 4; ISO/IEC 17065 md. 7.4", "k": "Dosya örneklemesi"}, {"no": "C.11", "sec": "C", "t": "Deney ekipmanı kalibreli ve izlenebilir; ölçüm belirsizliği karar kuralında dikkate alınmış.", "d": "EA-2/17 Annex A (t): ISO/IEC 17025 md. 6.4, 6.5, 7.6", "k": "Kayıt incelemesi + Tanık denetimi"}, {"no": "C.12", "sec": "C", "t": "Deneyler dış laboratuvarda yapılıyorsa laboratuvarın Md. 30 şartlarını karşıladığı değerlendirilmiş, bildirim otoritesine bilgi verilmiş, sorumluluk OK'de kalmış.", "d": "(AB) 2023/1230 Md. 32(1), 32(2), 32(4); ISO/IEC 17065 md. 6.2.2", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "D.1", "sec": "D", "t": "Değerlendirme personeli her Ek I kategorisi için tanımlı yetkinlik kriterlerine göre yetkilendirilmiş (Ek III TSGİ, ilgili A/B/C tipi uyumlaştırılmış standartlar, ortak spesifikasyonlar).", "d": "Md. 30(7)(a)–(c); ISO/IEC 17020 md. 6.1.2–6.1.3 (pk)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "D.2", "sec": "D", "t": "Deney yapan personelin deney yöntemlerine ilişkin yetkinliği ve izlenmesi kayıtlı.", "d": "ISO/IEC 17025 md. 6.2 (t)", "k": "Kayıt incelemesi + Tanık denetimi"}, {"no": "D.3", "sec": "D", "t": "Güvenlikle ilgili kumanda sistemleri, yazılım ve siber bozulmaya karşı koruma konularında yetkin personel (iç veya alt yüklenici) mevcut.", "d": "Md. 30(6)(a), 30(7)(c); Ek III 1.1.9, 1.2.1", "k": "Kayıt incelemesi + Mülakat"}, {"no": "E.1", "sec": "E", "t": "Değerlendirme raporu Ek VII md. 4 kapsamında yapılan faaliyetleri ve sonuçlarını kanıtlarıyla birlikte kaydediyor.", "d": "Ek VII md. 5; Md. 30(7)(d)", "k": "Dosya örneklemesi"}, {"no": "E.2", "sec": "E", "t": "Raporun içeriği yalnız imalatçının onayıyla (bildirim otoritesine karşı yükümlülükler saklı) açıklanıyor.", "d": "Ek VII md. 5", "k": "Prosedür incelemesi"}, {"no": "E.3", "sec": "E", "t": "Gözden geçirme ve belgelendirme kararı, değerlendirmeyi yapmamış yetkin kişi(ler)ce veriliyor; karar kaydı tarihli ve imzalı.", "d": "ISO/IEC 17065 md. 7.5, 7.6 (cd)", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "E.4", "sec": "E", "t": "TSGİ veya uyumlaştırılmış standart / ortak spesifikasyon karşılanmadığında düzeltici faaliyet isteniyor ve sertifika düzenlenmiyor.", "d": "(AB) 2023/1230 Md. 38(3)", "k": "Dosya örneklemesi"}, {"no": "E.5", "sec": "E", "t": "Ret kararında ayrıntılı gerekçe başvurana yazılı bildiriliyor.", "d": "Ek VII md. 6.4", "k": "Dosya örneklemesi"}, {"no": "E.6", "sec": "E", "t": "OK kararlarına karşı şeffaf ve erişilebilir itiraz prosedürü mevcut; itirazlar kararı verenden bağımsız kişilerce ele alınıyor.", "d": "(AB) 2023/1230 Md. 39; ISO/IEC 17065 md. 7.13", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "F.1", "sec": "F", "t": "Sertifika asgari içeriği taşıyor: OK adı ve kimlik numarası; imalatçı / Yİ adı ve adresi; ürün tanımı (tip numarası); TSGİ'lere uygunluk ifadesi; uygulanan standart/ortak spesifikasyon ve diğer teknik spesifikasyon atıfları; düzenleme, son geçerlilik ve yenileme tarihleri; varsa koşullar.", "d": "Ek VII md. 6.2(a)–(h)", "k": "Dosya örneklemesi"}, {"no": "F.2", "sec": "F", "t": "Sertifika geçerliliği (ilk veya yenilenmiş) 5 yılı aşmıyor.", "d": "Ek VII md. 6.1", "k": "Dosya örneklemesi"}, {"no": "F.3", "sec": "F", "t": "Sertifika ve ekleri, onaylı tipin tanımlanmasına ve üretilen ürünlerin tipe uygunluğunun değerlendirilmesine yetecek bilgileri içeriyor.", "d": "Ek VII md. 6.2, 6.3", "k": "Dosya örneklemesi"}, {"no": "F.4", "sec": "F", "t": "Müşteriye, tip incelemesinin Modül C (Ek VIII) ile tamamlanması gerektiği ve CE işaretinin yanında Modül B'yi yapan OK'nin kimlik numarasının bulunacağı bildiriliyor (iyi uygulama).", "d": "Md. 24(3), Md. 25(2)(a), 25(3)(b); Ek V-A md. 8", "k": "Dosya örneklemesi"}, {"no": "G.1", "sec": "G", "t": "OK genel kabul görmüş teknolojinin gelişimini (state of the art) izliyor; onaylı tipin artık uygun olmayabileceği durumlarda ek inceleme gerekip gerekmediğine karar verip imalatçıyı bilgilendiriyor.", "d": "Ek VII md. 7.1", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "G.2", "sec": "G", "t": "İmalatçının tip ve teknik dosya değişikliği bildirimleri inceleniyor; uygunluğu veya geçerlilik koşullarını etkileyenler sertifikaya ek (addition) ile onaylanıyor.", "d": "Ek VII md. 7.2", "k": "Dosya örneklemesi"}, {"no": "G.3", "sec": "G", "t": "Gözden geçirme talepleri (tip değişikliği, state of the art değişikliği, en geç bitişten önce) ele alınıyor; yenileme başvurusu bitişten en erken 12, en geç 6 ay önce ise yenileme, aksi hâlde yalnız ek düzenleniyor ve orijinal bitiş tarihi korunuyor.", "d": "Ek VII md. 7.4", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "G.4", "sec": "G", "t": "Gözden geçirmede gerekli inceleme/deneyler yapılıyor ve süreç sertifika bitiş tarihinden önce tamamlanıyor.", "d": "Ek VII md. 7.5", "k": "Dosya örneklemesi"}, {"no": "G.5", "sec": "G", "t": "Basitleştirilmiş gözden geçirme: imalatçı teyitleri ve güncel çizim/fotoğraf/işaretleme bilgileri alınıyor; değişiklik yoksa deney yapılmadan yenileniyor ve ücret idari yükle orantılı; state of the art değişikliği bulunursa tam gözden geçirmeye geçiliyor.", "d": "Ek VII md. 7.6", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "G.6", "sec": "G", "t": "Geçerliliğini yitiren sertifika geri çekiliyor ve imalatçıya piyasaya arzı durdurması bildiriliyor; askı/kısıtlama kriterleri tanımlı.", "d": "Ek VII md. 7.7; ISO/IEC 17065 md. 7.11", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "H.1", "sec": "H", "t": "Kayıt saklama: sertifika, ekleri ve eklemeleri ile imalatçının sunduğu belgeler dahil teknik dosya, sertifika geçerliliğinin bitiminden sonra 5 yıl saklanıyor.", "d": "Ek VII md. 8 son paragraf; ISO/IEC 17065 md. 7.12", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "H.2", "sec": "H", "t": "Bildirim otoritesine düzenlenen/geri çekilen sertifikalar ve ekler bildiriliyor; reddedilen, askıya alınan veya kısıtlananların listesi periyodik olarak veya talep üzerine sunuluyor.", "d": "Ek VII md. 8; Md. 40(1)(a)", "k": "Kayıt incelemesi"}, {"no": "H.3", "sec": "H", "t": "Diğer onaylanmış kuruluşlara reddedilen, geri çekilen, askıya alınan veya kısıtlanan sertifikalar bildiriliyor; talep hâlinde düzenlenenler hakkında bilgi veriliyor.", "d": "Ek VII md. 8; Md. 40(2)", "k": "Kayıt incelemesi"}, {"no": "H.4", "sec": "H", "t": "Komisyon ve üye devletlerin talebi hâlinde sertifika kopyası, teknik dosya ve inceleme sonuçları verilebiliyor; prosedürde tanımlı.", "d": "Ek VII md. 8", "k": "Prosedür incelemesi"}, {"no": "H.5", "sec": "H", "t": "İmalatçının sertifika ve teknik dosyayı piyasaya arzdan sonra en az 10 yıl saklama yükümlülüğü müşteriye bildiriliyor (iyi uygulama).", "d": "Ek VII md. 9", "k": "Dosya örneklemesi"}, {"no": "H.6", "sec": "H", "t": "Gizlilik: değerlendirme sırasında elde edilen bilgiler yalnız yetkili makamlarla paylaşılıyor; mülkiyet hakları, fikri mülkiyet ve ticari sırlar korunuyor.", "d": "(AB) 2023/1230 Md. 30(10)", "k": "Prosedür incelemesi + Mülakat"}, {"no": "H.7", "sec": "H", "t": "OK, makine onaylanmış kuruluşlar koordinasyon grubuna (NB-M) katılıyor veya personeli bilgilendiriliyor; grubun bu modüle ilişkin idari kararları ve dokümanları prosedürlere işlenmiş.", "d": "(AB) 2023/1230 Md. 30(11), Md. 42", "k": "Prosedür incelemesi + Kayıt incelemesi + Mülakat"}], "tanik": {"faaliyet": "Tip incelemesi dosyası + numune üzerinde tip deneyi (laboratuvar/imalatçı tesisi) — Ek I kategori grubu bazında", "grup": "B* veya G veya H1", "not": "Ek I kategorileri (ahşap işleme, pres, kaldırma, koruyucu tertibat, ML'li güvenlik bileşeni vb.) önemli ölçüde farklı; kategori grupları için ek dosya incelemesi/teknik mülakat gerekebilir."}}, {"id": "M-X", "code": "M2", "grup": "makine", "yon": "makine", "ad": "Makine Modül G (Ek X)", "baslik": "EK X — BİRİM DOĞRULAMAYA DAYALI UYGUNLUK (MODÜL G)", "ozet": [["Ürün", "Ek I Bölüm A ve B makine ve ilgili ürünler — her birim ayrı doğrulanır (tekil veya az adetli üretim)"], ["Direktif dayanağı", "(AB) 2023/1230 Md. 25(2)(c) ve 25(3)(d)"], ["Başvuran / OK çıktısı", "İmalatçı veya yetkili temsilcisi / birim doğrulama sertifikası; OK kimlik numarası ürün üzerinde CE yanında"], ["Akreditasyon (EA-2/17 M:2026)", "EN ISO/IEC 17065 · cd + pk + t · kabul edilmeyen: 17021-1, 17024, 17025, 17029"], ["Tanık gruplaması", "Tablo 2: G ← G veya (B* + F1) veya (B* + F)"], ["Saklama süreleri", "OK: Ek X süre öngörmez — ISO/IEC 17065 md. 7.12 uyarınca prosedürde · İmalatçı: teknik dosya ve sertifikalar 10 yıl (md. 2.1, 4)"]], "items": [{"no": "A.1", "sec": "A", "t": "Kuruluş bu modül (Ek X — Modül G) için EN ISO/IEC 17065 esas alınarak akredite edilmiş/denetleniyor mu? Farklı bir standart kullanılıyorsa bildirim otoritesinin yayımlanmış bağlayıcı gerekliliğine dayanan gerekçe AK tarafından kayda alınmış mı?", "d": "EA-2/17 M:2026 §4.2, Annex A Tablo 1 (Modül G)", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "A.2", "sec": "A", "t": "Bu modül için kabul edilmeyen standartlar (ISO/IEC 17021-1, 17024, 17025, 17029) akreditasyon dayanağı olarak kullanılmıyor.", "d": "EA-2/17 M:2026 Annex A Tablo 1", "k": "Kayıt incelemesi"}, {"no": "A.3", "sec": "A", "t": "'cd' gerekliliği: EN ISO/IEC 17065 md. 4.1.2, 4.1.3, 7.5 ve 7.6'nın (belgelendirme anlaşması, belge/işaret kullanımı, gözden geçirme ve karar) bu modül için ayrıca kanıtlandığı doğrulanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (cd)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "A.4", "sec": "A", "t": "'pk' gerekliliği: ürün bilgisine dayalı mesleki yargı — EN ISO/IEC 17020 md. 6.1.2, 6.1.3 ve 6.1.6–6.1.10 (yetkinlik kriterleri, görevlendirme, eğitim, gözetim, saha izleme, kayıtlar) bu modülün personeli için Ek I kategorileri bazında kanıtlanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (pk)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "A.5", "sec": "A", "t": "'t' gerekliliği: OK deneyleri kendisi yapıyorsa EN ISO/IEC 17025 md. 6 ve 7 (7.9 hariç) karşılanmalı; deneyler dış laboratuvarda yapılıyorsa Md. 32 kapsamında alt yüklenici değerlendirmesi aranmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (t); (AB) 2023/1230 Md. 32", "k": "Prosedür incelemesi + Kayıt incelemesi + Tanık denetimi"}, {"no": "A.6", "sec": "A", "t": "Kapsam ifadesi: mevzuat ((AB) 2023/1230), ek ve modül (Ek X — Modül G) ile ürün kapsamı (Ek I Bölüm A / Bölüm B kategori numaraları) NANDO sınıflandırmasıyla uyumlu şekilde açıkça yazılmış.", "d": "EA-2/17 M:2026 §5; EA-2/17 S2:2026; ISO/IEC 17011 md. 7.8", "k": "Kayıt incelemesi"}, {"no": "A.7", "sec": "A", "t": "Akreditasyon kapsamı ile bildirim (NANDO) kapsamı tutarlı; bildirim dışı bir modül veya Ek I kategorisi için sertifika düzenlenmemiş.", "d": "(AB) 2023/1230 Md. 34(3), Md. 38(1)", "k": "Kayıt incelemesi + Dosya örneklemesi"}, {"no": "A.8", "sec": "A", "t": "Tanık planı: birim doğrulamanın imalatçı tesisinde veya kurulum yerinde yapılan inceleme ve deneyleri, kapsamdaki Ek I kategori grupları dikkate alınarak akreditasyon döngüsünde tanıkla değerlendirilecek şekilde planlanmış mı?", "d": "EA-2/17 M:2026 Annex B Tablo 2", "k": "Kayıt incelemesi"}, {"no": "A.9", "sec": "A", "t": "İlk akreditasyonda tanık denetimi ertelendiyse 18 ay içinde tamamlandığı ve tanık öncesi akredite sertifika düzenlenmediği doğrulanmış.", "d": "EA-2/17 M:2026 Annex B (18 ay kuralı)", "k": "Kayıt incelemesi"}, {"no": "A.10", "sec": "A", "t": "Uyumlaştırılmış standart veya ortak spesifikasyon bulunmayan ya da imalatçının uygulamadığı durumlar için (özellikle Ek I Bölüm A 5–6: makine öğrenimiyle kendi kendini geliştiren güvenlik işlevleri) OK'nin politika ve prosedürleri gerekçeli analize dayanıyor ve AK tarafından değerlendirilmiş.", "d": "EA-2/17 M:2026 §6; (AB) 2023/1230 Md. 20", "k": "Prosedür incelemesi + Mülakat"}, {"no": "B.1", "sec": "B", "t": "Başvuru imalatçı veya yetkili temsilcisi tarafından yapılıyor; yetkili temsilci için yetki belgesi Ek X md. 2.1 ve 5 yükümlülüklerini kapsıyor.", "d": "Ek X md. 2(a), 6", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.2", "sec": "B", "t": "Aynı başvurunun başka bir onaylanmış kuruluşa yapılmadığına dair yazılı beyan alınmış.", "d": "Ek X md. 2(b)(iii)", "k": "Dosya örneklemesi"}, {"no": "B.3", "sec": "B", "t": "Başvuru/teknik dosya imalatı planlanan birimi tanımlıyor; asgari olarak Ek IV-A (a)–(g) bentlerini ve uygulanabildiği ölçüde kalite sistemi dokümantasyonunu içeriyor.", "d": "Ek X md. 2(b)(i)–(ii)", "k": "Dosya örneklemesi"}, {"no": "B.4", "sec": "B", "t": "Başvurunun gözden geçirilmesinde ürünün Ek I kategorisi ve Md. 25'e göre Modül G'nin seçilebilirliği, bildirim kapsamı, yetkinlik, kaynak ve tarafsızlık riski değerlendiriliyor.", "d": "(AB) 2023/1230 Md. 25, Md. 30(6); ISO/IEC 17065 md. 7.3", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.5", "sec": "B", "t": "Sözleşmede OK'nin ve akreditasyon kuruluşunun imalat ve (gerekiyorsa) kurulum yerine, ürüne ve kayıtlara erişim hakkı yazılı.", "d": "ISO/IEC 17065 md. 4.1.2", "k": "Dosya örneklemesi"}, {"no": "B.6", "sec": "B", "t": "Alt yüklenici veya bağlı kuruluş kullanılacaksa müşterinin onayı alınmış.", "d": "(AB) 2023/1230 Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "B.7", "sec": "B", "t": "Orantılılık ve KOBİ'lere yönelik ücretlendirme dikkate alınmış; koruma düzeyinden taviz verilmemiş.", "d": "(AB) 2023/1230 Md. 38(2), Md. 25(5)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C.1", "sec": "C", "t": "Teknik dosya, ürünün ilgili TSGİ'lere uygunluğunun değerlendirilmesine imkân veriyor ve yeterli risk analizi ve değerlendirmesi içeriyor; OK bu yeterliliği incelemiş.", "d": "Ek X md. 2", "k": "Dosya örneklemesi"}, {"no": "C.2", "sec": "C", "t": "Uygulanabilir TSGİ'ler belirtilmiş; tasarım, imalat ve işletme değerlendirme için gerektiği ölçüde kapsanmış; OK TSGİ listesini bağımsız olarak doğrulamış (Ek III 1.1.9, 1.2.1 dahil).", "d": "Ek X md. 2; Ek III", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C.3", "sec": "C", "t": "OK, ilgili uyumlaştırılmış standart ve/veya ortak spesifikasyonda öngörülen inceleme ve deneyleri veya eşdeğerlerini yapmış ya da yaptırmış; eşdeğerlik gerekçesi kayıtlı.", "d": "Ek X md. 4 1. paragraf", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C.4", "sec": "C", "t": "Uyumlaştırılmış standart / ortak spesifikasyon bulunmadığında uygun deneyler OK tarafından belirlenmiş ve gerekçelendirilmiş.", "d": "Ek X md. 4; EA-2/17 M:2026 §6", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C.5", "sec": "C", "t": "Doğrulama, sertifikanın kapsadığı fiilî birim üzerinde yapılmış; birimin kimliği (seri no, yer) teknik dosya ve deney kayıtlarıyla eşleştirilmiş.", "d": "Ek X md. 1, 4", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C.6", "sec": "C", "t": "Yalnız kullanım yerinde monte edilebilen makinelerde (ör. kalıcı kurulan kaldırma makineleri) doğrulamanın kurulum yerinde yapıldığı ve yerin kayda alındığı görülmüş.", "d": "Ek X md. 4; Ek V-A md. 3", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C.7", "sec": "C", "t": "Güvenlik işlevi sağlayan yazılım ve makine öğrenimi içeren ürünlerde sistem özellikleri, sınırları, veri, deney ve doğrulama süreçleri değerlendirilmiş.", "d": "Ek IV-A (n); Ek III 1.2.1", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C.8", "sec": "C", "t": "Deney ekipmanı kalibreli ve izlenebilir; ölçüm belirsizliği karar kuralında dikkate alınmış.", "d": "EA-2/17 Annex A (t): ISO/IEC 17025 md. 6.4, 6.5, 7.6", "k": "Kayıt incelemesi + Tanık denetimi"}, {"no": "C.9", "sec": "C", "t": "Deneyler dış laboratuvarda veya alt yükleniciyle yapılıyorsa Md. 30 şartları sağlanmış, bildirim otoritesine bilgi verilmiş, sorumluluk OK'de.", "d": "(AB) 2023/1230 Md. 32", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "D.1", "sec": "D", "t": "Değerlendirme personeli her Ek I kategorisi için tanımlı yetkinlik kriterlerine göre yetkilendirilmiş; sahada çalışan personelin gözetimi ve saha izlemesi kayıtlı.", "d": "Md. 30(7); ISO/IEC 17020 md. 6.1.2–6.1.3, 6.1.8–6.1.9 (pk)", "k": "Kayıt incelemesi + Mülakat + Tanık denetimi"}, {"no": "D.2", "sec": "D", "t": "Deney yapan personelin yetkinliği ve izlenmesi kayıtlı.", "d": "ISO/IEC 17025 md. 6.2 (t)", "k": "Kayıt incelemesi + Tanık denetimi"}, {"no": "D.3", "sec": "D", "t": "Güvenlikle ilgili kumanda sistemleri ve yazılım konusunda yetkin personel mevcut.", "d": "Md. 30(6)(a), 30(7)(c)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "E.1", "sec": "E", "t": "Doğrulama raporu yapılan inceleme ve deneyleri, sonuçlarını ve kanıtları kaydediyor.", "d": "Ek X md. 4; Md. 30(7)(d)", "k": "Dosya örneklemesi"}, {"no": "E.2", "sec": "E", "t": "Gözden geçirme ve karar, değerlendirmeyi yapmamış yetkin kişi(ler)ce veriliyor; karar kaydı tarihli ve imzalı.", "d": "ISO/IEC 17065 md. 7.5, 7.6 (cd)", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "E.3", "sec": "E", "t": "TSGİ veya standart / ortak spesifikasyon karşılanmadığında düzeltici faaliyet isteniyor ve birim doğrulama sertifikası düzenlenmiyor.", "d": "(AB) 2023/1230 Md. 38(3)", "k": "Dosya örneklemesi"}, {"no": "E.4", "sec": "E", "t": "OK kararlarına karşı şeffaf ve erişilebilir itiraz prosedürü mevcut.", "d": "(AB) 2023/1230 Md. 39; ISO/IEC 17065 md. 7.13", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "F.1", "sec": "F", "t": "Yapılan inceleme ve deneyleri kapsayan birim doğrulama sertifikası düzenlenmiş; sertifika birimi açıkça tanımlıyor ve uygulanan standart/ortak spesifikasyon veya deney yöntemlerine atıf içeriyor.", "d": "Ek X md. 4 2. paragraf", "k": "Dosya örneklemesi"}, {"no": "F.2", "sec": "F", "t": "OK kimlik numarası onaylanan ürüne OK tarafından veya OK'nin sorumluluğunda konmuş; uygulama kaydı (fotoğraf, talimat) mevcut.", "d": "Ek X md. 4, 5.1; Md. 24(3)", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "F.3", "sec": "F", "t": "Müşteriye CE işareti, OK numarası ve AB uygunluk beyanında OK adı/numarası ile Modül G atfına ilişkin bilgi veriliyor (iyi uygulama).", "d": "Ek X md. 5; Ek V-A md. 8", "k": "Dosya örneklemesi"}, {"no": "G.1", "sec": "G", "t": "Sertifika sonrası birimde değişiklik bildirilirse yeniden doğrulama gereği değerlendiriliyor; sertifikanın geri çekilmesi/kısıtlanması kriterleri tanımlı.", "d": "ISO/IEC 17065 md. 7.10, 7.11; Md. 38(3)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "G.2", "sec": "G", "t": "Piyasa gözetim otoritelerinden gelen bilgi talepleri ve Md. 43(1) bildirimleri ele alınıyor ve bildirim otoritesine iletiliyor.", "d": "(AB) 2023/1230 Md. 40(1)(c), Md. 43(1)", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "H.1", "sec": "H", "t": "Kayıt saklama süresi prosedürde tanımlı ve imalatçının 10 yıllık saklama süresiyle uyumlu (Ek X OK için süre öngörmez).", "d": "ISO/IEC 17065 md. 7.12; Ek X md. 2.1, 4", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "H.2", "sec": "H", "t": "Reddedilen, kısıtlanan, askıya alınan veya geri çekilen birim doğrulama sertifikaları bildirim otoritesine bildiriliyor.", "d": "(AB) 2023/1230 Md. 40(1)(a)", "k": "Kayıt incelemesi"}, {"no": "H.3", "sec": "H", "t": "Aynı ürünleri değerlendiren diğer OK'lere olumsuz ve talep hâlinde olumlu sonuçlar hakkında bilgi veriliyor.", "d": "(AB) 2023/1230 Md. 40(2)", "k": "Kayıt incelemesi"}, {"no": "H.4", "sec": "H", "t": "İmalatçının teknik dosya ve sertifikaları piyasaya arzdan sonra en az 10 yıl saklama yükümlülüğü müşteriye bildiriliyor (iyi uygulama).", "d": "Ek X md. 2.1, 4", "k": "Dosya örneklemesi"}, {"no": "H.5", "sec": "H", "t": "Gizlilik ve mülkiyet haklarının korunması güvence altında.", "d": "(AB) 2023/1230 Md. 30(10)", "k": "Prosedür incelemesi + Mülakat"}, {"no": "H.6", "sec": "H", "t": "OK, NB-M koordinasyon grubu çalışmalarına katılıyor veya personeli bilgilendiriliyor; idari kararlar prosedürlere işlenmiş.", "d": "(AB) 2023/1230 Md. 30(11), Md. 42", "k": "Prosedür incelemesi + Kayıt incelemesi + Mülakat"}], "tanik": {"faaliyet": "Birim üzerinde inceleme ve deneyler (imalatçı tesisi veya kurulum yeri)", "grup": "G veya (B* + F1) veya (B* + F)", "not": "G tanığı, Tablo 2'ye göre B modülü için de gruplama seçeneğidir."}}, {"id": "M-IX", "code": "M3", "grup": "makine", "yon": "makine", "ad": "Makine Modül H (Ek IX)", "baslik": "EK IX — TAM KALİTE GÜVENCESİNE DAYALI UYGUNLUK (MODÜL H)", "ozet": [["Ürün", "Ek I Bölüm A ve B makine ve ilgili ürünler — tasarım, imalat ve son muayene/deneyi kapsayan onaylı kalite sistemi"], ["Direktif dayanağı", "(AB) 2023/1230 Md. 25(2)(b) ve 25(3)(c)"], ["Başvuran / OK çıktısı", "İmalatçı veya yetkili temsilcisi / kalite sistemi onay kararı; OK kimlik numarası her üründe CE yanında"], ["Akreditasyon (EA-2/17 M:2026)", "EN ISO/IEC 17021-1 · qa + cd + pk · kabul edilmeyen: 17024, 17025, 17029"], ["Tanık gruplaması", "Tablo 2: H ← H veya H1"], ["Saklama süreleri", "OK: Ek IX süre öngörmez — ISO/IEC 17021-1 md. 9.9 uyarınca prosedürde · İmalatçı: 10 yıl (md. 6)"]], "items": [{"no": "A.1", "sec": "A", "t": "Kuruluş bu modül (Ek IX — Modül H) için EN ISO/IEC 17021-1 esas alınarak akredite edilmiş/denetleniyor mu? Farklı bir standart (ör. ISO/IEC 17065) kullanılıyorsa bildirim otoritesinin yayımlanmış bağlayıcı gerekliliğine dayanan gerekçe AK tarafından kayda alınmış mı?", "d": "EA-2/17 M:2026 §4.2, Annex A Tablo 1 (Modül H)", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "A.2", "sec": "A", "t": "Bu modül için kabul edilmeyen standartlar (ISO/IEC 17024, 17025, 17029) akreditasyon dayanağı olarak kullanılmıyor.", "d": "EA-2/17 M:2026 Annex A Tablo 1", "k": "Kayıt incelemesi"}, {"no": "A.3", "sec": "A", "t": "'qa' gerekliliği: EN ISO/IEC 17021-1 md. 7.1.1, 7.1.2, 7.2.4, 7.2.5, 7.2.8, 7.2.10 ve 9.1–9.4, 9.6 (denetçi yetkinliği, denetim programı, planlama, yürütme, gözetim) karşılanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (qa)", "k": "Prosedür incelemesi + Kayıt incelemesi + Dosya örneklemesi"}, {"no": "A.4", "sec": "A", "t": "'cd' gerekliliği: EN ISO/IEC 17065 md. 4.1.2, 4.1.3, 7.5 ve 7.6'nın (anlaşma, işaret kullanımı, gözden geçirme ve karar) bu modül için ayrıca kanıtlandığı doğrulanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (cd)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "A.5", "sec": "A", "t": "'pk' gerekliliği: ürün bilgisine dayalı mesleki yargı — EN ISO/IEC 17020 md. 6.1.2, 6.1.3, 6.1.6–6.1.10 denetim ekibindeki makine teknik uzmanları için kanıtlanmalı.", "d": "EA-2/17 M:2026 Annex A anahtarı (pk)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "A.6", "sec": "A", "t": "17021-1 ile akreditasyonda ilgili IAF MD dokümanlarına (ör. IAF MD 5 denetim süresi) tam uyuluyor; NB-M koordinasyon grubu gerekliliğiyle çelişki varsa grup gerekliliği uygulanıyor.", "d": "EA-2/17 M:2026 Annex A Not 4, Not 5", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "A.7", "sec": "A", "t": "Kapsam ifadesi: (AB) 2023/1230, Ek IX — Modül H ve Ek I Bölüm A / Bölüm B kategori numaraları NANDO ile uyumlu şekilde yazılmış.", "d": "EA-2/17 M:2026 §5; EA-2/17 S2:2026; ISO/IEC 17011 md. 7.8", "k": "Kayıt incelemesi"}, {"no": "A.8", "sec": "A", "t": "Akreditasyon kapsamı ile bildirim (NANDO) kapsamı tutarlı; bildirim dışı kategori için onay kararı verilmemiş.", "d": "(AB) 2023/1230 Md. 34(3), Md. 38(1)", "k": "Kayıt incelemesi + Dosya örneklemesi"}, {"no": "A.9", "sec": "A", "t": "Tanık planı: tasarım dahil kalite sistemi denetiminin (ilk veya gözetim) imalatçı tesisinde tanıkla değerlendirilmesi planlanmış; kapsamdaki farklı kategori grupları için ek tanık veya dosya incelemesi düşünülmüş.", "d": "EA-2/17 M:2026 Annex B Tablo 2 (H ← H veya H1)", "k": "Kayıt incelemesi"}, {"no": "A.10", "sec": "A", "t": "İlk akreditasyonda tanık denetimi ertelendiyse 18 ay içinde tamamlandığı ve tanık öncesi akredite onay kararı verilmediği doğrulanmış.", "d": "EA-2/17 M:2026 Annex B (18 ay kuralı)", "k": "Kayıt incelemesi"}, {"no": "B.1", "sec": "B", "t": "Başvuru imalatçı veya yetkili temsilcisi tarafından yapılıyor; yetki belgesi Ek IX md. 3.1, 3.5, 5 ve 6 yükümlülüklerini kapsıyor.", "d": "Ek IX md. 3.1(a), 8", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.2", "sec": "B", "t": "Başvuru, üretilmesi planlanan her kategoriden bir model için Ek IV-A (a)–(g), (i)–(k) ve (m)–(o) bentlerini içeren teknik dosyayı ve kalite sistemi dokümantasyonunu içeriyor.", "d": "Ek IX md. 3.1(b)–(c)", "k": "Dosya örneklemesi"}, {"no": "B.3", "sec": "B", "t": "Aynı başvurunun başka bir onaylanmış kuruluşa yapılmadığına dair yazılı beyan alınmış.", "d": "Ek IX md. 3.1(d)", "k": "Dosya örneklemesi"}, {"no": "B.4", "sec": "B", "t": "Başvurunun gözden geçirilmesinde Ek I kategorileri, Md. 25'e uygunluk, sahalar (tasarım, imalat, deney, depolama), denetim süresi, yetkinlik ve tarafsızlık riski değerlendiriliyor.", "d": "(AB) 2023/1230 Md. 25, Md. 30(6); ISO/IEC 17021-1 md. 9.1.2", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "B.5", "sec": "B", "t": "Sözleşmede OK'nin ve AK'nin tasarım, imalat, muayene, deney ve depolama yerlerine erişimi ile habersiz ziyaret hakkı yazılı.", "d": "Ek IX md. 4.2, 4.4; ISO/IEC 17065 md. 4.1.2", "k": "Dosya örneklemesi"}, {"no": "B.6", "sec": "B", "t": "Alt yüklenici veya bağlı kuruluş kullanılacaksa müşterinin onayı alınmış.", "d": "(AB) 2023/1230 Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "B.7", "sec": "B", "t": "Orantılılık ve KOBİ'lere yönelik ücretlendirme dikkate alınmış; koruma düzeyinden taviz verilmemiş.", "d": "(AB) 2023/1230 Md. 38(2), Md. 25(5)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "C1.1", "sec": "C1", "t": "KS dokümantasyonunun tüm unsurları yazılı politika, prosedür ve talimatlarla sistematik ve tutarlı yorumlanabilir biçimde belgelendiği değerlendirilmiş.", "d": "Ek IX md. 3.2", "k": "Dosya örneklemesi"}, {"no": "C1.2", "sec": "C1", "t": "Kalite hedefleri, organizasyon yapısı ve yönetimin tasarım ve ürün kalitesine ilişkin sorumluluk ve yetkileri değerlendirilmiş.", "d": "Ek IX md. 3.2(a)", "k": "Dosya örneklemesi"}, {"no": "C1.3", "sec": "C1", "t": "Uygulanacak teknik tasarım spesifikasyonları ve standartlar; standart / ortak spesifikasyon tam uygulanmayacaksa TSGİ'lerin karşılanma yolları değerlendirilmiş.", "d": "Ek IX md. 3.2(b)", "k": "Dosya örneklemesi"}, {"no": "C1.4", "sec": "C1", "t": "Tasarım kontrolü ve tasarım doğrulama teknikleri, süreçleri ve sistematik faaliyetleri değerlendirilmiş.", "d": "Ek IX md. 3.2(c)", "k": "Dosya örneklemesi"}, {"no": "C1.5", "sec": "C1", "t": "İmalat, kalite kontrol ve kalite güvence teknikleri, süreçleri ve sistematik faaliyetleri değerlendirilmiş.", "d": "Ek IX md. 3.2(d)", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C1.6", "sec": "C1", "t": "İmalat öncesi, sırası ve sonrası muayene ve deneyler ile sıklıkları değerlendirilmiş.", "d": "Ek IX md. 3.2(e)", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C1.7", "sec": "C1", "t": "Kalite kayıtları (muayene raporları, deney ve kalibrasyon verileri, personel yeterlilik raporları) değerlendirilmiş.", "d": "Ek IX md. 3.2(f)", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C1.8", "sec": "C1", "t": "Hedeflenen tasarım ve ürün kalitesine ulaşımın ve KS'nin etkin işleyişinin izlenme yöntemleri değerlendirilmiş.", "d": "Ek IX md. 3.2(g)", "k": "Dosya örneklemesi"}, {"no": "C1.9", "sec": "C1", "t": "İlgili uyumlaştırılmış standarda (ör. EN ISO 9001) uyan KS unsurları için uygunluk varsayımı doğru uygulanmış; ürün güvenliğine özgü unsurlar ayrıca değerlendirilmiş.", "d": "Ek IX md. 3.3 2. paragraf", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C1.10", "sec": "C1", "t": "Denetim ekibinde KYS deneyimine ek olarak ilgili makine alanı ve teknolojisinde değerlendirici deneyimi ve Ek III TSGİ bilgisi olan en az bir üye bulunuyor.", "d": "Ek IX md. 3.3 3. paragraf", "k": "Kayıt incelemesi + Tanık denetimi"}, {"no": "C1.11", "sec": "C1", "t": "Denetim imalatçının tesisine değerlendirme ziyaretini içeriyor; birden fazla saha varsa örnekleme gerekçeli.", "d": "Ek IX md. 3.3; ISO/IEC 17021-1 md. 9.1.5 / IAF MD 1", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C1.12", "sec": "C1", "t": "Denetim programı, planı ve yürütülmesi (açılış, kanıt toplama, bulgular, kapanış) ISO/IEC 17021-1 gerekliliklerine uygun.", "d": "ISO/IEC 17021-1 md. 9.1–9.4 (qa)", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "C1.13", "sec": "C1", "t": "Karar, denetim sonuçları ve gerekçeli değerlendirme kararıyla imalatçıya / Yİ'ye bildiriliyor.", "d": "Ek IX md. 3.3 son paragraf", "k": "Dosya örneklemesi"}, {"no": "C2.1", "sec": "C2", "t": "Ekip, 3.1(b) teknik dosyasını inceleyerek imalatçının uygulanabilir TSGİ'leri belirleme ve uygunluğu sağlamak için gerekli incelemeleri yapma yeteneğini doğrulamış (risk değerlendirmesi, koruyucu önlemler, artık riskler).", "d": "Ek IX md. 3.3 3. paragraf", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C2.2", "sec": "C2", "t": "Standart dışı çözümler için imalatçının tasarım doğrulama kayıtları ve deney sonuçları incelenmiş; çözümlerin TSGİ'leri karşıladığına ilişkin gerekçe değerlendirilmiş.", "d": "Ek IX md. 3.2(b)–(c); EA-2/17 M:2026 §6", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C2.3", "sec": "C2", "t": "Güvenlik işlevi sağlayan yazılım ve makine öğrenimi içeren ürünlerde imalatçının geliştirme, veri, deney ve doğrulama süreçleri KS kapsamında değerlendirilmiş (Ek III 1.1.9, 1.2.1).", "d": "Ek IV-A (n); Ek III 1.1.9, 1.2.1", "k": "Dosya örneklemesi + Mülakat"}, {"no": "C2.4", "sec": "C2", "t": "Kategori başına seçilen model dosyasının, KS kapsamındaki diğer modeller için temsil edici olduğu gerekçelendirilmiş.", "d": "Ek IX md. 3.1(b)", "k": "Dosya örneklemesi"}, {"no": "D.1", "sec": "D", "t": "KYS denetçilerinin ve teknik uzmanların yetkinlik kriterleri, yetkilendirme ve izlenmesi tanımlı ve kayıtlı.", "d": "ISO/IEC 17021-1 md. 7.1.1, 7.1.2, 7.2.4, 7.2.5, 7.2.8, 7.2.10 (qa)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "D.2", "sec": "D", "t": "Teknik uzmanlar Ek I kategorileri, Ek III TSGİ ve ilgili uyumlaştırılmış standartlar konusunda yetkin.", "d": "Md. 30(7)(c); ISO/IEC 17020 md. 6.1.2–6.1.3 (pk)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "E.1", "sec": "E", "t": "Denetim raporu bulguları, kanıtları ve sonucu açıkça kaydediyor ve imalatçıya veriliyor.", "d": "Ek IX md. 4.3; ISO/IEC 17021-1 md. 9.4.8", "k": "Dosya örneklemesi"}, {"no": "E.2", "sec": "E", "t": "Onay kararı denetimi yapmamış yetkin kişi(ler)ce veriliyor; uygunsuzlukların düzeltildiği ve etkinliği doğrulanmış.", "d": "ISO/IEC 17021-1 md. 9.4.9, 9.5; ISO/IEC 17065 md. 7.6 (cd)", "k": "Dosya örneklemesi + Kayıt incelemesi"}, {"no": "E.3", "sec": "E", "t": "TSGİ veya standart / ortak spesifikasyon karşılanmadığında düzeltici faaliyet isteniyor ve KS onay kararı verilmiyor.", "d": "(AB) 2023/1230 Md. 38(3)", "k": "Dosya örneklemesi"}, {"no": "E.4", "sec": "E", "t": "OK kararlarına karşı şeffaf ve erişilebilir itiraz prosedürü mevcut.", "d": "(AB) 2023/1230 Md. 39; ISO/IEC 17021-1 md. 9.7", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "F.1", "sec": "F", "t": "KS onay kararı kapsamı (Ek I kategorileri/modeller, sahalar), geçerlilik koşulları ve gözetim yükümlülüklerini açıkça tanımlıyor.", "d": "Ek IX md. 3.3; ISO/IEC 17021-1 md. 8.2", "k": "Dosya örneklemesi"}, {"no": "F.2", "sec": "F", "t": "CE işareti yanında her ürüne OK kimlik numarasının OK'nin sorumluluğunda konması kuralları müşteriye bildirilmiş ve uygulaması gözetimde kontrol ediliyor.", "d": "Ek IX md. 5.1; Md. 24(3); ISO/IEC 17065 md. 4.1.3", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "F.3", "sec": "F", "t": "Müşteriye AB uygunluk beyanında OK adı/numarası ve Modül H atfı ile 10 yıllık saklama yükümlülüklerine ilişkin bilgi veriliyor (iyi uygulama).", "d": "Ek IX md. 5.2, 6; Ek V-A md. 8", "k": "Dosya örneklemesi"}, {"no": "G.1", "sec": "G", "t": "Planlanan KS değişiklikleri değerlendiriliyor; değişen sistemin şartları karşılamaya devam edip etmediğine veya yeniden değerlendirme gerektiğine dair gerekçeli karar imalatçıya bildiriliyor.", "d": "Ek IX md. 3.5", "k": "Dosya örneklemesi"}, {"no": "G.2", "sec": "G", "t": "Periyodik gözetim denetimleri yapılıyor (sıklık prosedürde tanımlı; en az yılda bir) ve imalatçıya denetim raporu veriliyor.", "d": "Ek IX md. 4.3; ISO/IEC 17021-1 md. 9.6.2", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "G.3", "sec": "G", "t": "Gözetimde tasarım kayıtları (analiz, hesap, deney) ve imalat kayıtları (muayene, deney, kalibrasyon, personel yeterliliği) örneklenerek inceleniyor.", "d": "Ek IX md. 4.2(a)–(c)", "k": "Dosya örneklemesi + Tanık denetimi"}, {"no": "G.4", "sec": "G", "t": "Habersiz ziyaret politikası tanımlı; ziyaret yapıldığında ziyaret raporu, ürün deneyi yapıldığında deney raporu veriliyor.", "d": "Ek IX md. 4.4", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "G.5", "sec": "G", "t": "Onay sonrası ürünün uygunluğunu yitirdiği tespit edilirse düzeltici faaliyet isteniyor; gerekirse onay askıya alınıyor, kısıtlanıyor veya geri çekiliyor.", "d": "(AB) 2023/1230 Md. 38(4); ISO/IEC 17021-1 md. 9.6.5", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "G.6", "sec": "G", "t": "Onayın geçerlilik süresi ve yeniden belgelendirme süreci prosedürde tanımlı (Ek IX süre öngörmez).", "d": "ISO/IEC 17021-1 md. 9.6.3", "k": "Prosedür incelemesi"}, {"no": "G.7", "sec": "G", "t": "Uyumlaştırılmış standart / ortak spesifikasyon değişikliklerinin onaylı KS kapsamındaki ürünlere etkisi gözetimde değerlendiriliyor.", "d": "Ek IX md. 3.2(b); Md. 30(11)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "H.1", "sec": "H", "t": "Kayıt saklama süresi prosedürde tanımlı ve imalatçının 10 yıllık saklama süresiyle uyumlu (Ek IX OK için süre öngörmez).", "d": "ISO/IEC 17021-1 md. 9.9; Ek IX md. 6", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "H.2", "sec": "H", "t": "Verilen/geri çekilen KS onayları bildirim otoritesine bildiriliyor; reddedilen, askıya alınan veya kısıtlananların listesi periyodik olarak veya talep üzerine sunuluyor.", "d": "Ek IX md. 7; Md. 40(1)(a)", "k": "Kayıt incelemesi"}, {"no": "H.3", "sec": "H", "t": "Diğer OK'lere reddedilen, askıya alınan veya geri çekilen onaylar bildiriliyor; talep hâlinde verilen onaylar hakkında bilgi veriliyor.", "d": "Ek IX md. 7; Md. 40(2)", "k": "Kayıt incelemesi"}, {"no": "H.4", "sec": "H", "t": "İmalatçının teknik dosya, KS dokümantasyonu, onaylı değişiklikler ve OK karar/raporlarını 10 yıl saklama yükümlülüğü müşteriye bildiriliyor (iyi uygulama).", "d": "Ek IX md. 6", "k": "Dosya örneklemesi"}, {"no": "H.5", "sec": "H", "t": "Gizlilik ve mülkiyet haklarının korunması güvence altında.", "d": "(AB) 2023/1230 Md. 30(10)", "k": "Prosedür incelemesi + Mülakat"}, {"no": "H.6", "sec": "H", "t": "OK, NB-M koordinasyon grubu çalışmalarına katılıyor veya personeli bilgilendiriliyor; idari kararlar prosedürlere işlenmiş.", "d": "(AB) 2023/1230 Md. 30(11), Md. 42", "k": "Prosedür incelemesi + Kayıt incelemesi + Mülakat"}], "tanik": {"faaliyet": "Tasarım dahil KS denetimi (ilk veya gözetim) — imalatçı tesisi", "grup": "H veya H1", "not": "Modül H'de tip sertifikası yoktur; tasarım değerlendirmesi KS denetimi kapsamında teknik dosya incelemesiyle yapılır (Ek IX md. 3.3)."}}], "ortak": [{"no": "O.1", "sec": "Hukuki statü ve bağımsızlık", "t": "Kuruluş bir üye devlet (Türkiye) mevzuatına göre kurulmuş ve tüzel kişiliğe sahip.", "d": "2014/33/AB Md. 24(2)", "k": "Kayıt incelemesi"}, {"no": "O.2", "sec": "Hukuki statü ve bağımsızlık", "t": "Kuruluş, değerlendirdiği kuruluş veya ürünlerden bağımsız üçüncü taraf; sektör birliği/meslek federasyonuna bağlıysa bağımsızlık ve çıkar çatışması yokluğu kanıtlanmış.", "d": "Md. 24(3)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "O.3", "sec": "Hukuki statü ve bağımsızlık", "t": "Kuruluş, üst yönetimi ve personeli değerlendirdikleri asansör/aksamların tasarımcısı, imalatçısı, tedarikçisi, monte edeni, alıcısı, sahibi, kullanıcısı veya bakımcısı ya da bunların temsilcisi değil.", "d": "Md. 24(4) 1. paragraf", "k": "Kayıt incelemesi + Mülakat"}, {"no": "O.4", "sec": "Hukuki statü ve bağımsızlık", "t": "Tasarım, imalat, pazarlama, montaj, kullanım veya bakım faaliyetlerinde doğrudan yer alınmıyor; özellikle danışmanlık hizmeti verilmiyor.", "d": "Md. 24(4) 2. paragraf", "k": "Kayıt incelemesi + Mülakat"}, {"no": "O.5", "sec": "Hukuki statü ve bağımsızlık", "t": "Bağlı kuruluş ve alt yüklenici faaliyetlerinin gizlilik, tarafsızlık ve objektifliği etkilemediği güvence altında.", "d": "Md. 24(4) son paragraf", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "O.6", "sec": "Hukuki statü ve bağımsızlık", "t": "Tarafsızlık risk analizi asansör sektörüne özgü ilişkileri (bakım firmaları, monte edenlerle ortaklıklar, eski çalışanlar) kapsıyor ve güncel.", "d": "Md. 24(8); ISO/IEC 17065 md. 4.2 / 17021-1 md. 5.2 / 17020 md. 4.1", "k": "Kayıt incelemesi + Mülakat"}, {"no": "O.7", "sec": "Hukuki statü ve bağımsızlık", "t": "Üst yönetim ve değerlendirme personelinin ücreti değerlendirme sayısına veya sonuçlarına bağlı değil.", "d": "Md. 24(8)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "O.8", "sec": "Hukuki statü ve bağımsızlık", "t": "Personel, kararlarını etkileyebilecek mali ve diğer baskılardan bağımsız; baskı/teşvik bildirim mekanizması var.", "d": "Md. 24(5)", "k": "Prosedür incelemesi + Mülakat"}, {"no": "O.9", "sec": "Kaynaklar, prosedürler ve sigorta", "t": "Bildirildiği her prosedür ve her asansör/aksam kategorisi için yeterli personel, prosedür ve ekipman her zaman mevcut.", "d": "Md. 24(6)", "k": "Kayıt incelemesi"}, {"no": "O.10", "sec": "Kaynaklar, prosedürler ve sigorta", "t": "Değerlendirme prosedürleri şeffaf ve tekrarlanabilir; OK görevleri ile diğer faaliyetler ayrıştırılmış.", "d": "Md. 24(6)(b)", "k": "Prosedür incelemesi"}, {"no": "O.11", "sec": "Kaynaklar, prosedürler ve sigorta", "t": "İşletmenin büyüklüğü, sektör, yapı, teknolojinin karmaşıklığı ve üretimin seri/kütle niteliğini dikkate alan prosedürler mevcut.", "d": "Md. 24(6)(c), Md. 32(2)", "k": "Prosedür incelemesi"}, {"no": "O.12", "sec": "Kaynaklar, prosedürler ve sigorta", "t": "Mesleki sorumluluk sigortası yürürlükte ve kapsam/limit faaliyetlerle orantılı.", "d": "Md. 24(9)", "k": "Kayıt incelemesi"}, {"no": "O.13", "sec": "Personel yetkinliği", "t": "Personel bildirildiği tüm faaliyetleri kapsayan sağlam teknik ve mesleki eğitime sahip.", "d": "Md. 24(7)(a)", "k": "Kayıt incelemesi"}, {"no": "O.14", "sec": "Personel yetkinliği", "t": "Personel yaptığı değerlendirmelerin şartlarını yeterince biliyor ve yeterli yetkiye sahip.", "d": "Md. 24(7)(b)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "O.15", "sec": "Personel yetkinliği", "t": "Personel Ek I TSGG, uygulanabilir uyumlaştırılmış standartlar (EN 81-20/50, EN ISO 8100-1/-2, EN 81-21/-28/-70/-71/-72/-73/-77 vb.), Birlik mevzuatı ve ulusal mevzuat (Asansör Yönetmeliği) bilgisine sahip.", "d": "Md. 24(7)(c)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "O.16", "sec": "Personel yetkinliği", "t": "Personel değerlendirmelerin yapıldığını gösteren belge, kayıt ve raporları düzenleyebiliyor.", "d": "Md. 24(7)(d)", "k": "Dosya örneklemesi"}, {"no": "O.17", "sec": "Personel yetkinliği", "t": "Standart revizyonları (EN 81-20/50 → EN ISO 8100-1/-2) ve yeni RfU'lar için personel bilgilendirme/eğitim kayıtları mevcut.", "d": "Md. 24(11)", "k": "Kayıt incelemesi"}, {"no": "O.18", "sec": "Gizlilik, standardizasyon ve koordinasyon", "t": "Personel, Ek IV–XII görevleri sırasında elde edilen bilgiler için meslekî sır yükümlülüğüne uyuyor (yetkili makamlar hariç); mülkiyet hakları korunuyor.", "d": "Md. 24(10)", "k": "Prosedür incelemesi + Mülakat"}, {"no": "O.19", "sec": "Gizlilik, standardizasyon ve koordinasyon", "t": "Kuruluş ilgili standardizasyon faaliyetlerine ve NB-L Koordinasyon Grubu çalışmalarına katılıyor veya personelini bilgilendiriyor; grubun idari kararlarını ve dokümanlarını genel kılavuz olarak uyguluyor.", "d": "Md. 24(11), Md. 36", "k": "Kayıt incelemesi + Mülakat"}, {"no": "O.20", "sec": "Alt yüklenicilik ve bağlı kuruluşlar", "t": "Alt yüklenici veya bağlı kuruluşun Md. 24 şartlarını karşıladığı sağlanmış ve bildirim otoritesine bilgi verilmiş.", "d": "Md. 26(1)", "k": "Kayıt incelemesi"}, {"no": "O.21", "sec": "Alt yüklenicilik ve bağlı kuruluşlar", "t": "Alt yüklenici/bağlı kuruluş işlerinin tam sorumluluğu OK'da.", "d": "Md. 26(2)", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "O.22", "sec": "Alt yüklenicilik ve bağlı kuruluşlar", "t": "Alt yüklenicilik yalnız müşteri onayıyla yapılıyor.", "d": "Md. 26(3)", "k": "Dosya örneklemesi"}, {"no": "O.23", "sec": "Alt yüklenicilik ve bağlı kuruluşlar", "t": "Alt yüklenici niteliklerinin değerlendirmesine ve yaptıkları işe ilişkin belgeler bildirim otoritesinin erişimine hazır.", "d": "Md. 26(4)", "k": "Kayıt incelemesi"}, {"no": "O.24", "sec": "Operasyonel yükümlülükler", "t": "Değerlendirmeler yalnız Md. 15 ve Md. 16'da öngörülen prosedürlere göre yapılıyor.", "d": "Md. 32(1)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "O.25", "sec": "Operasyonel yükümlülükler", "t": "Uygunsuzlukta düzeltici faaliyet isteniyor ve belge düzenlenmiyor.", "d": "Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "O.26", "sec": "Operasyonel yükümlülükler", "t": "Belge sonrası izlemede uygunsuzluk tespit edilirse düzeltici faaliyet isteniyor; gerekirse belge askıya alınıyor/geri çekiliyor.", "d": "Md. 32(4)", "k": "Dosya örneklemesi"}, {"no": "O.27", "sec": "Operasyonel yükümlülükler", "t": "Düzeltici faaliyet yapılmaz veya etkisiz kalırsa belgeler/onaylar kısıtlanıyor, askıya alınıyor veya geri çekiliyor.", "d": "Md. 32(5)", "k": "Dosya örneklemesi"}, {"no": "O.28", "sec": "Operasyonel yükümlülükler", "t": "OK kararlarına karşı itiraz prosedürü mevcut.", "d": "Md. 33", "k": "Prosedür incelemesi"}, {"no": "O.29", "sec": "Bilgi verme yükümlülükleri", "t": "Bildirim otoritesine belge ret, kısıtlama, askı veya geri çekme; bildirim kapsamını etkileyen durumlar; piyasa gözetim otoritelerinden gelen bilgi talepleri ve kapsam içindeki faaliyetler (sınır ötesi dâhil) bildiriliyor.", "d": "Md. 34(1)", "k": "Kayıt incelemesi"}, {"no": "O.30", "sec": "Bilgi verme yükümlülükleri", "t": "Aynı asansör/aksamları değerlendiren diğer OK'lara olumsuz ve talep hâlinde olumlu sonuçlar hakkında bilgi veriliyor.", "d": "Md. 34(2)", "k": "Kayıt incelemesi"}, {"no": "O.31", "sec": "Bilgi verme yükümlülükleri", "t": "Bildirim kapsamı daralır, askıya alınır veya geri çekilirse dosyaların başka OK'ya devri veya makamların erişimine hazır tutulması için düzenleme mevcut.", "d": "Md. 30(2)", "k": "Prosedür incelemesi"}], "ortakMakine": [{"no": "OM.1", "sec": "Hukuki statü ve bağımsızlık", "t": "Kuruluş bir üye devlet (Türkiye) mevzuatına göre kurulmuş ve tüzel kişiliğe sahip.", "d": "(AB) 2023/1230 Md. 30(2)", "k": "Kayıt incelemesi"}, {"no": "OM.2", "sec": "Hukuki statü ve bağımsızlık", "t": "Kuruluş, değerlendirdiği kuruluş veya makinelerden bağımsız üçüncü taraf; sektör birliği/meslek federasyonuna bağlıysa bağımsızlık ve çıkar çatışması yokluğu kanıtlanmış.", "d": "Md. 30(3)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "OM.3", "sec": "Hukuki statü ve bağımsızlık", "t": "Kuruluş, üst yönetimi ve personeli değerlendirdikleri makinelerin (ve bunlara dahil edilen kısmen tamamlanmış makinelerin) tasarımcısı, imalatçısı, tedarikçisi, ithalatçısı, dağıtıcısı, kurucusu, alıcısı, sahibi, kullanıcısı veya bakımcısı ya da bunların temsilcisi değil.", "d": "Md. 30(4) 1. paragraf", "k": "Kayıt incelemesi + Mülakat"}, {"no": "OM.4", "sec": "Hukuki statü ve bağımsızlık", "t": "Tasarım, ithalat, dağıtım, imalat, pazarlama, kurulum, kullanım veya bakım faaliyetlerinde doğrudan yer alınmıyor; özellikle danışmanlık hizmeti verilmiyor.", "d": "Md. 30(4) 2. paragraf", "k": "Kayıt incelemesi + Mülakat"}, {"no": "OM.5", "sec": "Hukuki statü ve bağımsızlık", "t": "Bağlı kuruluş ve alt yüklenici faaliyetlerinin gizlilik, tarafsızlık ve objektifliği etkilemediği güvence altında.", "d": "Md. 30(4) son paragraf", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "OM.6", "sec": "Hukuki statü ve bağımsızlık", "t": "Tarafsızlık risk analizi makine sektörüne özgü ilişkileri (imalatçı/ithalatçı ortaklıkları, eğitim ve danışmanlık firmaları, eski çalışanlar) kapsıyor ve güncel.", "d": "Md. 30(8); ISO/IEC 17065 md. 4.2 / 17021-1 md. 5.2", "k": "Kayıt incelemesi + Mülakat"}, {"no": "OM.7", "sec": "Hukuki statü ve bağımsızlık", "t": "Üst yönetim ve değerlendirme personelinin ücreti değerlendirme sayısına veya sonuçlarına bağlı değil.", "d": "Md. 30(8) 2. paragraf", "k": "Kayıt incelemesi + Mülakat"}, {"no": "OM.8", "sec": "Hukuki statü ve bağımsızlık", "t": "Personel, kararlarını etkileyebilecek mali ve diğer baskılardan bağımsız; en yüksek mesleki dürüstlük ve teknik yetkinlikle çalışıyor.", "d": "Md. 30(5)", "k": "Prosedür incelemesi + Mülakat"}, {"no": "OM.9", "sec": "Kaynaklar, prosedürler ve sigorta", "t": "Bildirildiği her prosedür (Ek VII, IX, X) ve her makine türü/kategorisi için yeterli personel, prosedür ve ekipman her zaman mevcut.", "d": "Md. 30(6) (a)", "k": "Kayıt incelemesi"}, {"no": "OM.10", "sec": "Kaynaklar, prosedürler ve sigorta", "t": "Değerlendirme prosedürleri şeffaf ve tekrarlanabilir; OK görevleri ile diğer faaliyetler politika ve prosedürlerle ayrıştırılmış.", "d": "Md. 30(6)(b), (c)", "k": "Prosedür incelemesi"}, {"no": "OM.11", "sec": "Kaynaklar, prosedürler ve sigorta", "t": "İşletmenin büyüklüğü, sektör, yapı, teknolojinin karmaşıklığı ve üretimin seri/kütle niteliğini dikkate alan prosedürler mevcut.", "d": "Md. 30(6)(d), Md. 38(2)", "k": "Prosedür incelemesi"}, {"no": "OM.12", "sec": "Kaynaklar, prosedürler ve sigorta", "t": "Teknik ve idari görevler için gerekli araçlar ile tüm gerekli ekipman ve tesislere erişim mevcut.", "d": "Md. 30(6) son paragraf", "k": "Kayıt incelemesi + Tanık denetimi"}, {"no": "OM.13", "sec": "Kaynaklar, prosedürler ve sigorta", "t": "Mesleki sorumluluk sigortası yürürlükte ve kapsam/limit faaliyetlerle orantılı.", "d": "Md. 30(9)", "k": "Kayıt incelemesi"}, {"no": "OM.14", "sec": "Kaynaklar, prosedürler ve sigorta", "t": "Uygunluk değerlendirme ücretleri belirlenirken KOBİ'lerin özel çıkar ve ihtiyaçları dikkate alınıyor.", "d": "Md. 25(5)", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "OM.15", "sec": "Personel yetkinliği", "t": "Personel bildirildiği tüm faaliyetleri kapsayan sağlam teknik ve mesleki eğitime sahip.", "d": "Md. 30(7)(a)", "k": "Kayıt incelemesi"}, {"no": "OM.16", "sec": "Personel yetkinliği", "t": "Personel yaptığı değerlendirmelerin şartlarını yeterince biliyor ve yeterli yetkiye sahip.", "d": "Md. 30(7)(b)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "OM.17", "sec": "Personel yetkinliği", "t": "Personel Ek III TSGİ (yeni 1.1.9 ve 1.2.1 dahil), uygulanabilir uyumlaştırılmış standartlar ve ortak spesifikasyonlar, Birlik ve ulusal mevzuat hakkında uygun bilgiye sahip.", "d": "Md. 30(7)(c)", "k": "Kayıt incelemesi + Mülakat"}, {"no": "OM.18", "sec": "Personel yetkinliği", "t": "Personel değerlendirmelerin yapıldığını gösteren sertifika, kayıt ve raporları düzenleyebiliyor.", "d": "Md. 30(7)(d)", "k": "Dosya örneklemesi"}, {"no": "OM.19", "sec": "Personel yetkinliği", "t": "2006/42/AT'den (AB) 2023/1230'a geçiş (yeni Ek I yapısı, Ek III değişiklikleri, sertifika geçerliliği ve yenileme kuralları) için personel eğitim kayıtları mevcut.", "d": "Md. 30(7), 30(11)", "k": "Kayıt incelemesi"}, {"no": "OM.20", "sec": "Gizlilik, standardizasyon ve koordinasyon", "t": "Personel Ek VII, IX ve X görevleri sırasında elde edilen bilgiler için meslekî sır yükümlülüğüne uyuyor (yetkili makamlar hariç); mülkiyet hakları, fikri mülkiyet ve ticari sırlar korunuyor.", "d": "Md. 30(10)", "k": "Prosedür incelemesi + Mülakat"}, {"no": "OM.21", "sec": "Gizlilik, standardizasyon ve koordinasyon", "t": "Kuruluş ilgili standardizasyon faaliyetlerine ve Md. 42 kapsamındaki makine onaylanmış kuruluşlar koordinasyon grubuna (NB-M) katılıyor veya personelini bilgilendiriyor; grubun idari kararları ve dokümanları genel kılavuz olarak uygulanıyor.", "d": "Md. 30(11), Md. 42", "k": "Kayıt incelemesi + Mülakat"}, {"no": "OM.22", "sec": "Alt yüklenicilik ve bağlı kuruluşlar", "t": "Alt yüklenici veya bağlı kuruluşun Md. 30 şartlarını karşıladığı sağlanmış ve bildirim otoritesine bilgi verilmiş.", "d": "Md. 32(1)", "k": "Kayıt incelemesi"}, {"no": "OM.23", "sec": "Alt yüklenicilik ve bağlı kuruluşlar", "t": "Alt yüklenici/bağlı kuruluş işlerinin tam sorumluluğu, nerede yerleşik olurlarsa olsunlar, OK'de.", "d": "Md. 32(2)", "k": "Prosedür incelemesi + Kayıt incelemesi"}, {"no": "OM.24", "sec": "Alt yüklenicilik ve bağlı kuruluşlar", "t": "Alt yüklenicilik yalnız müşteri onayıyla yapılıyor.", "d": "Md. 32(3)", "k": "Dosya örneklemesi"}, {"no": "OM.25", "sec": "Alt yüklenicilik ve bağlı kuruluşlar", "t": "Alt yüklenici niteliklerinin değerlendirmesine ve Ek VII, IX, X kapsamında yaptıkları işe ilişkin belgeler bildirim otoritesinin erişimine hazır.", "d": "Md. 32(4)", "k": "Kayıt incelemesi"}, {"no": "OM.26", "sec": "Operasyonel yükümlülükler", "t": "Değerlendirmeler yalnız Ek VII, IX ve X'te öngörülen prosedürlere göre yapılıyor.", "d": "Md. 38(1)", "k": "Prosedür incelemesi + Dosya örneklemesi"}, {"no": "OM.27", "sec": "Operasyonel yükümlülükler", "t": "TSGİ veya standart/ortak spesifikasyon karşılanmadığında düzeltici faaliyet isteniyor; AB tip inceleme sertifikası, KS onay kararı veya birim doğrulama sertifikası düzenlenmiyor.", "d": "Md. 38(3)", "k": "Dosya örneklemesi"}, {"no": "OM.28", "sec": "Operasyonel yükümlülükler", "t": "Ek IX onayı sonrası izlemede uygunsuzluk tespit edilirse düzeltici faaliyet isteniyor; gerekirse onay askıya alınıyor veya geri çekiliyor; düzeltici faaliyet etkisizse kısıtlanıyor, askıya alınıyor veya geri çekiliyor.", "d": "Md. 38(4)", "k": "Dosya örneklemesi"}, {"no": "OM.29", "sec": "Operasyonel yükümlülükler", "t": "OK kararlarına karşı şeffaf ve erişilebilir itiraz prosedürü mevcut.", "d": "Md. 39", "k": "Prosedür incelemesi"}, {"no": "OM.30", "sec": "Bilgi verme yükümlülükleri", "t": "Bildirim otoritesine sertifika/onay ret, kısıtlama, askı veya geri çekme; bildirim kapsamını veya koşullarını etkileyen durumlar; piyasa gözetim otoritelerinden gelen bilgi talepleri; talep hâlinde sınır ötesi faaliyetler ve alt yüklenicilik dahil yürütülen faaliyetler bildiriliyor.", "d": "Md. 40(1)(a)–(d)", "k": "Kayıt incelemesi"}, {"no": "OM.31", "sec": "Bilgi verme yükümlülükleri", "t": "Aynı tür makineleri değerlendiren diğer OK'lere olumsuz ve talep hâlinde olumlu sonuçlar hakkında bilgi veriliyor.", "d": "Md. 40(2)", "k": "Kayıt incelemesi"}, {"no": "OM.32", "sec": "Bilgi verme yükümlülükleri", "t": "Bildirim kısıtlanır, askıya alınır, geri çekilir veya faaliyet durursa dosyaların başka OK'ye devri veya makamların erişimine hazır tutulması için düzenleme mevcut.", "d": "Md. 36(2)", "k": "Prosedür incelemesi"}], "yonetmelikler": [{"id": "asansor", "ad": "2014/33/AB Asansör Yönetmeliği", "kisa": "2014/33/AB", "alt": "Asansörler ve asansör güvenlik aksamları", "ortak": "ortak", "ortakId": "O", "ortakAd": "Ortak Şartlar", "ortakMd": "Md. 24, 26, 30, 32–34, 36", "gruplar": [{"id": "aksam", "ad": "Güvenlik Aksamları", "md": "Md. 15 · Ek IV-A, VI, VII, IX"}, {"id": "asansor", "ad": "Asansör", "md": "Md. 16 · Ek IV-B, V, VIII, X, XI, XII"}]}, {"id": "makine", "ad": "(AB) 2023/1230 Makine Tüzüğü", "kisa": "(AB) 2023/1230", "alt": "Makine ve ilgili ürünler (Ek I Bölüm A ve B)", "ortak": "ortakMakine", "ortakId": "OM", "ortakAd": "Makine Ortak Şartlar", "ortakMd": "Md. 25(5), 30, 32, 36(2), 38–40, 42", "gruplar": [{"id": "makine", "ad": "Makine ve İlgili Ürünler", "md": "Md. 25 · Ek VII, IX, X"}]}]};
